select ac_cargar_unidad($ac${"slug":"consumo-3","rama":"consumo","orden":3,"nivel":2,"titulo_es":"Economía circular","bajada_es":"Diseñar sin residuos, mantener las cosas en uso y regenerar la naturaleza: qué es la economía circular, qué la hace posible y dónde están sus límites.","objetivos_es":["Contrastar el modelo lineal con los principios de la economía circular","Distinguir el ciclo técnico del biológico y explicar por qué los ciclos internos valen más","Reconocer estrategias de ecodiseño y el derecho a reparar","Analizar modelos de negocio que venden uso en lugar de productos","Identificar los límites de la circularidad y el papel de los recuperadores urbanos"],"repasa":["consumo-1","residuos-2","residuos-3","consumo-2"],"requiere_tronco":2,"fuentes":["ellen-macarthur","emf-mariposa","circularity-gap-2025","ue-ecodiseno","ue-derecho-reparar","faccyr","rep-envases","emf-textiles"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"consumo-3.s1","orden":1,"tipo":"leccion","titulo_es":"De la línea al círculo","bajada_es":"Extraer, fabricar, usar y tirar: por qué el modelo lineal no cierra, y los tres principios de la alternativa.","minutos":10,"pasos":[{"slug":"consumo-3.s1.p1","orden":1,"grupo":"consumo-3.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El modelo lineal","cuerpo":["La mayor parte de la economía funciona en línea: se extraen materiales, se fabrican productos, se usan un tiempo y se tiran. Según el Informe sobre la Brecha de Circularidad de 2025, el mundo ya usa más de 100.000 millones de toneladas de materiales por año, y solo el 6,9 % de lo que entra a la economía proviene de materiales recuperados. En 2018, ese porcentaje era del 9,1 %: aunque se recicla más, el consumo total crece todavía más rápido."],"destacado":{"valor":"6,9 %","texto":"de los materiales que usa la economía mundial provienen de materiales recuperados, según el Informe sobre la Brecha de Circularidad 2025."}},"solucion":{}},{"slug":"consumo-3.s1.p2","orden":2,"grupo":"consumo-3.s1.p2","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de los materiales que usa la economía mundial proviene de materiales recuperados.","min":0,"max":100,"paso":0.5,"unidad":"%","escala":"lineal"},"solucion":{"valor":6.9,"banda":"lineal","explicacion":"Apenas un 6,9 %, según el informe de 2025. La economía sigue siendo casi completamente lineal."}},{"slug":"consumo-3.s1.p3","orden":3,"grupo":"consumo-3.s1.p3","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Si se recicla cada vez más, ¿por qué bajó el porcentaje de circularidad desde 2018?","opciones":[{"id":"o1","texto":"Porque el consumo total de materiales creció más rápido"},{"id":"o2","texto":"Porque se dejó de reciclar en todo el mundo"},{"id":"o3","texto":"Porque los materiales reciclados no se cuentan"},{"id":"o4","texto":"Porque se inventaron materiales imposibles de usar"}]},"solucion":{"clave":["o1"],"explicacion":"Un porcentaje puede bajar aunque su numerador suba, si el total crece más. Lo viste con porcentajes y tasas.","por_opcion":{"o3":"Se cuentan; el problema es que el total creció más."}}},{"slug":"consumo-3.s1.p4","orden":4,"grupo":"consumo-3.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una economía usa 100 mil millones de toneladas de materiales y 6,9 mil millones son recuperados, ¿qué porcentaje es circular? Redondeá a un decimal.","unidad":"%","decimales":1,"contexto":"6.9 de 100 mil millones de toneladas recuperados."},"solucion":{"valor":6.9,"tolerancia":0.1,"explicacion":"6,9 ÷ 100 × 100 ≈ 6,9 %. Para subir ese número hay que recuperar más y también usar menos en total."}},{"slug":"consumo-3.s1.p4.v2","orden":4,"grupo":"consumo-3.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una economía usa 80 mil millones de toneladas de materiales y 8 mil millones son recuperados, ¿qué porcentaje es circular? Redondeá a un decimal.","unidad":"%","decimales":1,"contexto":"8 de 80 mil millones de toneladas recuperados."},"solucion":{"valor":10,"tolerancia":0.1,"explicacion":"8 ÷ 80 × 100 ≈ 10 %. Para subir ese número hay que recuperar más y también usar menos en total."}},{"slug":"consumo-3.s1.p4.v3","orden":4,"grupo":"consumo-3.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una economía usa 120 mil millones de toneladas de materiales y 6 mil millones son recuperados, ¿qué porcentaje es circular? Redondeá a un decimal.","unidad":"%","decimales":1,"contexto":"6 de 120 mil millones de toneladas recuperados."},"solucion":{"valor":5,"tolerancia":0.1,"explicacion":"6 ÷ 120 × 100 ≈ 5 %. Para subir ese número hay que recuperar más y también usar menos en total."}},{"slug":"consumo-3.s1.p5","orden":5,"grupo":"consumo-3.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tres principios","cuerpo":["La Fundación Ellen MacArthur resume la economía circular en tres principios. Eliminar los residuos y la contaminación desde el diseño: que no existan, en lugar de gestionarlos después. Mantener los productos y materiales en uso, a su mayor valor posible. Y regenerar la naturaleza: devolver nutrientes al suelo y no solo \"dañar menos\".","No es lo mismo que reciclar más: el reciclaje es una parte, y no la primera."],"lista":["1 · Eliminar residuos y contaminación desde el diseño","2 · Mantener productos y materiales en uso, a su mayor valor","3 · Regenerar la naturaleza"]},"solucion":{}},{"slug":"consumo-3.s1.p6","orden":6,"grupo":"consumo-3.s1.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué principio aplica cada acción?","grupos":[{"id":"g1","nombre":"Eliminar desde el diseño"},{"id":"g2","nombre":"Mantener en uso"},{"id":"g3","nombre":"Regenerar"}],"items":[{"id":"i1","texto":"Un envase que no hace falta porque el producto se vende a granel"},{"id":"i2","texto":"Reparar una heladera en lugar de tirarla"},{"id":"i3","texto":"Compostar restos de comida y volver al suelo"},{"id":"i4","texto":"Un producto sin sustancias tóxicas que impidan reciclarlo"},{"id":"i5","texto":"Vender ropa de segunda mano"},{"id":"i6","texto":"Cultivar con prácticas que recuperan el suelo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Los tres principios se complementan: diseñar bien, usar mucho y devolver a la naturaleza."}},{"slug":"consumo-3.s1.p7","orden":7,"grupo":"consumo-3.s1.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Economía circular es lo mismo que reciclar más.","razones":[{"id":"r1","texto":"Porque reciclar es solo una parte, y no la primera"},{"id":"r2","texto":"Porque la economía circular prohíbe reciclar"},{"id":"r3","texto":"Porque reciclar no tiene ningún valor"}]},"solucion":{"valor":false,"explicacion":"El reciclaje es solo una parte, y no la más valiosa. Antes vienen eliminar residuos desde el diseño, reusar, reparar y compartir.","clave":["r1"]}},{"slug":"consumo-3.s1.p8","orden":8,"grupo":"consumo-3.s1.p8","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido de un producto en el modelo lineal.","items":[{"id":"i1","texto":"Se extraen materias primas"},{"id":"i2","texto":"Se fabrica el producto"},{"id":"i3","texto":"Se usa por un tiempo corto"},{"id":"i4","texto":"Se tira"},{"id":"i5","texto":"Termina enterrado, quemado o en la naturaleza"},{"id":"i6","texto":"Vuelve automáticamente a la fábrica"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"En la línea, el valor del producto y de sus materiales se pierde al final."}},{"slug":"consumo-3.s1.p9","orden":9,"grupo":"consumo-3.s1.p9","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su descripción.","izquierda":[{"id":"a1","texto":"Modelo lineal"},{"id":"a2","texto":"Economía circular"},{"id":"a3","texto":"Tasa de circularidad"},{"id":"a4","texto":"Diseño sin residuos"}],"derecha":[{"id":"b1","texto":"Extraer, fabricar, usar y tirar"},{"id":"b2","texto":"Mantener materiales en uso y regenerar"},{"id":"b3","texto":"Porcentaje de materiales recuperados"},{"id":"b4","texto":"Que el residuo no llegue a existir"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro conceptos para hablar de circularidad con precisión."}},{"slug":"consumo-3.s1.p10","orden":10,"grupo":"consumo-3.s1.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué acciones son parte de la economía circular? Marcá todas.","opciones":[{"id":"o1","texto":"Diseñar productos fáciles de reparar"},{"id":"o2","texto":"Alquilar herramientas en lugar de comprarlas"},{"id":"o3","texto":"Compostar restos orgánicos"},{"id":"o4","texto":"Comprar más cosas porque se pueden reciclar"},{"id":"o5","texto":"Fabricar productos imposibles de abrir"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Que algo sea reciclable no justifica consumir más: el primer objetivo es usar menos materiales."}},{"slug":"consumo-3.s1.p11","orden":11,"grupo":"consumo-3.s1.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué significa mantener los materiales \"a su mayor valor\"?","opciones":[{"id":"o1","texto":"Preferir usarlos como producto antes que fundirlos"},{"id":"o2","texto":"Venderlos siempre al precio más alto posible"},{"id":"o3","texto":"Guardarlos sin usar para que no se gasten"},{"id":"o4","texto":"Reciclarlos lo antes posible"}]},"solucion":{"clave":["o1"],"explicacion":"Un celular que funciona vale mucho más que los gramos de metal que se recuperan al reciclarlo.","por_opcion":{"o3":"Un objeto guardado sin uso no aporta valor."}}},{"slug":"consumo-3.s1.p12","orden":12,"grupo":"consumo-3.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La economía mundial usa más de 100.000 millones de toneladas de materiales por año."},{"id":"s2","texto":"Más de la mitad de los materiales del mundo ya son reciclados."},{"id":"s3","texto":"Uno de los principios es regenerar la naturaleza."},{"id":"s4","texto":"Si todo fuera reciclable, podríamos consumir sin límite."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La circularidad empieza por el diseño y por consumir menos, no por el tacho.","por_opcion":{"s2":"Solo el 6,9 % proviene de materiales recuperados.","s4":"Reciclar pierde material y energía; usar menos sigue siendo clave."}}},{"slug":"consumo-3.s1.p13","orden":13,"grupo":"consumo-3.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El modelo de extraer, fabricar, usar y tirar es {{0}}; según el informe de 2025, la economía mundial es circular en un {{1}} %; y el tercer principio es {{2}} la naturaleza.","banco":[{"id":"w1","texto":"lineal"},{"id":"w2","texto":"6,9"},{"id":"w3","texto":"regenerar"},{"id":"w4","texto":"circular"},{"id":"w5","texto":"69"},{"id":"w6","texto":"ignorar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las ideas de partida de la economía circular."}}]},{"slug":"consumo-3.s2","orden":2,"tipo":"leccion","titulo_es":"Los dos ciclos","bajada_es":"El diagrama de la mariposa: materiales técnicos que se mantienen en uso y materiales biológicos que vuelven al suelo.","minutos":12,"pasos":[{"slug":"consumo-3.s2.p1","orden":1,"grupo":"consumo-3.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Técnico y biológico","cuerpo":["El \"diagrama de la mariposa\" de la Fundación Ellen MacArthur muestra dos ciclos. En el ciclo biológico circulan materiales que pueden volver de forma segura a la naturaleza, como la comida, la madera sin tratar o el algodón: se aprovechan en cascada y al final se compostan o se digieren para devolver nutrientes al suelo. En el ciclo técnico circulan materiales que no se deben devolver a la naturaleza, como metales y plásticos: el objetivo es mantenerlos en uso el mayor tiempo posible."]},"solucion":{}},{"slug":"consumo-3.s2.p2","orden":2,"grupo":"consumo-3.s2.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este material pertenece al ciclo técnico o al biológico?","grupos":[{"id":"g1","nombre":"Ciclo biológico"},{"id":"g2","nombre":"Ciclo técnico"}],"items":[{"id":"i1","texto":"Restos de comida"},{"id":"i2","texto":"Aluminio de una lata"},{"id":"i3","texto":"Hojas y ramas de poda"},{"id":"i4","texto":"Plástico de una carcasa"},{"id":"i5","texto":"Madera sin tratar"},{"id":"i6","texto":"Cobre de un cable"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Mezclar los dos ciclos, por ejemplo con plásticos en el compost, arruina a ambos."}},{"slug":"consumo-3.s2.p3","orden":3,"grupo":"consumo-3.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los ciclos internos valen más","cuerpo":["En el ciclo técnico, las estrategias forman círculos de adentro hacia afuera. Los círculos más internos conservan más valor y usan menos energía: mantener y hacer durar, compartir, reutilizar y redistribuir, reacondicionar y remanufacturar, y por último reciclar. Reciclar un celular recupera algunos metales; repararlo conserva el aparato entero, con toda la energía y el trabajo que tiene incorporados."]},"solucion":{}},{"slug":"consumo-3.s2.p4","orden":4,"grupo":"consumo-3.s2.p4","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las estrategias del ciclo técnico, de la que conserva más valor a la que conserva menos.","items":[{"id":"i1","texto":"Mantener y hacer durar"},{"id":"i2","texto":"Compartir"},{"id":"i3","texto":"Reutilizar y redistribuir"},{"id":"i4","texto":"Reacondicionar y remanufacturar"},{"id":"i5","texto":"Reciclar"}],"extremos":["Más valor","Menos valor"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cuanto más cerca del usuario se cierra el ciclo, más valor se conserva."}},{"slug":"consumo-3.s2.p5","orden":5,"grupo":"consumo-3.s2.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué reparar un celular es mejor que reciclarlo?","opciones":[{"id":"o1","texto":"Conserva el aparato con toda su energía incorporada"},{"id":"o2","texto":"Porque el reciclaje de celulares está prohibido"},{"id":"o3","texto":"Porque reparar no usa ningún recurso"},{"id":"o4","texto":"Porque los celulares no tienen metales"}]},"solucion":{"clave":["o1"],"explicacion":"Lo viste con los aparatos: la mayor parte de la huella está en fabricarlos.","por_opcion":{"o3":"Usa algunos, pero muchos menos que fabricar uno nuevo."}}},{"slug":"consumo-3.s2.p6","orden":6,"grupo":"consumo-3.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reacondicionar y remanufacturar","cuerpo":["Reacondicionar es revisar, limpiar y arreglar un producto usado para volver a venderlo, como los celulares reacondicionados con garantía. Remanufacturar va más allá: se desarma el producto, se reemplazan las piezas gastadas y se vuelve a armar con calidad de nuevo, como se hace con motores, cajas de cambio o cartuchos de impresora."]},"solucion":{}},{"slug":"consumo-3.s2.p7","orden":7,"grupo":"consumo-3.s2.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada estrategia con su ejemplo.","izquierda":[{"id":"a1","texto":"Mantener"},{"id":"a2","texto":"Compartir"},{"id":"a3","texto":"Reacondicionar"},{"id":"a4","texto":"Remanufacturar"},{"id":"a5","texto":"Reciclar"}],"derecha":[{"id":"b1","texto":"Cambiar la batería de una notebook"},{"id":"b2","texto":"Una biblioteca de herramientas del barrio"},{"id":"b3","texto":"Un celular revisado y vendido con garantía"},{"id":"b4","texto":"Un motor desarmado y rearmado con piezas nuevas"},{"id":"b5","texto":"Fundir latas para hacer aluminio nuevo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Cada estrategia tiene su lugar; conviene preferir las internas cuando son posibles."}},{"slug":"consumo-3.s2.p8","orden":8,"grupo":"consumo-3.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El ciclo biológico en cascada","cuerpo":["En el ciclo biológico también hay un orden: primero se aprovecha el material para su uso de mayor valor, y luego en usos de menor valor, en cascada. Por ejemplo, la comida que sobra en un comercio puede donarse para personas; lo que no sirve para personas, para alimento animal; y lo que queda, para compost o biogás. Lo viste en la unidad de la comida que se tira."]},"solucion":{}},{"slug":"consumo-3.s2.p9","orden":9,"grupo":"consumo-3.s2.p9","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená la cascada de aprovechamiento de alimentos que sobran en un supermercado.","items":[{"id":"i1","texto":"Donarlos a personas si son aptos"},{"id":"i2","texto":"Usarlos como alimento animal"},{"id":"i3","texto":"Digerirlos para producir biogás"},{"id":"i4","texto":"Compostarlos para devolver nutrientes al suelo"}],"extremos":["Mayor valor","Menor valor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero el uso de mayor valor, y al final volver al suelo."}},{"slug":"consumo-3.s2.p10","orden":10,"grupo":"consumo-3.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fabricar un celular nuevo emite unos 80 kg de CO₂e. Repararlo, con repuesto y transporte, unos 10 kg. ¿Cuántos kg se evitan al repararlo?","unidad":"kg de CO₂e","decimales":0,"contexto":"80 kg nuevo; 10 kg reparado."},"solucion":{"valor":70,"tolerancia":1.4000000000000001,"explicacion":"80 − 10 = 70 kg de CO₂e evitados. Valores aproximados para practicar: la reparación casi siempre evita la mayor parte."}},{"slug":"consumo-3.s2.p10.v2","orden":10,"grupo":"consumo-3.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fabricar un celular nuevo emite unos 120 kg de CO₂e. Repararlo, con repuesto y transporte, unos 15 kg. ¿Cuántos kg se evitan al repararlo?","unidad":"kg de CO₂e","decimales":0,"contexto":"120 kg nuevo; 15 kg reparado."},"solucion":{"valor":105,"tolerancia":2.1,"explicacion":"120 − 15 = 105 kg de CO₂e evitados. Valores aproximados para practicar: la reparación casi siempre evita la mayor parte."}},{"slug":"consumo-3.s2.p10.v3","orden":10,"grupo":"consumo-3.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fabricar un celular nuevo emite unos 60 kg de CO₂e. Repararlo, con repuesto y transporte, unos 12 kg. ¿Cuántos kg se evitan al repararlo?","unidad":"kg de CO₂e","decimales":0,"contexto":"60 kg nuevo; 12 kg reparado."},"solucion":{"valor":48,"tolerancia":0.96,"explicacion":"60 − 12 = 48 kg de CO₂e evitados. Valores aproximados para practicar: la reparación casi siempre evita la mayor parte."}},{"slug":"consumo-3.s2.p11","orden":11,"grupo":"consumo-3.s2.p11","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un producto hecho con una mezcla de algodón y plástico pegados es fácil de circular.","razones":[{"id":"r1","texto":"Porque los materiales mezclados no pueden volver a ningún ciclo"},{"id":"r2","texto":"Porque el algodón y el plástico son el mismo material"},{"id":"r3","texto":"Porque todo lo mezclado se composta"}]},"solucion":{"valor":false,"explicacion":"Los materiales mezclados de forma inseparable no pueden volver ni al ciclo técnico ni al biológico. Por eso el diseño busca materiales puros o separables.","clave":["r1"]}},{"slug":"consumo-3.s2.p12","orden":12,"grupo":"consumo-3.s2.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En el ciclo biológico, lo primero que conviene hacer con la comida que sobra es compostarla.","razones":[{"id":"r1","texto":"Porque antes vienen usos de mayor valor, como alimentar personas"},{"id":"r2","texto":"Porque la comida nunca se composta"},{"id":"r3","texto":"Porque el compost no devuelve nutrientes"}]},"solucion":{"valor":false,"explicacion":"Primero va el uso de mayor valor: si es apta, alimentar a personas; después, a animales; y recién al final, biogás o compost.","clave":["r1"]}},{"slug":"consumo-3.s2.p13","orden":13,"grupo":"consumo-3.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los restos de comida pertenecen al ciclo biológico."},{"id":"s2","texto":"Reciclar conserva más valor que reparar."},{"id":"s3","texto":"Una biblioteca de herramientas es una forma de compartir."},{"id":"s4","texto":"Los metales deben devolverse a la naturaleza al final de su vida."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los dos ciclos tienen reglas distintas, y no conviene mezclarlos.","por_opcion":{"s2":"Reparar es un ciclo más interno y conserva más valor.","s4":"Pertenecen al ciclo técnico: deben mantenerse en uso."}}},{"slug":"consumo-3.s2.p14","orden":14,"grupo":"consumo-3.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los materiales que vuelven al suelo forman el ciclo {{0}}; los metales y plásticos, el ciclo {{1}}; y las estrategias más {{2}} conservan más valor.","banco":[{"id":"w1","texto":"biológico"},{"id":"w2","texto":"técnico"},{"id":"w3","texto":"internas"},{"id":"w4","texto":"químico"},{"id":"w5","texto":"natural"},{"id":"w6","texto":"externas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las ideas clave del diagrama de la mariposa."}},{"slug":"consumo-3.s2.p15","orden":15,"grupo":"consumo-3.s2.p15","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué estrategias del ciclo técnico son más valiosas que reciclar? Marcá todas.","opciones":[{"id":"o1","texto":"Reparar"},{"id":"o2","texto":"Reacondicionar"},{"id":"o3","texto":"Compartir"},{"id":"o4","texto":"Enterrar en un relleno"},{"id":"o5","texto":"Quemar sin recuperar energía"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Enterrar o quemar son salidas del ciclo, no estrategias circulares."}}]},{"slug":"consumo-3.s3","orden":3,"tipo":"leccion","titulo_es":"Diseñar para cerrar el ciclo","bajada_es":"Ecodiseño, piezas estándar, materiales separables y el derecho a reparar.","minutos":11,"pasos":[{"slug":"consumo-3.s3.p1","orden":1,"grupo":"consumo-3.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El diseño decide","cuerpo":["Se estima que la mayor parte del impacto ambiental de un producto queda definida en la etapa de diseño: qué materiales usa, cuánto dura, si se puede abrir, reparar, actualizar y desarmar. El ecodiseño busca que desde el primer boceto el producto sea durable, reparable y fácil de separar en materiales puros al final de su vida."]},"solucion":{}},{"slug":"consumo-3.s3.p2","orden":2,"grupo":"consumo-3.s3.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué características de diseño facilitan la circularidad? Marcá todas.","opciones":[{"id":"o1","texto":"Tornillos en lugar de pegamento"},{"id":"o2","texto":"Piezas y cargadores estándar"},{"id":"o3","texto":"Materiales puros y fáciles de separar"},{"id":"o4","texto":"Manuales y repuestos disponibles"},{"id":"o5","texto":"Baterías soldadas imposibles de cambiar"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un producto que no se puede abrir no se puede reparar ni reciclar bien."}},{"slug":"consumo-3.s3.p3","orden":3,"grupo":"consumo-3.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El derecho a reparar","cuerpo":["En 2024, la Unión Europea aprobó normas sobre el derecho a reparar: los fabricantes de ciertos productos, como lavarropas, heladeras o celulares, deben ofrecer reparación a precios razonables también después de la garantía, y si un producto se repara dentro de la garantía, esta se extiende. También aprobó un reglamento de ecodiseño que fija requisitos de durabilidad y reparabilidad, crea un pasaporte digital de productos y prohíbe destruir ropa y calzado sin vender."]},"solucion":{}},{"slug":"consumo-3.s3.p4","orden":4,"grupo":"consumo-3.s3.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada medida con lo que busca.","izquierda":[{"id":"a1","texto":"Derecho a reparar"},{"id":"a2","texto":"Pasaporte digital de productos"},{"id":"a3","texto":"Prohibir destruir ropa sin vender"},{"id":"a4","texto":"Requisitos de durabilidad"}],"derecha":[{"id":"b1","texto":"Que reparar sea posible y razonable"},{"id":"b2","texto":"Información sobre materiales y reparación"},{"id":"b3","texto":"Que no se tire lo que nunca se usó"},{"id":"b4","texto":"Que los productos duren más"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Las reglas cambian lo que conviene fabricar."}},{"slug":"consumo-3.s3.p5","orden":5,"grupo":"consumo-3.s3.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué las normas de ecodiseño son más efectivas que pedir a cada persona que repare sus cosas?","opciones":[{"id":"o1","texto":"Cambian cómo se fabrican millones de productos"},{"id":"o2","texto":"Porque las personas no saben reparar nada"},{"id":"o3","texto":"Porque reparar está prohibido para las personas"},{"id":"o4","texto":"Porque las normas eliminan la necesidad de reparar"}]},"solucion":{"clave":["o1"],"explicacion":"Lo viste en el tronco: lo individual importa, pero los sistemas deciden qué es fácil y qué es difícil.","por_opcion":{"o3":"No lo está; las normas facilitan que sea posible."}}},{"slug":"consumo-3.s3.p6","orden":6,"grupo":"consumo-3.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Obsolescencia","cuerpo":["La obsolescencia es cuando un producto deja de servir o de ser deseado antes de lo necesario. Puede ser técnica (una pieza falla y no hay repuesto), por software (el aparato deja de recibir actualizaciones), o percibida (la moda o la publicidad hacen que parezca viejo). El ecodiseño y las normas atacan las dos primeras; la tercera depende también de nuestras decisiones."]},"solucion":{}},{"slug":"consumo-3.s3.p7","orden":7,"grupo":"consumo-3.s3.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué tipo de obsolescencia es cada caso?","grupos":[{"id":"g1","nombre":"Técnica"},{"id":"g2","nombre":"Por software"},{"id":"g3","nombre":"Percibida"}],"items":[{"id":"i1","texto":"La batería falla y no se consiguen repuestos"},{"id":"i2","texto":"El celular deja de recibir actualizaciones"},{"id":"i3","texto":"Cambiar el celular porque salió un color nuevo"},{"id":"i4","texto":"Una pieza plástica interna se rompe fácilmente"},{"id":"i5","texto":"Una aplicación esencial deja de funcionar en el modelo"},{"id":"i6","texto":"Sentir que la ropa de la temporada pasada \"ya no va\""}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Cada tipo de obsolescencia tiene respuestas distintas: técnicas, legales o personales."}},{"slug":"consumo-3.s3.p8","orden":8,"grupo":"consumo-3.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un producto cuesta 300 mil pesos y dura 3 años; otro, más reparable, cuesta 450 mil y dura 6. ¿Cuántos miles de pesos por año cuesta el más durable?","unidad":"miles de pesos por año","decimales":0,"contexto":"300 mil por 3 años contra 450 mil por 6 años."},"solucion":{"valor":75,"tolerancia":1.5,"explicacion":"450 ÷ 6 = 75 mil por año, contra 100 mil del otro. El más caro al comprar resulta más barato por año de uso."}},{"slug":"consumo-3.s3.p8.v2","orden":8,"grupo":"consumo-3.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un producto cuesta 200 mil pesos y dura 2 años; otro, más reparable, cuesta 320 mil y dura 5. ¿Cuántos miles de pesos por año cuesta el más durable?","unidad":"miles de pesos por año","decimales":0,"contexto":"200 mil por 2 años contra 320 mil por 5 años."},"solucion":{"valor":64,"tolerancia":1.28,"explicacion":"320 ÷ 5 = 64 mil por año, contra 100 mil del otro. El más caro al comprar resulta más barato por año de uso."}},{"slug":"consumo-3.s3.p8.v3","orden":8,"grupo":"consumo-3.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un producto cuesta 500 mil pesos y dura 4 años; otro, más reparable, cuesta 700 mil y dura 8. ¿Cuántos miles de pesos por año cuesta el más durable?","unidad":"miles de pesos por año","decimales":1,"contexto":"500 mil por 4 años contra 700 mil por 8 años."},"solucion":{"valor":87.5,"tolerancia":1.75,"explicacion":"700 ÷ 8 = 87,5 mil por año, contra 125 mil del otro. El más caro al comprar resulta más barato por año de uso."}},{"slug":"consumo-3.s3.p9","orden":9,"grupo":"consumo-3.s3.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un diseño modular alarga la vida de una notebook.","items":[{"id":"i1","texto":"La notebook tiene memoria y batería reemplazables"},{"id":"i2","texto":"Cuando la batería se gasta, se cambia solo esa pieza"},{"id":"i3","texto":"Cuando se necesita más memoria, se agrega"},{"id":"i4","texto":"El equipo sigue sirviendo varios años más"},{"id":"i5","texto":"Se evita fabricar una notebook nueva"},{"id":"i6","texto":"La notebook se vuelve obsoleta más rápido por tener piezas"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Lo modular convierte una falla en un repuesto, no en un aparato nuevo."}},{"slug":"consumo-3.s3.p10","orden":10,"grupo":"consumo-3.s3.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un producto más barato siempre es la opción más económica.","razones":[{"id":"r1","texto":"Porque importa el costo por año de uso, no solo el precio"},{"id":"r2","texto":"Porque los productos caros duran siempre para siempre"},{"id":"r3","texto":"Porque el precio no importa nunca"}]},"solucion":{"valor":false,"explicacion":"Si dura mucho menos o no se puede reparar, el costo por año de uso puede ser mayor. Conviene mirar el costo durante toda la vida del producto.","clave":["r1"]}},{"slug":"consumo-3.s3.p11","orden":11,"grupo":"consumo-3.s3.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta publicidad de un celular y marcá lo que va contra la circularidad.","segmentos":[{"id":"s1","texto":"Batería reemplazable por el usuario."},{"id":"s2","texto":"Carcasa sellada con pegamento para que sea más fina."},{"id":"s3","texto":"Siete años de actualizaciones de software."},{"id":"s4","texto":"Cargador con conector exclusivo de la marca."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Muchas decisiones de diseño se ven en la publicidad: conviene leerlas con ojo circular.","por_opcion":{"s2":"Dificulta la reparación y el reciclaje.","s4":"Los conectores estándar evitan cargadores duplicados."}}},{"slug":"consumo-3.s3.p12","orden":12,"grupo":"consumo-3.s3.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos productos de más a menos circular por su diseño.","items":[{"id":"i1","texto":"Modular, con repuestos y manual público"},{"id":"i2","texto":"Atornillado, con repuestos solo del servicio oficial"},{"id":"i3","texto":"Pegado, reparable solo con herramientas especiales"},{"id":"i4","texto":"Sellado, con materiales mezclados imposibles de separar"}],"extremos":["Más circular","Menos circular"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El acceso a repuestos e información es tan importante como la forma física.","valores":{"i1":"muy circular","i2":"bastante","i3":"poco","i4":"nada"}}},{"slug":"consumo-3.s3.p13","orden":13,"grupo":"consumo-3.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Diseñar pensando en el ambiente desde el principio es {{0}}; cuando un producto deja de recibir actualizaciones hablamos de obsolescencia por {{1}}; y las normas europeas de 2024 impulsan el derecho a {{2}}.","banco":[{"id":"w1","texto":"ecodiseño"},{"id":"w2","texto":"software"},{"id":"w3","texto":"reparar"},{"id":"w4","texto":"rediseño"},{"id":"w5","texto":"moda"},{"id":"w6","texto":"reclamar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos para evaluar el diseño de un producto."}},{"slug":"consumo-3.s3.p14","orden":14,"grupo":"consumo-3.s3.p14","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Tu lavarropas se rompe al cuarto año. ¿Qué pregunta conviene hacer primero?","opciones":[{"id":"o1","texto":"¿Se consigue el repuesto y cuánto cuesta la reparación?"},{"id":"o2","texto":"¿Cuál es el modelo más nuevo y con más funciones?"},{"id":"o3","texto":"¿Se puede reciclar el lavarropas viejo?"},{"id":"o4","texto":"¿Qué color combina mejor con la cocina?"}]},"solucion":{"clave":["o1"],"explicacion":"Primero reparar; si no se puede, recién ahí reemplazar y reciclar lo viejo.","por_opcion":{"o3":"Importa, pero después de ver si se puede reparar."}}}]},{"slug":"consumo-3.s4","orden":4,"tipo":"leccion","titulo_es":"Usar sin poseer","bajada_es":"Alquilar, compartir, suscribirse al servicio y no al producto: modelos que cambian los incentivos de quien fabrica.","minutos":11,"pasos":[{"slug":"consumo-3.s4.p1","orden":1,"grupo":"consumo-3.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Vender el servicio","cuerpo":["En el modelo tradicional, a una empresa le conviene vender muchos productos, aunque duren poco. En los modelos de producto como servicio, la empresa conserva la propiedad y cobra por el uso: iluminación por horas de luz, lavarropas por lavados, neumáticos por kilómetro. Así, le conviene que el producto dure, consuma poco y se pueda reparar y remanufacturar, porque los costos de reemplazarlo son suyos."]},"solucion":{}},{"slug":"consumo-3.s4.p2","orden":2,"grupo":"consumo-3.s4.p2","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el producto como servicio incentiva la durabilidad.","items":[{"id":"i1","texto":"La empresa conserva la propiedad del producto"},{"id":"i2","texto":"Cobra por el uso, no por la venta"},{"id":"i3","texto":"Si el producto se rompe, la reparación la paga ella"},{"id":"i4","texto":"Le conviene fabricarlo durable y reparable"},{"id":"i5","texto":"Se fabrican menos productos para el mismo servicio"},{"id":"i6","texto":"La empresa gana más si el producto se rompe pronto"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cambiar quién es dueño cambia qué conviene fabricar."}},{"slug":"consumo-3.s4.p3","orden":3,"grupo":"consumo-3.s4.p3","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un modelo de venta tradicional o de uso?","grupos":[{"id":"g1","nombre":"Venta tradicional"},{"id":"g2","nombre":"Modelo de uso"}],"items":[{"id":"i1","texto":"Comprar un taladro que usarás 15 minutos en su vida"},{"id":"i2","texto":"Alquilar un taladro por un día"},{"id":"i3","texto":"Comprar un auto que pasa casi todo el día estacionado"},{"id":"i4","texto":"Suscribirse a un servicio de iluminación pagado por horas de luz"},{"id":"i5","texto":"Usar bicicletas públicas compartidas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Muchos objetos se usan poquísimo: compartirlos multiplica su uso real."}},{"slug":"consumo-3.s4.p4","orden":4,"grupo":"consumo-3.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Compartir y segunda mano","cuerpo":["Compartir, alquilar y comprar de segunda mano aumentan las veces que se usa cada objeto. Una biblioteca de herramientas en un barrio puede reemplazar decenas de taladros que pasan casi toda su vida guardados. Los mercados de ropa, muebles y electrónica usados alargan la vida de los productos. La recarga (comprar el producto y reusar el envase) evita fabricar envases nuevos."]},"solucion":{}},{"slug":"consumo-3.s4.p5","orden":5,"grupo":"consumo-3.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio, 40 hogares usan un taladro unas 4 veces por año cada uno. Si comparten 2 taladros en una biblioteca de herramientas, ¿cuántas veces por año se usa cada taladro?","unidad":"usos por año","decimales":0,"contexto":"40 hogares; 4 usos por hogar; 2 taladros."},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"40 × 4 = 160 usos repartidos en 2 taladros: 80 usos cada uno. En lugar de 40 taladros casi sin usar, 2 bien aprovechados."}},{"slug":"consumo-3.s4.p5.v2","orden":5,"grupo":"consumo-3.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio, 60 hogares usan un taladro unas 3 veces por año cada uno. Si comparten 2 taladros en una biblioteca de herramientas, ¿cuántas veces por año se usa cada taladro?","unidad":"usos por año","decimales":0,"contexto":"60 hogares; 3 usos por hogar; 2 taladros."},"solucion":{"valor":90,"tolerancia":1.8,"explicacion":"60 × 3 = 180 usos repartidos en 2 taladros: 90 usos cada uno. En lugar de 60 taladros casi sin usar, 2 bien aprovechados."}},{"slug":"consumo-3.s4.p5.v3","orden":5,"grupo":"consumo-3.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio, 30 hogares usan un taladro unas 6 veces por año cada uno. Si comparten 2 taladros en una biblioteca de herramientas, ¿cuántas veces por año se usa cada taladro?","unidad":"usos por año","decimales":0,"contexto":"30 hogares; 6 usos por hogar; 2 taladros."},"solucion":{"valor":90,"tolerancia":1.8,"explicacion":"30 × 6 = 180 usos repartidos en 2 taladros: 90 usos cada uno. En lugar de 30 taladros casi sin usar, 2 bien aprovechados."}},{"slug":"consumo-3.s4.p6","orden":6,"grupo":"consumo-3.s4.p6","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué objeto conviene más compartir que comprar?","opciones":[{"id":"o1","texto":"Una escalera que se usa dos veces al año"},{"id":"o2","texto":"El cepillo de dientes de cada persona"},{"id":"o3","texto":"El celular que usás todo el día"},{"id":"o4","texto":"La ropa interior de cada persona"}]},"solucion":{"clave":["o1"],"explicacion":"Los objetos de uso ocasional son los mejores candidatos para compartir.","por_opcion":{"o3":"Se usa demasiado para compartirlo; conviene hacerlo durar."}}},{"slug":"consumo-3.s4.p7","orden":7,"grupo":"consumo-3.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuidado con el rebote","cuerpo":["Estos modelos no siempre reducen el impacto. Si compartir hace algo tan barato que se usa mucho más, o si el alquiler implica muchos traslados en auto para buscar y devolver, parte del beneficio se pierde. Y si la ropa alquilada se envía y se lava en seco después de cada uso, su huella puede ser mayor que la de una prenda propia usada muchas veces."]},"solucion":{}},{"slug":"consumo-3.s4.p8","orden":8,"grupo":"consumo-3.s4.p8","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Alquilar ropa siempre tiene menos impacto que comprarla.","razones":[{"id":"r1","texto":"Porque los envíos y lavados pueden sumar mucho impacto"},{"id":"r2","texto":"Porque alquilar es siempre peor"},{"id":"r3","texto":"Porque la ropa alquilada no se lava"}]},"solucion":{"valor":false,"explicacion":"Depende: los envíos y lavados frecuentes pueden sumar mucho. Una prenda propia usada durante años suele tener menos impacto que una alquilada que viaja y se lava tras cada uso.","clave":["r1"]}},{"slug":"consumo-3.s4.p9","orden":9,"grupo":"consumo-3.s4.p9","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada modelo con su ejemplo.","izquierda":[{"id":"a1","texto":"Producto como servicio"},{"id":"a2","texto":"Compartir"},{"id":"a3","texto":"Segunda mano"},{"id":"a4","texto":"Recarga"}],"derecha":[{"id":"b1","texto":"Pagar por horas de luz en lugar de comprar lámparas"},{"id":"b2","texto":"Bicicletas públicas"},{"id":"b3","texto":"Feria de ropa usada"},{"id":"b4","texto":"Llenar el mismo envase de detergente"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Distintas formas de obtener el servicio que necesitamos con menos materiales."}},{"slug":"consumo-3.s4.p10","orden":10,"grupo":"consumo-3.s4.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una empresa alquila bicicletas por mes y se encarga de repararlas. ¿Por qué le conviene que duren mucho?","opciones":[{"id":"o1","texto":"Porque cada bici nueva que compra es un costo suyo"},{"id":"o2","texto":"Porque así puede cobrar más caro el alquiler"},{"id":"o3","texto":"Porque las bicis viejas se venden más caras"},{"id":"o4","texto":"Porque la ley la obliga a no comprar bicis"}]},"solucion":{"clave":["o1"],"explicacion":"En el modelo de uso, la durabilidad deja de ser un costo para la empresa y pasa a ser su ganancia.","por_opcion":{"o3":"El punto es que reemplazarlas le cuesta a la empresa."}}},{"slug":"consumo-3.s4.p11","orden":11,"grupo":"consumo-3.s4.p11","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas opciones para tener un taladro de uso ocasional, de menor a mayor impacto.","items":[{"id":"i1","texto":"Pedirlo prestado a un vecino"},{"id":"i2","texto":"Usar la biblioteca de herramientas del barrio"},{"id":"i3","texto":"Comprar uno usado"},{"id":"i4","texto":"Comprar uno nuevo y guardarlo"}],"extremos":["Menor impacto","Mayor impacto"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuanto más se comparte un objeto que existe, menos objetos nuevos hacen falta.","valores":{"i1":"mínimo","i2":"bajo","i3":"medio","i4":"mayor"}}},{"slug":"consumo-3.s4.p12","orden":12,"grupo":"consumo-3.s4.p12","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué condiciones hacen que un modelo de uso reduzca de verdad el impacto? Marcá todas.","opciones":[{"id":"o1","texto":"Que el producto compartido sea durable y se mantenga"},{"id":"o2","texto":"Que buscarlo y devolverlo no requiera largos viajes en auto"},{"id":"o3","texto":"Que reemplace compras de productos nuevos"},{"id":"o4","texto":"Que se use el doble solo porque es barato"},{"id":"o5","texto":"Que cada uso requiera un envío individual en avión"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El beneficio depende de los detalles: logística, durabilidad y si realmente reemplaza compras."}},{"slug":"consumo-3.s4.p13","orden":13,"grupo":"consumo-3.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé la propuesta de una empresa y marcá lo que no es circular.","segmentos":[{"id":"s1","texto":"Alquilamos lavarropas y nos ocupamos de repararlos."},{"id":"s2","texto":"Cada seis meses reemplazamos el lavarropas por uno nuevo aunque funcione."},{"id":"s3","texto":"Remanufacturamos las piezas gastadas."},{"id":"s4","texto":"Cobramos por lavado, así preferimos equipos que consuman poco."}]},"solucion":{"clave":["s2"],"explicacion":"Un modelo de servicio es circular si alarga la vida de los productos, no si los rota más rápido.","por_opcion":{"s2":"Descartar aparatos que funcionan va contra la circularidad."}}},{"slug":"consumo-3.s4.p14","orden":14,"grupo":"consumo-3.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cobrar por el uso en lugar de vender el objeto es un modelo de producto como {{0}}; una biblioteca de herramientas es una forma de {{1}}; y si un servicio barato hace que se use mucho más, hay un efecto {{2}}.","banco":[{"id":"w1","texto":"servicio"},{"id":"w2","texto":"compartir"},{"id":"w3","texto":"rebote"},{"id":"w4","texto":"regalo"},{"id":"w5","texto":"acumular"},{"id":"w6","texto":"espejo"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre modelos que venden uso en lugar de cosas."}}]},{"slug":"consumo-3.s5","orden":5,"tipo":"leccion","titulo_es":"Límites y personas","bajada_es":"Lo que la circularidad no puede, el reciclaje que degrada, el lavado circular y quienes hoy recuperan los materiales.","minutos":12,"pasos":[{"slug":"consumo-3.s5.p1","orden":1,"grupo":"consumo-3.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"No puede ser perfecta","cuerpo":["Ninguna economía puede ser 100 % circular. Cada vez que se recicla se pierde algo de material y se usa energía; algunos materiales se degradan (el papel acorta sus fibras, muchos plásticos pierden calidad); y mientras la demanda de materiales crezca, ni siquiera reciclando todo alcanzaría para abastecerla. Según el Informe sobre la Brecha de Circularidad, reciclar todo lo reciclable, sin reducir el consumo, llevaría la circularidad mundial solo hasta un 25 % aproximadamente."]},"solucion":{}},{"slug":"consumo-3.s5.p2","orden":2,"grupo":"consumo-3.s5.p2","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Según el informe de 2025, ¿hasta dónde subiría la circularidad si se reciclara todo lo reciclable, sin reducir el consumo?","opciones":[{"id":"o1","texto":"Hasta un 25 % aproximadamente"},{"id":"o2","texto":"Hasta el 100 %, es decir, la circularidad total"},{"id":"o3","texto":"Hasta un 80 %, casi completa"},{"id":"o4","texto":"No cambiaría nada, seguiría en 6,9 %"}]},"solucion":{"clave":["o1"],"explicacion":"Reciclar más ayuda, pero sin usar menos materiales la economía sigue siendo mayormente lineal.","por_opcion":{"o3":"Muy por debajo: los materiales en uso y en stock no alcanzan."}}},{"slug":"consumo-3.s5.p3","orden":3,"grupo":"consumo-3.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reciclaje que degrada","cuerpo":["A veces el reciclaje convierte un material en algo de menor calidad, que después ya no se puede reciclar: se lo llama infrarreciclaje. Por ejemplo, botellas plásticas convertidas en fibras para ropa, que luego casi nunca se reciclan de nuevo. Es mejor que tirarlas, pero no cierra el ciclo: solo lo estira un paso más."]},"solucion":{}},{"slug":"consumo-3.s5.p4","orden":4,"grupo":"consumo-3.s5.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido de una botella que se infrarrecicla.","items":[{"id":"i1","texto":"Se usa una botella plástica"},{"id":"i2","texto":"Se recicla en fibras para una remera"},{"id":"i3","texto":"La remera se usa unos años"},{"id":"i4","texto":"Mezclada con otras fibras, casi no se puede reciclar"},{"id":"i5","texto":"Termina en un relleno o quemada"},{"id":"i6","texto":"La remera vuelve a ser botella automáticamente"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El infrarreciclaje retrasa el final, pero no lo evita."}},{"slug":"consumo-3.s5.p5","orden":5,"grupo":"consumo-3.s5.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este reciclaje cierra el ciclo o solo lo estira?","grupos":[{"id":"g1","nombre":"Cierra el ciclo"},{"id":"g2","nombre":"Solo lo estira"}],"items":[{"id":"i1","texto":"Una lata de aluminio que vuelve a ser lata"},{"id":"i2","texto":"Una botella plástica convertida en fibra textil"},{"id":"i3","texto":"Una botella de vidrio que vuelve a ser botella"},{"id":"i4","texto":"Papel de oficina convertido en cartón de menor calidad"},{"id":"i5","texto":"Restos de comida compostados que vuelven al suelo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Cerrar el ciclo es volver al mismo uso; estirarlo es bajar un escalón de calidad."}},{"slug":"consumo-3.s5.p6","orden":6,"grupo":"consumo-3.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lavado circular","cuerpo":["Como pasa con lo \"verde\", también hay lavado circular: empresas que se presentan como circulares por un programa chico de reciclaje mientras su modelo sigue siendo vender cada vez más productos de corta vida. Las preguntas útiles son: ¿qué porcentaje de sus productos vuelve y a qué ciclo?, ¿diseñan para durar y reparar?, ¿su volumen de ventas crece más rápido que lo que recuperan?"]},"solucion":{}},{"slug":"consumo-3.s5.p7","orden":7,"grupo":"consumo-3.s5.p7","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta campaña de una marca de moda rápida y marcá lo engañoso.","segmentos":[{"id":"s1","texto":"Tenemos contenedores para devolver ropa usada en nuestras tiendas."},{"id":"s2","texto":"Somos una marca circular: tu ropa vieja se convierte en ropa nueva."},{"id":"s3","texto":"Publicamos cuántas prendas recolectamos por año."},{"id":"s4","texto":"Llevá una bolsa de ropa usada y te damos un descuento para comprar más."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Lo viste con el greenwashing: una acción real puede usarse para tapar un modelo lineal.","por_opcion":{"s2":"En la práctica, muy poca ropa se recicla en ropa nueva.","s4":"Incentivar más compras contradice la circularidad."}}},{"slug":"consumo-3.s5.p8","orden":8,"grupo":"consumo-3.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quienes recuperan","cuerpo":["En Argentina, gran parte de los materiales que se reciclan son recuperados por recuperadoras y recuperadores urbanos, muchas veces organizados en cooperativas, como las que integran la Federación Argentina de Cartoneros, Carreros y Recicladores. Hacen un trabajo ambiental esencial, muchas veces en condiciones precarias. Una economía circular justa los reconoce, los incluye en los sistemas de gestión y mejora sus condiciones.","Otra herramienta es la responsabilidad extendida del productor: que quienes ponen productos y envases en el mercado se hagan cargo de financiar su recuperación."]},"solucion":{}},{"slug":"consumo-3.s5.p9","orden":9,"grupo":"consumo-3.s5.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace más justa a la economía circular? Marcá todo.","opciones":[{"id":"o1","texto":"Incluir a las cooperativas de recuperadores en la gestión"},{"id":"o2","texto":"Mejorar sus condiciones de trabajo y sus ingresos"},{"id":"o3","texto":"Que los productores financien la recuperación de sus envases"},{"id":"o4","texto":"Excluir a los recuperadores para automatizar todo"},{"id":"o5","texto":"Que los costos los paguen solo los municipios"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La circularidad también es una cuestión social: quién hace el trabajo y quién paga."}},{"slug":"consumo-3.s5.p10","orden":10,"grupo":"consumo-3.s5.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su descripción.","izquierda":[{"id":"a1","texto":"Infrarreciclaje"},{"id":"a2","texto":"Lavado circular"},{"id":"a3","texto":"Responsabilidad extendida del productor"},{"id":"a4","texto":"Recuperadores urbanos"}],"derecha":[{"id":"b1","texto":"Reciclar en algo de menor calidad"},{"id":"b2","texto":"Presentarse como circular sin serlo"},{"id":"b3","texto":"El productor financia la recuperación"},{"id":"b4","texto":"Personas que recuperan materiales reciclables"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro conceptos para mirar la circularidad con ojo crítico."}},{"slug":"consumo-3.s5.p11","orden":11,"grupo":"consumo-3.s5.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una marca vende 1.000 toneladas de ropa por año y recupera 20 toneladas con su programa de reciclaje. ¿Qué porcentaje recupera?","unidad":"%","decimales":1,"contexto":"20 t recuperadas de 1000 t vendidas."},"solucion":{"valor":2,"tolerancia":0.1,"explicacion":"20 ÷ 1.000 × 100 = 2 %. Si su publicidad dice \"somos circulares\", el número muestra otra cosa."}},{"slug":"consumo-3.s5.p11.v2","orden":11,"grupo":"consumo-3.s5.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una marca vende 500 toneladas de ropa por año y recupera 15 toneladas con su programa de reciclaje. ¿Qué porcentaje recupera?","unidad":"%","decimales":1,"contexto":"15 t recuperadas de 500 t vendidas."},"solucion":{"valor":3,"tolerancia":0.1,"explicacion":"15 ÷ 500 × 100 = 3 %. Si su publicidad dice \"somos circulares\", el número muestra otra cosa."}},{"slug":"consumo-3.s5.p11.v3","orden":11,"grupo":"consumo-3.s5.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una marca vende 2.000 toneladas de ropa por año y recupera 50 toneladas con su programa de reciclaje. ¿Qué porcentaje recupera?","unidad":"%","decimales":1,"contexto":"50 t recuperadas de 2000 t vendidas."},"solucion":{"valor":2.5,"tolerancia":0.1,"explicacion":"50 ÷ 2.000 × 100 = 2,5 %. Si su publicidad dice \"somos circulares\", el número muestra otra cosa."}},{"slug":"consumo-3.s5.p12","orden":12,"grupo":"consumo-3.s5.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una empresa recicla una parte de sus productos, ya es una empresa circular.","razones":[{"id":"r1","texto":"Porque importan cuánto recupera, cómo diseña y cuánto vende"},{"id":"r2","texto":"Porque reciclar no tiene ningún valor"},{"id":"r3","texto":"Porque ninguna empresa puede reciclar"}]},"solucion":{"valor":false,"explicacion":"Depende de cuánto recupera, a qué ciclo vuelve lo recuperado, cómo diseña y si su volumen de ventas crece más que lo que recupera.","clave":["r1"]}},{"slug":"consumo-3.s5.p13","orden":13,"grupo":"consumo-3.s5.p13","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas acciones de una empresa de la más circular a la menos.","items":[{"id":"i1","texto":"Diseñar para durar y ofrecer reparación de por vida"},{"id":"i2","texto":"Recomprar productos usados y reacondicionarlos"},{"id":"i3","texto":"Usar un 30 % de material reciclado"},{"id":"i4","texto":"Poner un contenedor de reciclaje en sus tiendas"}],"extremos":["Más circular","Menos circular"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las acciones de diseño y de ciclos internos pesan más que las de reciclaje al final.","valores":{"i1":"más circular","i2":"muy circular","i3":"algo","i4":"poco"}}},{"slug":"consumo-3.s5.p14","orden":14,"grupo":"consumo-3.s5.p14","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la economía circular no reemplaza la necesidad de consumir menos?","opciones":[{"id":"o1","texto":"Porque reciclar pierde material y energía"},{"id":"o2","texto":"Porque la economía circular obliga a comprar más"},{"id":"o3","texto":"Porque consumir menos está prohibido"},{"id":"o4","texto":"Porque los materiales reciclados no existen"}]},"solucion":{"clave":["o1"],"explicacion":"Circularidad y suficiencia van juntas: usar menos, usar más tiempo y recuperar lo que queda.","por_opcion":{"o3":"No lo está: es la estrategia más efectiva."}}},{"slug":"consumo-3.s5.p15","orden":15,"grupo":"consumo-3.s5.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Reciclar un material en algo de menor calidad es {{0}}; presentarse como circular sin serlo es lavado {{1}}; y que el productor financie la recuperación es responsabilidad {{2}}.","banco":[{"id":"w1","texto":"infrarreciclaje"},{"id":"w2","texto":"circular"},{"id":"w3","texto":"extendida"},{"id":"w4","texto":"sobrerreciclaje"},{"id":"w5","texto":"verde"},{"id":"w6","texto":"limitada"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para detectar los límites y las trampas de la circularidad."}}]},{"slug":"consumo-3.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: economía circular","bajada_es":"Principios, ciclos, ecodiseño, modelos de uso, límites y justicia, mezclados.","minutos":8,"pasos":[{"slug":"consumo-3.s6.p1","orden":1,"grupo":"consumo-3.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Economía circular». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"consumo-3.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la marca de zapatillas","bajada_es":"Una marca argentina de zapatillas quiere volverse circular. Evaluá sus propuestas con lo que aprendiste.","minutos":10,"pasos":[{"slug":"consumo-3.s7.p1","orden":1,"grupo":"consumo-3.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["La marca vende 100.000 pares por año. Sus zapatillas duran en promedio 1 año, tienen suela pegada y mezclan cuero, tela y plástico. El equipo propone: (A) una campaña que diga \"somos circulares\" con un contenedor de reciclaje en cada tienda; (B) rediseñar la zapatilla con suela cosida y reemplazable, y materiales separables; (C) un servicio de reparación y cambio de suela; (D) recomprar pares usados, reacondicionarlos y venderlos como segunda mano; (E) un descuento para comprar un par nuevo cada vez que devuelven uno viejo."]},"solucion":{}},{"slug":"consumo-3.s7.p2","orden":2,"grupo":"consumo-3.s7.p2","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las propuestas.","grupos":[{"id":"g1","nombre":"Circulares de verdad"},{"id":"g2","nombre":"Riesgo de lavado circular"}],"items":[{"id":"i1","texto":"B · Suela cosida y materiales separables"},{"id":"i2","texto":"A · Campaña \"somos circulares\" con contenedor"},{"id":"i3","texto":"C · Reparación y cambio de suela"},{"id":"i4","texto":"E · Descuento por comprar un par nuevo"},{"id":"i5","texto":"D · Recompra y reacondicionamiento"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Las propuestas de diseño y ciclos internos son las de fondo; las de comunicación e incentivo a comprar pueden ser lavado circular."}},{"slug":"consumo-3.s7.p3","orden":3,"grupo":"consumo-3.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si con el rediseño y la reparación las zapatillas duran 2 años en lugar de 1, ¿cuántos pares por año harían falta para calzar a las mismas personas?","unidad":"pares","decimales":0,"contexto":"100.000 pares por año; la vida útil pasa de 1 a 2 años."},"solucion":{"valor":50000,"tolerancia":1000,"explicacion":"100.000 ÷ 2 = 50.000 pares por año: la mitad de materiales y de residuos para el mismo servicio."}},{"slug":"consumo-3.s7.p4","orden":4,"grupo":"consumo-3.s7.p4","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las propuestas de la más a la menos circular.","items":[{"id":"i1","texto":"B · Rediseño con suela cosida y materiales separables"},{"id":"i2","texto":"C · Reparación y cambio de suela"},{"id":"i3","texto":"D · Recompra y reacondicionamiento"},{"id":"i4","texto":"A · Campaña con contenedor"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El diseño habilita todo lo demás; la campaña, sola, no cambia nada.","valores":{"i1":"diseño","i2":"mantener","i3":"reutilizar","i4":"comunicación"}}},{"slug":"consumo-3.s7.p5","orden":5,"grupo":"consumo-3.s7.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué problema tiene la propuesta E?","opciones":[{"id":"o1","texto":"Incentiva a comprar más pares nuevos"},{"id":"o2","texto":"Que las zapatillas usadas no sirven para nada"},{"id":"o3","texto":"Que es demasiado cara para la marca"},{"id":"o4","texto":"Que los descuentos están prohibidos"}]},"solucion":{"clave":["o1"],"explicacion":"Un incentivo a comprar más contradice el objetivo de usar menos materiales.","por_opcion":{"o3":"El problema no es el costo sino que empuja más ventas."}}},{"slug":"consumo-3.s7.p6","orden":6,"grupo":"consumo-3.s7.p6","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué indicadores debería publicar la marca para mostrar avances reales? Marcá todos.","opciones":[{"id":"o1","texto":"Vida útil promedio de sus zapatillas"},{"id":"o2","texto":"Pares reparados y reacondicionados por año"},{"id":"o3","texto":"Porcentaje de materiales que vuelven a un ciclo"},{"id":"o4","texto":"Cantidad de publicaciones en redes sobre circularidad"},{"id":"o5","texto":"Número de contenedores instalados, sin datos de lo recuperado"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Los indicadores deben medir resultados, no actividades de comunicación."}},{"slug":"consumo-3.s7.p7","orden":7,"grupo":"consumo-3.s7.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si la marca vende la mitad de pares nuevos pero cobra por reparaciones y reacondicionados, puede seguir siendo un negocio viable.","razones":[{"id":"r1","texto":"Porque puede ganar con servicios y segunda mano"},{"id":"r2","texto":"Porque reparar nunca genera ingresos"},{"id":"r3","texto":"Porque las empresas solo ganan vendiendo productos nuevos"}]},"solucion":{"valor":true,"explicacion":"Muchas empresas circulares ganan con servicios, reparaciones y segunda mano. El modelo cambia: menos unidades, más servicio por unidad.","clave":["r1"]}},{"slug":"consumo-3.s7.p8","orden":8,"grupo":"consumo-3.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La marca redacta su comunicado. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Nuestras nuevas zapatillas tienen suela cosida y reemplazable."},{"id":"s2","texto":"Somos 100 % circulares."},{"id":"s3","texto":"Ofrecemos cambio de suela en todas nuestras tiendas."},{"id":"s4","texto":"Devolvé tu par viejo y llevate dos nuevos con descuento."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Comunicar bien es dar datos verificables, sin prometer lo imposible.","por_opcion":{"s2":"Ninguna empresa lo es; conviene dar datos concretos.","s4":"Incentiva comprar más: contradice la circularidad."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"consumo-4","rama":"consumo","orden":4,"nivel":2,"titulo_es":"Lo que el precio no dice","bajada_es":"Contaminación que nadie paga, subsidios que empujan al revés y productos baratos que salen caros: los costos ocultos y cómo hacer que los precios digan la verdad.","objetivos_es":["Explicar qué es una externalidad, negativa o positiva, con ejemplos","Interpretar los costos ocultos de los sistemas alimentarios","Comparar impuestos al carbono y mercados de emisiones","Reconocer subsidios que alientan la contaminación","Calcular el costo total de un producto y considerar quién paga cada política"],"repasa":["consumo-1","consumo-3","alimentacion-2","energia-2"],"requiere_tronco":2,"fuentes":["fao-sofa-2023","bm-precio-carbono","fmi-subsidios","ley-27430-impuesto-co2","ley-25675-ambiente","ipbes-polinizadores","fao-pesca-sofia","oms-aire-exterior"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"consumo-4.s1","orden":1,"tipo":"leccion","titulo_es":"Lo que el precio no cuenta","bajada_es":"Externalidades: costos y beneficios que recaen sobre quienes no compran ni venden.","minutos":10,"pasos":[{"slug":"consumo-4.s1.p1","orden":1,"grupo":"consumo-4.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una tercera persona paga","cuerpo":["Cuando una fábrica contamina un río, el precio de lo que produce no incluye el costo de limpiar el agua ni el de las enfermedades de quienes viven aguas abajo. Ese costo existe, pero lo pagan otras personas. En economía se lo llama externalidad negativa: un costo que recae sobre quienes no participaron de la compra ni de la venta.","Como el precio no refleja el costo completo, el producto contaminante parece más barato de lo que es, y se produce y se consume más de lo que convendría."]},"solucion":{}},{"slug":"consumo-4.s1.p2","orden":2,"grupo":"consumo-4.s1.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué es una externalidad negativa?","opciones":[{"id":"o1","texto":"Un costo que paga alguien ajeno a la compra y la venta"},{"id":"o2","texto":"Un impuesto que paga quien compra un producto"},{"id":"o3","texto":"El precio de un producto importado"},{"id":"o4","texto":"Una ganancia extra de la empresa"}]},"solucion":{"clave":["o1"],"explicacion":"El problema no es que el costo no exista, sino que lo paga otra persona.","por_opcion":{"o3":"No tiene que ver con el origen: es un costo que recae en terceros."}}},{"slug":"consumo-4.s1.p3","orden":3,"grupo":"consumo-4.s1.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Quién paga el costo en cada caso?","grupos":[{"id":"g1","nombre":"Lo paga quien compra o vende"},{"id":"g2","nombre":"Lo pagan terceros (externalidad)"}],"items":[{"id":"i1","texto":"El precio de la nafta en el surtidor"},{"id":"i2","texto":"El asma de quien vive junto a una avenida con mucho tránsito"},{"id":"i3","texto":"El costo de la materia prima de un producto"},{"id":"i4","texto":"La limpieza de un río contaminado por una curtiembre"},{"id":"i5","texto":"Los daños de eventos extremos por el calentamiento global"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Las externalidades son costos reales que no aparecen en el ticket."}},{"slug":"consumo-4.s1.p4","orden":4,"grupo":"consumo-4.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"También hay externalidades positivas","cuerpo":["A veces el efecto es un beneficio que nadie cobra. Un apicultor cuyas abejas polinizan los cultivos vecinos, una persona que planta árboles en su vereda que dan sombra a todos, o un campo que conserva un humedal que absorbe crecidas. Como nadie les paga por ese beneficio, se produce menos de lo que convendría. Por eso existen los pagos por servicios ambientales, que remuneran a quien conserva."]},"solucion":{}},{"slug":"consumo-4.s1.p5","orden":5,"grupo":"consumo-4.s1.p5","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una externalidad negativa o positiva?","grupos":[{"id":"g1","nombre":"Negativa"},{"id":"g2","nombre":"Positiva"}],"items":[{"id":"i1","texto":"El ruido de un boliche para los vecinos"},{"id":"i2","texto":"Las abejas de un apicultor polinizan campos vecinos"},{"id":"i3","texto":"El humo de una quema de basura"},{"id":"i4","texto":"Un árbol en la vereda que da sombra a quienes pasan"},{"id":"i5","texto":"El lodo de una obra que tapa un desagüe"},{"id":"i6","texto":"Un humedal conservado que reduce inundaciones aguas abajo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las positivas se producen de menos; las negativas, de más. Las políticas buscan corregir las dos."}},{"slug":"consumo-4.s1.p6","orden":6,"grupo":"consumo-4.s1.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué una externalidad negativa lleva a contaminar de más.","items":[{"id":"i1","texto":"Una empresa contamina sin pagar el daño"},{"id":"i2","texto":"Su costo de producir parece más bajo"},{"id":"i3","texto":"Puede vender más barato"},{"id":"i4","texto":"Se compra y se produce más"},{"id":"i5","texto":"Aumenta la contaminación total"},{"id":"i6","texto":"El precio bajo reduce la contaminación"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un precio que miente empuja a producir y consumir más de lo que convendría."}},{"slug":"consumo-4.s1.p7","orden":7,"grupo":"consumo-4.s1.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un producto cuesta 100 pesos, pero su fabricación causa daños a terceros por 30 pesos por unidad. ¿Cuál sería su costo real para la sociedad?","unidad":"pesos","decimales":0,"contexto":"Precio 100; daño a terceros 30 por unidad."},"solucion":{"valor":130,"tolerancia":2.6,"explicacion":"100 + 30 = 130 pesos. El precio muestra solo 100: la diferencia la pagan otras personas."}},{"slug":"consumo-4.s1.p7.v2","orden":7,"grupo":"consumo-4.s1.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un producto cuesta 250 pesos, pero su fabricación causa daños a terceros por 60 pesos por unidad. ¿Cuál sería su costo real para la sociedad?","unidad":"pesos","decimales":0,"contexto":"Precio 250; daño a terceros 60 por unidad."},"solucion":{"valor":310,"tolerancia":6.2,"explicacion":"250 + 60 = 310 pesos. El precio muestra solo 250: la diferencia la pagan otras personas."}},{"slug":"consumo-4.s1.p7.v3","orden":7,"grupo":"consumo-4.s1.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un producto cuesta 80 pesos, pero su fabricación causa daños a terceros por 40 pesos por unidad. ¿Cuál sería su costo real para la sociedad?","unidad":"pesos","decimales":0,"contexto":"Precio 80; daño a terceros 40 por unidad."},"solucion":{"valor":120,"tolerancia":2.4,"explicacion":"80 + 40 = 120 pesos. El precio muestra solo 80: la diferencia la pagan otras personas."}},{"slug":"consumo-4.s1.p8","orden":8,"grupo":"consumo-4.s1.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un producto es barato, es porque su fabricación no causa ningún daño.","razones":[{"id":"r1","texto":"Porque el precio puede no incluir los daños a terceros"},{"id":"r2","texto":"Porque los productos baratos nunca contaminan"},{"id":"r3","texto":"Porque el precio incluye siempre todos los costos"}]},"solucion":{"valor":false,"explicacion":"Puede ser barato justamente porque no paga los daños que causa. El precio bajo puede esconder costos ambientales y sociales.","clave":["r1"]}},{"slug":"consumo-4.s1.p9","orden":9,"grupo":"consumo-4.s1.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un campo conserva un humedal que evita inundaciones río abajo, pero nadie le paga por eso. ¿Qué es probable que pase?","opciones":[{"id":"o1","texto":"Que tenga incentivos para rellenarlo y sembrar"},{"id":"o2","texto":"Que lo conserve para siempre sin ningún costo"},{"id":"o3","texto":"Que los vecinos de río abajo le paguen solos"},{"id":"o4","texto":"Que el humedal se agrande naturalmente"}]},"solucion":{"clave":["o1"],"explicacion":"Sin pago, conservar le cuesta y no le rinde: las externalidades positivas tienden a perderse.","por_opcion":{"o3":"Sin un acuerdo o una política, nadie paga por un beneficio gratuito."}}},{"slug":"consumo-4.s1.p10","orden":10,"grupo":"consumo-4.s1.p10","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su ejemplo.","izquierda":[{"id":"a1","texto":"Externalidad negativa"},{"id":"a2","texto":"Externalidad positiva"},{"id":"a3","texto":"Pago por servicios ambientales"},{"id":"a4","texto":"Precio que miente"}],"derecha":[{"id":"b1","texto":"Contaminación del aire por una fábrica"},{"id":"b2","texto":"Polinización gratuita de cultivos vecinos"},{"id":"b3","texto":"Remunerar a quien conserva un bosque"},{"id":"b4","texto":"Un producto barato que esconde daños"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro ideas para leer los precios con otros ojos."}},{"slug":"consumo-4.s1.p11","orden":11,"grupo":"consumo-4.s1.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ejemplos muestran externalidades del transporte en auto? Marcá todos.","opciones":[{"id":"o1","texto":"Contaminación del aire que respiran peatones"},{"id":"o2","texto":"Congestión que demora a los colectivos"},{"id":"o3","texto":"Ruido en las calles"},{"id":"o4","texto":"La nafta que paga quien maneja"},{"id":"o5","texto":"La cuota del seguro del auto"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La nafta y el seguro los paga quien maneja; el aire, el ruido y la demora los pagan todos."}},{"slug":"consumo-4.s1.p12","orden":12,"grupo":"consumo-4.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta opinión y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El costo de la contaminación lo pagan muchas veces los vecinos."},{"id":"s2","texto":"Si nadie paga un costo, ese costo no existe."},{"id":"s3","texto":"Conservar un humedal puede beneficiar a quienes viven aguas abajo."},{"id":"s4","texto":"Las externalidades positivas no necesitan ninguna política."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Ver las externalidades cambia la pregunta de \"¿cuánto cuesta?\" a \"¿quién paga?\".","por_opcion":{"s2":"Existe: lo paga alguien, aunque no aparezca en el precio.","s4":"Como nadie las paga, se producen de menos; los pagos por servicios ambientales las estimulan."}}},{"slug":"consumo-4.s1.p13","orden":13,"grupo":"consumo-4.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un costo que paga alguien ajeno a la compra es una {{0}}; cuando el efecto es un beneficio gratuito, es {{1}}; y remunerar a quien conserva un bosque es un pago por servicios {{2}}.","banco":[{"id":"w1","texto":"externalidad"},{"id":"w2","texto":"positiva"},{"id":"w3","texto":"ambientales"},{"id":"w4","texto":"ganancia"},{"id":"w5","texto":"neutra"},{"id":"w6","texto":"bancarios"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Los conceptos básicos para entender los costos ocultos."}}]},{"slug":"consumo-4.s2","orden":2,"tipo":"leccion","titulo_es":"Los costos ocultos de la comida","bajada_es":"Salud, ambiente y pobreza: lo que el precio de los alimentos no incluye, según la FAO.","minutos":10,"pasos":[{"slug":"consumo-4.s2.p1","orden":1,"grupo":"consumo-4.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Diez billones de dólares","cuerpo":["En su informe de 2023, la FAO estimó por primera vez los costos ocultos de los sistemas agroalimentarios en 154 países: al menos 10 billones de dólares por año (10 millones de millones), casi el 10 % del producto bruto mundial. Alrededor del 73 % de esos costos se relaciona con dietas poco saludables, que causan enfermedades y pérdida de productividad; alrededor del 20 %, con impactos ambientales como emisiones, contaminación con nitrógeno y cambio en el uso del suelo; y cerca del 4 %, con costos sociales como la pobreza de quienes trabajan en la cadena."],"datos":{"tipo":"barras","titulo":"Costos ocultos de los sistemas agroalimentarios por tipo (aproximado)","unidad":"%","filas":[{"etiqueta":"Salud (dietas poco saludables)","valor":73},{"etiqueta":"Ambiente","valor":20},{"etiqueta":"Social","valor":4}],"nota":"FAO, El estado mundial de la agricultura y la alimentación 2023; el resto, otros costos."}},"solucion":{}},{"slug":"consumo-4.s2.p2","orden":2,"grupo":"consumo-4.s2.p2","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos millones de millones de dólares por año suman los costos ocultos de los sistemas agroalimentarios, según la FAO.","min":0.1,"max":1000,"paso":1,"unidad":"millones de millones de USD","escala":"log"},"solucion":{"valor":10,"banda":"log","explicacion":"Al menos 10 millones de millones (10 billones) de dólares por año, casi el 10 % del producto mundial."}},{"slug":"consumo-4.s2.p3","orden":3,"grupo":"consumo-4.s2.p3","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená los tipos de costos ocultos de la comida, de mayor a menor, según la FAO.","items":[{"id":"i1","texto":"Salud, por dietas poco saludables"},{"id":"i2","texto":"Ambiente"},{"id":"i3","texto":"Social"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"Sorprende a muchos: el mayor costo oculto está en la salud, no en el ambiente.","valores":{"i1":"≈ 73 %","i2":"≈ 20 %","i3":"≈ 4 %"}}},{"slug":"consumo-4.s2.p4","orden":4,"grupo":"consumo-4.s2.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es el mayor costo oculto de los sistemas agroalimentarios, según la FAO?","opciones":[{"id":"o1","texto":"Las enfermedades por dietas poco saludables"},{"id":"o2","texto":"Los envases plásticos de los alimentos"},{"id":"o3","texto":"El transporte internacional de alimentos"},{"id":"o4","texto":"El precio de la maquinaria agrícola"}]},"solucion":{"clave":["o1"],"explicacion":"Casi tres cuartos de los costos ocultos tienen que ver con la salud.","por_opcion":{"o3":"Es parte de lo ambiental, que en total pesa menos que la salud."}}},{"slug":"consumo-4.s2.p5","orden":5,"grupo":"consumo-4.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los costos ocultos suman 10 millones de millones de dólares y el 20 % es ambiental, ¿cuántos millones de millones son costos ambientales? Redondeá a un decimal.","unidad":"millones de millones de USD","decimales":1,"contexto":"10 millones de millones en total; 20 % ambiental."},"solucion":{"valor":2,"tolerancia":0.1,"explicacion":"10 × 0,2 = 2 millones de millones de dólares por año, que hoy nadie paga en el precio de la comida."}},{"slug":"consumo-4.s2.p5.v2","orden":5,"grupo":"consumo-4.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los costos ocultos suman 12 millones de millones de dólares y el 20 % es ambiental, ¿cuántos millones de millones son costos ambientales? Redondeá a un decimal.","unidad":"millones de millones de USD","decimales":1,"contexto":"12 millones de millones en total; 20 % ambiental."},"solucion":{"valor":2.4,"tolerancia":0.1,"explicacion":"12 × 0,2 = 2,4 millones de millones de dólares por año, que hoy nadie paga en el precio de la comida."}},{"slug":"consumo-4.s2.p5.v3","orden":5,"grupo":"consumo-4.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los costos ocultos suman 11 millones de millones de dólares y el 20 % es ambiental, ¿cuántos millones de millones son costos ambientales? Redondeá a un decimal.","unidad":"millones de millones de USD","decimales":1,"contexto":"11 millones de millones en total; 20 % ambiental."},"solucion":{"valor":2.2,"tolerancia":0.1,"explicacion":"11 × 0,2 = 2,2 millones de millones de dólares por año, que hoy nadie paga en el precio de la comida."}},{"slug":"consumo-4.s2.p6","orden":6,"grupo":"consumo-4.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El costo verdadero","cuerpo":["La idea de contabilidad de costos verdaderos busca sumar al precio de los alimentos los costos ocultos, para que las decisiones —de gobiernos, empresas y personas— se basen en la información completa. No significa necesariamente que la comida deba ser más cara para quien la compra: puede significar, por ejemplo, redirigir subsidios, cambiar la forma de producir o mejorar la información nutricional."]},"solucion":{}},{"slug":"consumo-4.s2.p7","orden":7,"grupo":"consumo-4.s2.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de un costo oculto de salud.","items":[{"id":"i1","texto":"Un alimento ultraprocesado es barato y muy consumido"},{"id":"i2","texto":"Su consumo frecuente aumenta el riesgo de enfermedades"},{"id":"i3","texto":"Crecen los tratamientos y los días sin poder trabajar"},{"id":"i4","texto":"El sistema de salud y las familias pagan ese costo"},{"id":"i5","texto":"Ese costo no está en el precio del producto"},{"id":"i6","texto":"El precio del producto incluye los tratamientos médicos"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Por eso el etiquetado frontal de alimentos busca, al menos, que la información llegue a quien compra."}},{"slug":"consumo-4.s2.p8","orden":8,"grupo":"consumo-4.s2.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué tipo de costo oculto es cada caso?","grupos":[{"id":"g1","nombre":"Salud"},{"id":"g2","nombre":"Ambiente"},{"id":"g3","nombre":"Social"}],"items":[{"id":"i1","texto":"Diabetes asociada a dietas con mucha azúcar"},{"id":"i2","texto":"Emisiones de metano de la ganadería"},{"id":"i3","texto":"Trabajadores rurales con salarios de pobreza"},{"id":"i4","texto":"Enfermedades cardíacas por exceso de sodio"},{"id":"i5","texto":"Nitrógeno de fertilizantes que contamina el agua"},{"id":"i6","texto":"Desmonte para ampliar cultivos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g2"},"explicacion":"Los costos ocultos cruzan salud, ambiente y justicia social."}},{"slug":"consumo-4.s2.p9","orden":9,"grupo":"consumo-4.s2.p9","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Contar los costos ocultos significa que la comida saludable tiene que ser más cara.","razones":[{"id":"r1","texto":"Porque puede llevar a abaratar lo saludable y redirigir subsidios"},{"id":"r2","texto":"Porque la comida saludable no tiene costos"},{"id":"r3","texto":"Porque los costos ocultos no existen"}]},"solucion":{"valor":false,"explicacion":"Al contrario: muchas veces muestra que conviene abaratar la comida saludable y dejar de subsidiar la que genera más costos. El objetivo es decidir con información completa.","clave":["r1"]}},{"slug":"consumo-4.s2.p10","orden":10,"grupo":"consumo-4.s2.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas pueden reducir los costos ocultos de la comida? Marcá todas.","opciones":[{"id":"o1","texto":"Abaratar frutas y verduras frescas"},{"id":"o2","texto":"Reducir el uso excesivo de fertilizantes"},{"id":"o3","texto":"Mejorar los ingresos de trabajadores rurales"},{"id":"o4","texto":"Subsidiar más los productos ultraprocesados"},{"id":"o5","texto":"Ocultar la información nutricional"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Atacar los costos ocultos es cambiar lo que se subsidia, cómo se produce y qué información llega a quien compra."}},{"slug":"consumo-4.s2.p11","orden":11,"grupo":"consumo-4.s2.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herramienta con el costo oculto que ataca.","izquierda":[{"id":"a1","texto":"Etiquetado frontal de alimentos"},{"id":"a2","texto":"Reducir fertilizantes nitrogenados"},{"id":"a3","texto":"Salarios justos en la cadena"},{"id":"a4","texto":"Frenar desmontes"}],"derecha":[{"id":"b1","texto":"Salud, por información a quien compra"},{"id":"b2","texto":"Contaminación del agua"},{"id":"b3","texto":"Pobreza rural"},{"id":"b4","texto":"Pérdida de bosques y emisiones"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada costo oculto pide una herramienta distinta."}},{"slug":"consumo-4.s2.p12","orden":12,"grupo":"consumo-4.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este titular y su bajada y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La FAO estimó costos ocultos de al menos 10 billones de dólares por año."},{"id":"s2","texto":"La mayor parte de esos costos es por el transporte de alimentos."},{"id":"s3","texto":"Una parte de los costos ocultos es ambiental."},{"id":"s4","texto":"Los costos ocultos ya están incluidos en los precios del súper."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los costos ocultos se miden para poder decidir mejor.","por_opcion":{"s2":"La mayor parte, un 73 %, es por dietas poco saludables.","s4":"Justamente no lo están: por eso se llaman ocultos."}}},{"slug":"consumo-4.s2.p13","orden":13,"grupo":"consumo-4.s2.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Según la FAO, los costos ocultos de la comida suman al menos 10 {{0}} de dólares por año; el mayor es de {{1}}; y cerca del 20 % es {{2}}.","banco":[{"id":"w1","texto":"billones"},{"id":"w2","texto":"salud"},{"id":"w3","texto":"ambiental"},{"id":"w4","texto":"miles"},{"id":"w5","texto":"transporte"},{"id":"w6","texto":"publicitario"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos clave del informe de la FAO sobre costos ocultos."}}]},{"slug":"consumo-4.s3","orden":3,"tipo":"leccion","titulo_es":"Ponerle precio a la contaminación","bajada_es":"Impuestos al carbono, mercados de emisiones y el principio de que quien contamina paga.","minutos":11,"pasos":[{"slug":"consumo-4.s3.p1","orden":1,"grupo":"consumo-4.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quien contamina paga","cuerpo":["Una forma de corregir una externalidad es que quien la causa la pague. En Argentina, la Ley General del Ambiente establece que quien genera efectos degradantes en el ambiente es responsable de los costos de prevenirlos y recomponerlos. Aplicado al clima, esto lleva a ponerle un precio a las emisiones de gases de efecto invernadero."]},"solucion":{}},{"slug":"consumo-4.s3.p2","orden":2,"grupo":"consumo-4.s3.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dos herramientas","cuerpo":["Hay dos formas principales de poner precio al carbono. Un impuesto al carbono fija un precio por tonelada emitida: se sabe cuánto cuesta, pero no exactamente cuánto bajarán las emisiones. Un mercado de emisiones fija un tope total de emisiones y reparte o subasta permisos que se pueden comprar y vender: se sabe cuánto se emitirá como máximo, pero el precio varía. La Unión Europea tiene un mercado de emisiones desde 2005.","Según el Banco Mundial, en 2026 los precios al carbono cubren casi el 30 % de las emisiones mundiales, y en 2025 recaudaron más de 100.000 millones de dólares para los presupuestos públicos."]},"solucion":{}},{"slug":"consumo-4.s3.p3","orden":3,"grupo":"consumo-4.s3.p3","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herramienta con su característica.","izquierda":[{"id":"a1","texto":"Impuesto al carbono"},{"id":"a2","texto":"Mercado de emisiones"},{"id":"a3","texto":"Principio de quien contamina paga"},{"id":"a4","texto":"Pago por servicios ambientales"}],"derecha":[{"id":"b1","texto":"Precio fijo por tonelada; la reducción varía"},{"id":"b2","texto":"Tope total fijo; el precio varía"},{"id":"b3","texto":"El que causa el daño cubre su costo"},{"id":"b4","texto":"Se remunera a quien conserva"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Herramientas distintas para el mismo objetivo: que los precios reflejen los daños."}},{"slug":"consumo-4.s3.p4","orden":4,"grupo":"consumo-4.s3.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un gobierno quiere asegurarse de que las emisiones no superen cierto límite. ¿Qué herramienta encaja mejor?","opciones":[{"id":"o1","texto":"Un mercado de emisiones con un tope total"},{"id":"o2","texto":"Un impuesto al carbono sin tope de emisiones"},{"id":"o3","texto":"Una campaña publicitaria sobre el clima"},{"id":"o4","texto":"Un subsidio a los combustibles fósiles"}]},"solucion":{"clave":["o1"],"explicacion":"El tope fija la cantidad; el mercado decide el precio.","por_opcion":{"o3":"Puede ayudar, pero no garantiza ningún límite."}}},{"slug":"consumo-4.s3.p5","orden":5,"grupo":"consumo-4.s3.p5","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de las emisiones mundiales está cubierto por algún precio al carbono, según el Banco Mundial.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":30,"banda":"lineal","explicacion":"Casi el 30 %, según el informe de 2026 del Banco Mundial. La mayor parte de las emisiones todavía no tiene precio."}},{"slug":"consumo-4.s3.p6","orden":6,"grupo":"consumo-4.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"En Argentina","cuerpo":["Argentina tiene un impuesto al dióxido de carbono sobre los combustibles líquidos y el carbón, creado por la Ley 27.430, de 2017. Su valor por tonelada es bajo comparado con el de otros países y con los daños estimados del CO₂, pero es una herramienta que ya existe y que puede ajustarse."]},"solucion":{}},{"slug":"consumo-4.s3.p7","orden":7,"grupo":"consumo-4.s3.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cada litro de nafta emite 2,3 kg de CO₂ y el impuesto es de 10 dólares por tonelada de CO₂, ¿cuántos dólares de impuesto corresponden a 1.000 litros? Redondeá a un decimal.","unidad":"dólares","decimales":1,"contexto":"1000 litros; 2,3 kg/L; 10 USD por tonelada."},"solucion":{"valor":23,"tolerancia":0.1,"explicacion":"1.000 × 2,3 = 2.300 kg = 2,3 t; × 10 = 23 dólares."}},{"slug":"consumo-4.s3.p7.v2","orden":7,"grupo":"consumo-4.s3.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cada litro de nafta emite 2,3 kg de CO₂ y el impuesto es de 20 dólares por tonelada de CO₂, ¿cuántos dólares de impuesto corresponden a 2.000 litros? Redondeá a un decimal.","unidad":"dólares","decimales":1,"contexto":"2000 litros; 2,3 kg/L; 20 USD por tonelada."},"solucion":{"valor":92,"tolerancia":0.1,"explicacion":"2.000 × 2,3 = 4.600 kg = 4,6 t; × 20 = 92 dólares."}},{"slug":"consumo-4.s3.p7.v3","orden":7,"grupo":"consumo-4.s3.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cada litro de nafta emite 2,3 kg de CO₂ y el impuesto es de 50 dólares por tonelada de CO₂, ¿cuántos dólares de impuesto corresponden a 500 litros? Redondeá a un decimal.","unidad":"dólares","decimales":1,"contexto":"500 litros; 2,3 kg/L; 50 USD por tonelada."},"solucion":{"valor":57.5,"tolerancia":0.1,"explicacion":"500 × 2,3 = 1.150 kg = 1,15 t; × 50 = 57,5 dólares."}},{"slug":"consumo-4.s3.p8","orden":8,"grupo":"consumo-4.s3.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un impuesto al carbono reduce emisiones.","items":[{"id":"i1","texto":"Se cobra un impuesto por tonelada de CO₂"},{"id":"i2","texto":"Los productos con más emisiones suben de precio"},{"id":"i3","texto":"Las empresas buscan procesos que emitan menos"},{"id":"i4","texto":"Las personas eligen más las opciones bajas en carbono"},{"id":"i5","texto":"Las emisiones totales bajan"},{"id":"i6","texto":"Las emisiones suben porque todo es más caro"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El precio envía una señal a millones de decisiones a la vez."}},{"slug":"consumo-4.s3.p9","orden":9,"grupo":"consumo-4.s3.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un impuesto al carbono le dice a cada empresa exactamente qué tecnología usar.","razones":[{"id":"r1","texto":"Porque fija un precio y deja elegir cómo reducir"},{"id":"r2","texto":"Porque prohíbe todas las tecnologías"},{"id":"r3","texto":"Porque no tiene ningún efecto en las decisiones"}]},"solucion":{"valor":false,"explicacion":"No: fija un precio y deja que cada una encuentre la forma más barata de reducir. Esa flexibilidad es una de sus ventajas.","clave":["r1"]}},{"slug":"consumo-4.s3.p10","orden":10,"grupo":"consumo-4.s3.p10","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una empresa puede reducir sus emisiones a un costo de 20 dólares por tonelada. El impuesto al carbono es de 50. ¿Qué le conviene?","opciones":[{"id":"o1","texto":"Reducir, porque le cuesta menos que pagar"},{"id":"o2","texto":"Pagar el impuesto y no cambiar nada en absoluto"},{"id":"o3","texto":"Emitir más para compensar el gasto"},{"id":"o4","texto":"Cerrar la empresa de inmediato"}]},"solucion":{"clave":["o1"],"explicacion":"El impuesto hace que reducir sea negocio cuando cuesta menos que pagar: así se logran las reducciones más baratas primero.","por_opcion":{"o3":"Emitir más le costaría 50 dólares por cada tonelada extra."}}},{"slug":"consumo-4.s3.p11","orden":11,"grupo":"consumo-4.s3.p11","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué ventaja tiene cada herramienta?","grupos":[{"id":"g1","nombre":"Impuesto al carbono"},{"id":"g2","nombre":"Mercado de emisiones"}],"items":[{"id":"i1","texto":"Se sabe de antemano cuánto cuesta cada tonelada"},{"id":"i2","texto":"Se sabe el máximo total de emisiones"},{"id":"i3","texto":"Es simple de aplicar sobre los combustibles"},{"id":"i4","texto":"Las empresas que reducen más pueden vender permisos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Cada diseño tiene ventajas; muchos países combinan ambos con otras regulaciones."}},{"slug":"consumo-4.s3.p12","orden":12,"grupo":"consumo-4.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este debate y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La Unión Europea tiene un mercado de emisiones desde 2005."},{"id":"s2","texto":"Casi todas las emisiones del mundo ya tienen un precio."},{"id":"s3","texto":"Argentina tiene un impuesto al CO₂ sobre combustibles."},{"id":"s4","texto":"Un mercado de emisiones fija el precio exacto del carbono."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer cómo funcionan estas herramientas permite discutirlas con fundamento.","por_opcion":{"s2":"Solo cerca del 30 % está cubierto.","s4":"Fija el tope; el precio varía según la oferta y la demanda."}}},{"slug":"consumo-4.s3.p13","orden":13,"grupo":"consumo-4.s3.p13","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué puede hacer un gobierno con lo que recauda un impuesto al carbono? Marcá todas las opciones razonables.","opciones":[{"id":"o1","texto":"Devolverlo en partes iguales a cada habitante"},{"id":"o2","texto":"Invertir en transporte público"},{"id":"o3","texto":"Bajar otros impuestos"},{"id":"o4","texto":"Ayudar a los hogares de menores ingresos"},{"id":"o5","texto":"Subsidiar más combustibles fósiles"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Usar lo recaudado para subsidiar más fósiles anularía la señal del impuesto."}},{"slug":"consumo-4.s3.p14","orden":14,"grupo":"consumo-4.s3.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un precio fijo por tonelada emitida es un {{0}} al carbono; un tope total con permisos que se compran y venden es un {{1}} de emisiones; y en Argentina, el impuesto al CO₂ lo creó la Ley {{2}}.","banco":[{"id":"w1","texto":"impuesto"},{"id":"w2","texto":"mercado"},{"id":"w3","texto":"27.430"},{"id":"w4","texto":"subsidio"},{"id":"w5","texto":"desfile"},{"id":"w6","texto":"26.331"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas clave para entender el precio al carbono."}}]},{"slug":"consumo-4.s4","orden":4,"tipo":"leccion","titulo_es":"Subsidios que empujan al revés","bajada_es":"Cuando el dinero público abarata lo que contamina: combustibles, pesca y señales que hay que corregir con cuidado.","minutos":11,"pasos":[{"slug":"consumo-4.s4.p1","orden":1,"grupo":"consumo-4.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Siete billones","cuerpo":["Según el Fondo Monetario Internacional, en 2022 los subsidios a los combustibles fósiles en el mundo sumaron unos 7 billones de dólares (7 millones de millones), alrededor del 7 % del producto mundial. De eso, unos 1,3 billones fueron subsidios explícitos: vender la energía por debajo de su costo de producción. El resto, la mayor parte, son subsidios implícitos: no cobrar los daños ambientales y de salud que causan esos combustibles."],"destacado":{"valor":"≈ 7 billones USD","texto":"sumaron los subsidios a los combustibles fósiles en 2022, contando los daños no cobrados, según el FMI."}},"solucion":{}},{"slug":"consumo-4.s4.p2","orden":2,"grupo":"consumo-4.s4.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada tipo de subsidio con su definición.","izquierda":[{"id":"a1","texto":"Subsidio explícito"},{"id":"a2","texto":"Subsidio implícito"},{"id":"a3","texto":"Subsidio focalizado"},{"id":"a4","texto":"Subsidio generalizado"}],"derecha":[{"id":"b1","texto":"Vender por debajo del costo de producción"},{"id":"b2","texto":"No cobrar los daños ambientales y de salud"},{"id":"b3","texto":"Ayuda dirigida a quien más la necesita"},{"id":"b4","texto":"Beneficia a todos por igual, también a quien más consume"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Distinguir tipos de subsidio ayuda a discutir cuáles corregir y cómo."}},{"slug":"consumo-4.s4.p3","orden":3,"grupo":"consumo-4.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los subsidios a los fósiles suman 7 billones de dólares y 1,3 son explícitos, ¿qué porcentaje es implícito? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"1.3 billones explícitos de 7 billones totales."},"solucion":{"valor":81,"tolerancia":1,"explicacion":"(7 − 1,3) ÷ 7 × 100 ≈ 81 %. La mayor parte del subsidio es el daño que no se cobra."}},{"slug":"consumo-4.s4.p3.v2","orden":3,"grupo":"consumo-4.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"De 7 billones de dólares de subsidios a los fósiles, 1,3 son explícitos. ¿Qué porcentaje corresponde a daños no cobrados? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"1.3 billones explícitos de 7 billones totales."},"solucion":{"valor":81,"tolerancia":1,"explicacion":"(7 − 1,3) ÷ 7 × 100 ≈ 81 %. La mayor parte del subsidio es el daño que no se cobra."}},{"slug":"consumo-4.s4.p3.v3","orden":3,"grupo":"consumo-4.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 1,3 billones de subsidios explícitos sobre un total de 7 billones, ¿qué porcentaje del total son subsidios implícitos? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"1.3 billones explícitos de 7 billones totales."},"solucion":{"valor":81,"tolerancia":1,"explicacion":"(7 − 1,3) ÷ 7 × 100 ≈ 81 %. La mayor parte del subsidio es el daño que no se cobra."}},{"slug":"consumo-4.s4.p4","orden":4,"grupo":"consumo-4.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué es un problema","cuerpo":["Un subsidio a los combustibles abarata lo que contamina y hace más difícil que compitan las alternativas limpias. Además, cuando es generalizado, beneficia más a quien más consume, que suele tener más ingresos: quien tiene dos autos y una casa grande recibe más subsidio que quien no tiene auto. Algo parecido pasa con los subsidios a la pesca que aumentan la capacidad de las flotas y empujan la sobrepesca."]},"solucion":{}},{"slug":"consumo-4.s4.p5","orden":5,"grupo":"consumo-4.s4.p5","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un subsidio generalizado a la nafta favorece a quien más tiene.","items":[{"id":"i1","texto":"La nafta se vende por debajo de su costo"},{"id":"i2","texto":"Cada litro cargado recibe subsidio"},{"id":"i3","texto":"Quien tiene más autos y maneja más, carga más litros"},{"id":"i4","texto":"Recibe más subsidio que quien no tiene auto"},{"id":"i5","texto":"El subsidio beneficia más a los hogares de mayores ingresos"},{"id":"i6","texto":"Quien no tiene auto recibe el mayor subsidio"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un subsidio generalizado a la energía suele ser caro e injusto a la vez."}},{"slug":"consumo-4.s4.p6","orden":6,"grupo":"consumo-4.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cada litro de nafta tiene 50 pesos de subsidio, un hogar que carga 2.000 litros por año y otro que carga 100, ¿cuántos pesos más de subsidio recibe el primero?","unidad":"pesos","decimales":0,"contexto":"2000 y 100 litros por año; 50 pesos de subsidio por litro."},"solucion":{"valor":95000,"tolerancia":1900,"explicacion":"(2.000 − 100) × 50 = 95.000 pesos más por año para quien más consume."}},{"slug":"consumo-4.s4.p6.v2","orden":6,"grupo":"consumo-4.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cada litro de nafta tiene 80 pesos de subsidio, un hogar que carga 1.500 litros por año y otro que carga 0, ¿cuántos pesos más de subsidio recibe el primero?","unidad":"pesos","decimales":0,"contexto":"1500 y 0 litros por año; 80 pesos de subsidio por litro."},"solucion":{"valor":120000,"tolerancia":2400,"explicacion":"(1.500 − 0) × 80 = 120.000 pesos más por año para quien más consume."}},{"slug":"consumo-4.s4.p6.v3","orden":6,"grupo":"consumo-4.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cada litro de nafta tiene 40 pesos de subsidio, un hogar que carga 3.000 litros por año y otro que carga 200, ¿cuántos pesos más de subsidio recibe el primero?","unidad":"pesos","decimales":0,"contexto":"3000 y 200 litros por año; 40 pesos de subsidio por litro."},"solucion":{"valor":112000,"tolerancia":2240,"explicacion":"(3.000 − 200) × 40 = 112.000 pesos más por año para quien más consume."}},{"slug":"consumo-4.s4.p7","orden":7,"grupo":"consumo-4.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reformar con cuidado","cuerpo":["Quitar un subsidio de golpe puede golpear a los hogares más pobres, que gastan una parte mayor de su ingreso en energía y transporte. Por eso, las reformas que funcionan suelen ser graduales, avisadas con tiempo, y acompañadas de ayudas focalizadas: tarifas sociales, transferencias a los hogares de menores ingresos y mejoras en el transporte público."]},"solucion":{}},{"slug":"consumo-4.s4.p8","orden":8,"grupo":"consumo-4.s4.p8","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos de una reforma de subsidios bien diseñada.","items":[{"id":"i1","texto":"Identificar quién recibe hoy el subsidio"},{"id":"i2","texto":"Diseñar ayudas focalizadas para los hogares vulnerables"},{"id":"i3","texto":"Anunciar el cambio con tiempo"},{"id":"i4","texto":"Reducir el subsidio de forma gradual"},{"id":"i5","texto":"Evaluar los efectos y ajustar"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Proteger a quien más lo necesita es lo que hace posible y justa la reforma."}},{"slug":"consumo-4.s4.p9","orden":9,"grupo":"consumo-4.s4.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Eliminar de golpe todos los subsidios a la energía, sin ninguna ayuda, es siempre la mejor política ambiental.","razones":[{"id":"r1","texto":"Porque sin ayudas golpea a los hogares más pobres"},{"id":"r2","texto":"Porque los subsidios no tienen ningún efecto ambiental"},{"id":"r3","texto":"Porque los hogares pobres no usan energía"}]},"solucion":{"valor":false,"explicacion":"Puede golpear a los hogares más pobres y generar rechazo que frene la reforma. Las reformas graduales con ayudas focalizadas son más justas y duraderas.","clave":["r1"]}},{"slug":"consumo-4.s4.p10","orden":10,"grupo":"consumo-4.s4.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este subsidio empuja hacia más o menos contaminación?","grupos":[{"id":"g1","nombre":"Empuja a contaminar más"},{"id":"g2","nombre":"Empuja a contaminar menos"}],"items":[{"id":"i1","texto":"Gasoil más barato que su costo para todos"},{"id":"i2","texto":"Crédito barato para aislar techos"},{"id":"i3","texto":"Ayudas para agrandar flotas pesqueras"},{"id":"i4","texto":"Tarifa social con un bloque básico de consumo"},{"id":"i5","texto":"Electricidad regalada sin límite de consumo"},{"id":"i6","texto":"Boleto de transporte público subsidiado"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"No todo subsidio es malo: depende de qué abarata y a quién ayuda."}},{"slug":"consumo-4.s4.p11","orden":11,"grupo":"consumo-4.s4.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un gobierno subsidia la compra de barcos más grandes para su flota pesquera. ¿Qué efecto probable tiene?","opciones":[{"id":"o1","texto":"Aumenta la presión sobre los peces"},{"id":"o2","texto":"Recupera las poblaciones de peces"},{"id":"o3","texto":"Baja el precio del pescado para siempre"},{"id":"o4","texto":"Reduce la cantidad de horas de pesca"}]},"solucion":{"clave":["o1"],"explicacion":"Lo viste en la unidad de pesca: subsidiar capacidad empuja la sobrepesca.","por_opcion":{"o3":"Puede bajarlo al principio, pero si hay sobrepesca, la pesca después cae."}}},{"slug":"consumo-4.s4.p12","orden":12,"grupo":"consumo-4.s4.p12","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué características hacen buena a una tarifa social de energía? Marcá todas.","opciones":[{"id":"o1","texto":"Está dirigida a los hogares vulnerables"},{"id":"o2","texto":"Cubre un consumo básico razonable"},{"id":"o3","texto":"Es fácil de solicitar"},{"id":"o4","texto":"Regala energía sin ningún límite"},{"id":"o5","texto":"Se otorga a todos los hogares por igual"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Una buena tarifa social protege lo esencial sin subsidiar el derroche."}},{"slug":"consumo-4.s4.p13","orden":13,"grupo":"consumo-4.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Según el FMI, los subsidios a los fósiles sumaron unos 7 billones de dólares en 2022."},{"id":"s2","texto":"Los subsidios generalizados benefician más a quienes menos consumen."},{"id":"s3","texto":"Una tarifa social puede proteger a los hogares vulnerables."},{"id":"s4","texto":"La mayor parte de esos subsidios son explícitos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los subsidios son herramientas poderosas: bien diseñados ayudan, mal diseñados contaminan.","por_opcion":{"s2":"Benefician más a quienes más consumen, que suelen tener más ingresos.","s4":"La mayor parte son implícitos: daños que no se cobran."}}},{"slug":"consumo-4.s4.p14","orden":14,"grupo":"consumo-4.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"No cobrar los daños de los combustibles es un subsidio {{0}}; la ayuda dirigida a quien más la necesita es un subsidio {{1}}; y las reformas que funcionan suelen ser {{2}}.","banco":[{"id":"w1","texto":"implícito"},{"id":"w2","texto":"focalizado"},{"id":"w3","texto":"graduales"},{"id":"w4","texto":"explícito"},{"id":"w5","texto":"general"},{"id":"w6","texto":"secretas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para pensar los subsidios con criterio ambiental y social."}}]},{"slug":"consumo-4.s5","orden":5,"tipo":"leccion","titulo_es":"Decidir con el costo total","bajada_es":"Lo barato que sale caro, cómo comparar productos en toda su vida y quién paga cada política.","minutos":12,"pasos":[{"slug":"consumo-4.s5.p1","orden":1,"grupo":"consumo-4.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Costo total de uso","cuerpo":["Para comparar dos productos no alcanza con mirar el precio de compra: hay que sumar lo que cuesta usarlos durante toda su vida (energía, agua, mantenimiento, repuestos) y cuánto duran. Una heladera eficiente puede costar más al comprarla y menos en total, porque gasta mucho menos electricidad cada año. Lo mismo pasa con las lámparas LED frente a las incandescentes."]},"solucion":{}},{"slug":"consumo-4.s5.p2","orden":2,"grupo":"consumo-4.s5.p2","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Dos heladeras","planteo":"Heladera A: cuesta 800 mil pesos y gasta 400 kWh por año. Heladera B: cuesta 950 mil y gasta 250 kWh por año. La electricidad cuesta 150 pesos por kWh y ambas duran 10 años.","pasos":["A: 800.000 + 400 × 150 × 10 = 800.000 + 600.000 = 1.400.000 pesos.","B: 950.000 + 250 × 150 × 10 = 950.000 + 375.000 = 1.325.000 pesos.","B cuesta 150 mil más al comprarla, pero 75 mil menos en total, y ahorra 1.500 kWh."],"resultado":"La más cara al comprar resulta la más barata en toda su vida. Precios de ejemplo."},"solucion":{}},{"slug":"consumo-4.s5.p3","orden":3,"grupo":"consumo-4.s5.p3","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Heladera A: 500 mil pesos y 300 kWh por año. Heladera B: 600 mil pesos y 200 kWh por año. Con 100 pesos por kWh y 10 años de uso, ¿cuántos pesos ahorra en total la B frente a la A?","unidad":"pesos","decimales":0,"contexto":"A 500 mil y 300 kWh/año; B 600 mil y 200 kWh/año; 100 $/kWh; 10 años."},"solucion":{"valor":0,"tolerancia":0.5,"explicacion":"A: 800.000. B: 800.000. Diferencia: 0 pesos a favor de la B. Precios de ejemplo."}},{"slug":"consumo-4.s5.p3.v2","orden":3,"grupo":"consumo-4.s5.p3","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Heladera A: 700 mil pesos y 450 kWh por año. Heladera B: 850 mil pesos y 280 kWh por año. Con 120 pesos por kWh y 12 años de uso, ¿cuántos pesos ahorra en total la B frente a la A?","unidad":"pesos","decimales":0,"contexto":"A 700 mil y 450 kWh/año; B 850 mil y 280 kWh/año; 120 $/kWh; 12 años."},"solucion":{"valor":94800,"tolerancia":1896,"explicacion":"A: 1.348.000. B: 1.253.200. Diferencia: 94.800 pesos a favor de la B. Precios de ejemplo."}},{"slug":"consumo-4.s5.p3.v3","orden":3,"grupo":"consumo-4.s5.p3","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Heladera A: 400 mil pesos y 350 kWh por año. Heladera B: 480 mil pesos y 220 kWh por año. Con 90 pesos por kWh y 10 años de uso, ¿cuántos pesos ahorra en total la B frente a la A?","unidad":"pesos","decimales":0,"contexto":"A 400 mil y 350 kWh/año; B 480 mil y 220 kWh/año; 90 $/kWh; 10 años."},"solucion":{"valor":37000,"tolerancia":740,"explicacion":"A: 715.000. B: 678.000. Diferencia: 37.000 pesos a favor de la B. Precios de ejemplo."}},{"slug":"consumo-4.s5.p4","orden":4,"grupo":"consumo-4.s5.p4","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hay que sumar para calcular el costo total de un electrodoméstico? Marcá todo.","opciones":[{"id":"o1","texto":"El precio de compra"},{"id":"o2","texto":"La energía que consume en toda su vida"},{"id":"o3","texto":"Reparaciones y repuestos"},{"id":"o4","texto":"El color de la caja"},{"id":"o5","texto":"La publicidad que vimos del producto"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El precio de compra es solo el comienzo de la cuenta."}},{"slug":"consumo-4.s5.p5","orden":5,"grupo":"consumo-4.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuando no se puede elegir","cuerpo":["Hay una trampa: los hogares con menos ingresos muchas veces no pueden pagar el producto más caro y eficiente, aunque a la larga les ahorraría dinero. Terminan pagando más por la energía durante años. Por eso sirven los créditos accesibles para equipos eficientes, los programas de recambio y las normas que sacan del mercado los aparatos que más consumen."]},"solucion":{}},{"slug":"consumo-4.s5.p6","orden":6,"grupo":"consumo-4.s5.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué un hogar de bajos ingresos puede terminar pagando más por la energía?","opciones":[{"id":"o1","texto":"No puede pagar el equipo eficiente al comprar"},{"id":"o2","texto":"Porque la electricidad es más cara en esos hogares"},{"id":"o3","texto":"Porque no le interesa ahorrar energía"},{"id":"o4","texto":"Porque los equipos eficientes no existen"}]},"solucion":{"clave":["o1"],"explicacion":"La barrera no es la información sino el dinero disponible hoy: las políticas pueden romper esa trampa.","por_opcion":{"o3":"No es falta de interés: es falta de dinero para invertir al principio."}}},{"slug":"consumo-4.s5.p7","orden":7,"grupo":"consumo-4.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quién paga cada política","cuerpo":["Toda política que cambia precios tiene ganadores y perdedores. Un impuesto al carbono sin compensación puede pesar más, en proporción, sobre los hogares de menores ingresos: se llama efecto regresivo. Por eso muchas propuestas devuelven lo recaudado en partes iguales a cada habitante: como los hogares ricos emiten más, pagan más impuesto del que reciben, y muchos hogares pobres terminan recibiendo más de lo que pagan."]},"solucion":{}},{"slug":"consumo-4.s5.p8","orden":8,"grupo":"consumo-4.s5.p8","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país tiene dos hogares: uno emite 2 t de CO₂ y otro 10 t. El impuesto es de 50 dólares por tonelada y lo recaudado se devuelve en partes iguales. ¿Cuántos dólares netos gana el hogar que emite 2 t (lo que recibe menos lo que paga)?","unidad":"dólares","decimales":0,"contexto":"Hogares que emiten 2 y 10 t; 50 USD/t; devolución en partes iguales."},"solucion":{"valor":200,"tolerancia":4,"explicacion":"Se recaudan (2 + 10) × 50 = 600 dólares; cada hogar recibe 300. El que emite poco pagó 100: gana 200 dólares netos."}},{"slug":"consumo-4.s5.p8.v2","orden":8,"grupo":"consumo-4.s5.p8","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país tiene dos hogares: uno emite 3 t de CO₂ y otro 12 t. El impuesto es de 40 dólares por tonelada y lo recaudado se devuelve en partes iguales. ¿Cuántos dólares netos gana el hogar que emite 3 t (lo que recibe menos lo que paga)?","unidad":"dólares","decimales":0,"contexto":"Hogares que emiten 3 y 12 t; 40 USD/t; devolución en partes iguales."},"solucion":{"valor":180,"tolerancia":3.6,"explicacion":"Se recaudan (3 + 12) × 40 = 600 dólares; cada hogar recibe 300. El que emite poco pagó 120: gana 180 dólares netos."}},{"slug":"consumo-4.s5.p8.v3","orden":8,"grupo":"consumo-4.s5.p8","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país tiene dos hogares: uno emite 1 t de CO₂ y otro 8 t. El impuesto es de 60 dólares por tonelada y lo recaudado se devuelve en partes iguales. ¿Cuántos dólares netos gana el hogar que emite 1 t (lo que recibe menos lo que paga)?","unidad":"dólares","decimales":0,"contexto":"Hogares que emiten 1 y 8 t; 60 USD/t; devolución en partes iguales."},"solucion":{"valor":210,"tolerancia":4.2,"explicacion":"Se recaudan (1 + 8) × 60 = 540 dólares; cada hogar recibe 270. El que emite poco pagó 60: gana 210 dólares netos."}},{"slug":"consumo-4.s5.p9","orden":9,"grupo":"consumo-4.s5.p9","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta medida es regresiva (pesa más sobre quien tiene menos) o progresiva?","grupos":[{"id":"g1","nombre":"Regresiva"},{"id":"g2","nombre":"Progresiva"}],"items":[{"id":"i1","texto":"Un impuesto a la energía sin ninguna compensación"},{"id":"i2","texto":"Un impuesto al carbono que devuelve lo recaudado en partes iguales"},{"id":"i3","texto":"Quitar de golpe la tarifa social"},{"id":"i4","texto":"Crédito subsidiado para heladeras eficientes en barrios populares"},{"id":"i5","texto":"Transporte público financiado con un cobro por congestión"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"El diseño de una política decide si es justa, no solo su objetivo ambiental."}},{"slug":"consumo-4.s5.p10","orden":10,"grupo":"consumo-4.s5.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una política ambiental puede ser a la vez buena para el ambiente y justa con los hogares de menores ingresos.","razones":[{"id":"r1","texto":"Porque el diseño puede proteger a quien tiene menos"},{"id":"r2","texto":"Porque toda política ambiental perjudica a los pobres"},{"id":"r3","texto":"Porque la justicia no tiene relación con el ambiente"}]},"solucion":{"valor":true,"explicacion":"Con un buen diseño —compensaciones, ayudas focalizadas, inversión pública— se pueden lograr ambos objetivos.","clave":["r1"]}},{"slug":"consumo-4.s5.p11","orden":11,"grupo":"consumo-4.s5.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Costo total de uso"},{"id":"a2","texto":"Efecto regresivo"},{"id":"a3","texto":"Dividendo de carbono"},{"id":"a4","texto":"Programa de recambio"}],"derecha":[{"id":"b1","texto":"Precio más lo que cuesta usarlo toda su vida"},{"id":"b2","texto":"Pesa más, en proporción, sobre quien tiene menos"},{"id":"b3","texto":"Devolver lo recaudado en partes iguales"},{"id":"b4","texto":"Ayuda para cambiar equipos ineficientes"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Herramientas para decidir y para diseñar políticas con justicia."}},{"slug":"consumo-4.s5.p12","orden":12,"grupo":"consumo-4.s5.p12","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una lámpara incandescente de 60 W se reemplaza por una LED de 9 W que da la misma luz. Si está prendida 4 horas por día, ¿cuántos kWh por año se ahorran? Redondeá a un decimal.","unidad":"kWh","decimales":1,"contexto":"60 W contra 9 W; 4 horas por día."},"solucion":{"valor":74.5,"tolerancia":0.1,"explicacion":"(60 − 9) W × 4 h × 365 días ÷ 1.000 ≈ 74,5 kWh por año, con una sola lámpara. La LED cuesta un poco más y se paga sola en poco tiempo."}},{"slug":"consumo-4.s5.p12.v2","orden":12,"grupo":"consumo-4.s5.p12","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una lámpara incandescente de 100 W se reemplaza por una LED de 14 W que da la misma luz. Si está prendida 5 horas por día, ¿cuántos kWh por año se ahorran? Redondeá a un decimal.","unidad":"kWh","decimales":1,"contexto":"100 W contra 14 W; 5 horas por día."},"solucion":{"valor":157,"tolerancia":0.1,"explicacion":"(100 − 14) W × 5 h × 365 días ÷ 1.000 ≈ 157 kWh por año, con una sola lámpara. La LED cuesta un poco más y se paga sola en poco tiempo."}},{"slug":"consumo-4.s5.p12.v3","orden":12,"grupo":"consumo-4.s5.p12","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una lámpara incandescente de 40 W se reemplaza por una LED de 6 W que da la misma luz. Si está prendida 6 horas por día, ¿cuántos kWh por año se ahorran? Redondeá a un decimal.","unidad":"kWh","decimales":1,"contexto":"40 W contra 6 W; 6 horas por día."},"solucion":{"valor":74.5,"tolerancia":0.1,"explicacion":"(40 − 6) W × 6 h × 365 días ÷ 1.000 ≈ 74,5 kWh por año, con una sola lámpara. La LED cuesta un poco más y se paga sola en poco tiempo."}},{"slug":"consumo-4.s5.p13","orden":13,"grupo":"consumo-4.s5.p13","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para comparar dos productos por su costo total.","items":[{"id":"i1","texto":"Anotar el precio de compra de cada uno"},{"id":"i2","texto":"Estimar cuánto consume cada uno por año"},{"id":"i3","texto":"Multiplicar por la tarifa y los años de vida útil"},{"id":"i4","texto":"Sumar compra y uso de cada producto"},{"id":"i5","texto":"Comparar los totales"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una cuenta simple que cambia muchas decisiones de compra."}},{"slug":"consumo-4.s5.p14","orden":14,"grupo":"consumo-4.s5.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta propuesta y marcá lo que conviene cambiar.","segmentos":[{"id":"s1","texto":"Pondremos un impuesto al carbono y devolveremos lo recaudado en partes iguales."},{"id":"s2","texto":"Eliminaremos la tarifa social para que todos paguen lo mismo."},{"id":"s3","texto":"Ofreceremos crédito barato para heladeras eficientes."},{"id":"s4","texto":"Solo miraremos el precio de compra al licitar equipos para escuelas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Buenas políticas miran el costo total y a quién le toca pagarlo.","por_opcion":{"s2":"Golpea a los hogares vulnerables; conviene focalizar, no eliminar.","s4":"Conviene mirar el costo total, incluida la energía."}}},{"slug":"consumo-4.s5.p15","orden":15,"grupo":"consumo-4.s5.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El precio más lo que cuesta usar un producto toda su vida es el costo {{0}}; una medida que pesa más sobre quien tiene menos es {{1}}; y devolver lo recaudado en partes iguales es un {{2}} de carbono.","banco":[{"id":"w1","texto":"total"},{"id":"w2","texto":"regresiva"},{"id":"w3","texto":"dividendo"},{"id":"w4","texto":"inicial"},{"id":"w5","texto":"progresiva"},{"id":"w6","texto":"descuento"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos para decidir y diseñar políticas justas."}}]},{"slug":"consumo-4.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: lo que el precio no dice","bajada_es":"Externalidades, costos ocultos de la comida, precio al carbono, subsidios y costo total, mezclados.","minutos":8,"pasos":[{"slug":"consumo-4.s6.p1","orden":1,"grupo":"consumo-4.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Lo que el precio no dice». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"consumo-4.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el cobro por descartables","bajada_es":"Una ciudad quiere cobrar un cargo a los vasos y bandejas descartables. Diseñá la medida con números y con justicia.","minutos":10,"pasos":[{"slug":"consumo-4.s7.p1","orden":1,"grupo":"consumo-4.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La propuesta","cuerpo":["En la ciudad se usan 12 millones de vasos y bandejas descartables por año. Su recolección y disposición le cuestan al municipio unos 30 pesos por unidad, que hoy paga toda la ciudad con sus tasas. El concejo propone un cargo de 50 pesos por cada descartable entregado en comercios de comida. Estudios de otras ciudades muestran que un cargo así puede reducir su uso a la mitad. Se discute qué hacer con lo recaudado."]},"solucion":{}},{"slug":"consumo-4.s7.p2","orden":2,"grupo":"consumo-4.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el uso baja a la mitad, ¿cuántos descartables por año se seguirían usando?","unidad":"unidades","decimales":0,"contexto":"12 millones de descartables por año; baja a la mitad."},"solucion":{"valor":6000000,"tolerancia":120000,"explicacion":"12 millones ÷ 2 = 6 millones por año. La mitad del residuo desaparece antes de existir."}},{"slug":"consumo-4.s7.p3","orden":3,"grupo":"consumo-4.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 6 millones de descartables por año y un cargo de 50 pesos, ¿cuántos pesos se recaudarían?","unidad":"pesos","decimales":0,"contexto":"6 millones de unidades; 50 pesos cada una."},"solucion":{"valor":300000000,"tolerancia":6000000,"explicacion":"6.000.000 × 50 = 300 millones de pesos por año."}},{"slug":"consumo-4.s7.p4","orden":4,"grupo":"consumo-4.s7.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué tipo de medida es el cargo por descartables?","opciones":[{"id":"o1","texto":"Un precio que refleja una externalidad"},{"id":"o2","texto":"Un subsidio a los comercios de comida"},{"id":"o3","texto":"Una prohibición total de los descartables"},{"id":"o4","texto":"Un pago por servicios ambientales"}]},"solucion":{"clave":["o1"],"explicacion":"El cargo hace que quien usa el descartable pague parte del costo que hoy paga toda la ciudad.","por_opcion":{"o3":"No prohíbe: pone un precio y deja la opción."}}},{"slug":"consumo-4.s7.p5","orden":5,"grupo":"consumo-4.s7.p5","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿En qué conviene usar lo recaudado? Marcá todas las opciones razonables.","opciones":[{"id":"o1","texto":"Ayudar a los comercios chicos a pasarse a vajilla reutilizable"},{"id":"o2","texto":"Financiar la gestión de residuos y el reciclaje con las cooperativas"},{"id":"o3","texto":"Instalar dispensers de agua en espacios públicos"},{"id":"o4","texto":"Comprar más descartables para los edificios públicos"},{"id":"o5","texto":"Nada: guardarlo sin destino"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Usar lo recaudado para facilitar las alternativas hace la medida más efectiva y más aceptada."}},{"slug":"consumo-4.s7.p6","orden":6,"grupo":"consumo-4.s7.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El cargo podría afectar más a comercios chicos que no pueden invertir en vajilla reutilizable.","razones":[{"id":"r1","texto":"Porque la transición cuesta y no todos pueden pagarla"},{"id":"r2","texto":"Porque los comercios chicos no usan descartables"},{"id":"r3","texto":"Porque el cargo lo pagan solo las grandes cadenas"}]},"solucion":{"valor":true,"explicacion":"Por eso conviene acompañar la medida con ayudas para la transición, financiadas con lo recaudado.","clave":["r1"]}},{"slug":"consumo-4.s7.p7","orden":7,"grupo":"consumo-4.s7.p7","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para implementar bien la medida.","items":[{"id":"i1","texto":"Consultar a comercios, cooperativas y vecinos"},{"id":"i2","texto":"Anunciar el cargo con tiempo"},{"id":"i3","texto":"Ofrecer ayudas para pasarse a reutilizables"},{"id":"i4","texto":"Aplicar el cargo"},{"id":"i5","texto":"Medir la reducción y publicar los resultados"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Consultar, avisar, ayudar, aplicar y medir: así una medida de precio se vuelve legítima."}},{"slug":"consumo-4.s7.p8","orden":8,"grupo":"consumo-4.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El concejo redacta la ordenanza. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Lo recaudado financiará vajilla reutilizable para comercios chicos."},{"id":"s2","texto":"El cargo empieza mañana, sin aviso previo."},{"id":"s3","texto":"Mediremos cada año cuántos descartables se usan."},{"id":"s4","texto":"Lo recaudado se usará para comprar más descartables municipales."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una medida de precio funciona cuando es previsible, justa y coherente con su objetivo.","por_opcion":{"s2":"Conviene anunciarlo con tiempo para que todos se adapten.","s4":"Contradice el objetivo: hay que financiar las alternativas."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"consumo-5","rama":"consumo","orden":5,"nivel":3,"titulo_es":"Consumo, bienestar y suficiencia","bajada_es":"Qué dice la evidencia sobre dinero, cosas y felicidad, qué necesitamos de verdad y cómo vivir bien usando menos del planeta, sin dejar a nadie sin lo básico.","objetivos_es":["Interpretar la evidencia sobre ingreso, materialismo y bienestar","Distinguir necesidades de satisfactores con el enfoque de Max-Neef","Explicar la suficiencia y diferenciarla de la eficiencia","Analizar cómo la publicidad y las normas sociales moldean el consumo","Proponer soluciones colectivas que den bienestar con menos recursos"],"repasa":["consumo-1","consumo-2","consumo-3","comunidad-3"],"requiere_tronco":3,"fuentes":["killingsworth-2023","dittmar-2014","dunn-2011","max-neef-1989","oneill-2018","dona-raworth","ipcc-ar6-demanda","francia-publicidad-fosil","haya-publicidad-fosil","oxfam-clima-2023"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"consumo-5.s1","orden":1,"tipo":"leccion","titulo_es":"Dinero, cosas y bienestar","bajada_es":"Qué dice la investigación sobre ingresos, felicidad, adaptación y materialismo.","minutos":11,"pasos":[{"slug":"consumo-5.s1.p1","orden":1,"grupo":"consumo-5.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cada peso suma menos","cuerpo":["Las encuestas de bienestar muestran que el ingreso importa, pero de una forma particular: la satisfacción crece aproximadamente con cada duplicación del ingreso, no con cada peso. Pasar de no llegar a fin de mes a cubrir lo básico cambia mucho la vida; sumar la misma cantidad a un ingreso alto cambia bastante menos.","En 2023, investigadores que habían llegado a conclusiones opuestas publicaron juntos un análisis: para la mayoría de las personas, el bienestar sigue aumentando con el ingreso más allá de los 100.000 dólares anuales; para una minoría infeliz, deja de mejorar alrededor de ese nivel."]},"solucion":{}},{"slug":"consumo-5.s1.p2","orden":2,"grupo":"consumo-5.s1.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Supongamos que la satisfacción con la vida sube medio punto cada vez que el ingreso se duplica. ¿Cuántos puntos sube si el ingreso pasa de 250.000 a 1.000.000 pesos por mes?","unidad":"puntos","decimales":1,"contexto":"De 250000 a 1000000 pesos; 0,5 puntos por duplicación."},"solucion":{"valor":1,"tolerancia":0.05,"explicacion":"De 250.000 a 1.000.000 hay 2 duplicaciones; 2 × 0,5 = 1 puntos. Valores de ejemplo: para sumar lo mismo, cada vez hace falta el doble de dinero."}},{"slug":"consumo-5.s1.p2.v2","orden":2,"grupo":"consumo-5.s1.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Supongamos que la satisfacción con la vida sube medio punto cada vez que el ingreso se duplica. ¿Cuántos puntos sube si el ingreso pasa de 100.000 a 800.000 pesos por mes?","unidad":"puntos","decimales":1,"contexto":"De 100000 a 800000 pesos; 0,5 puntos por duplicación."},"solucion":{"valor":1.5,"tolerancia":0.05,"explicacion":"De 100.000 a 800.000 hay 3 duplicaciones; 3 × 0,5 = 1,5 puntos. Valores de ejemplo: para sumar lo mismo, cada vez hace falta el doble de dinero."}},{"slug":"consumo-5.s1.p2.v3","orden":2,"grupo":"consumo-5.s1.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Supongamos que la satisfacción con la vida sube medio punto cada vez que el ingreso se duplica. ¿Cuántos puntos sube si el ingreso pasa de 150.000 a 2.400.000 pesos por mes?","unidad":"puntos","decimales":1,"contexto":"De 150000 a 2400000 pesos; 0,5 puntos por duplicación."},"solucion":{"valor":2,"tolerancia":0.05,"explicacion":"De 150.000 a 2.400.000 hay 4 duplicaciones; 4 × 0,5 = 2 puntos. Valores de ejemplo: para sumar lo mismo, cada vez hace falta el doble de dinero."}},{"slug":"consumo-5.s1.p3","orden":3,"grupo":"consumo-5.s1.p3","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un aumento de 100.000 pesos por mes, ¿a quién suele cambiarle más la vida?","opciones":[{"id":"o1","texto":"A un hogar que gana 300.000 que a uno que gana 3.000.000"},{"id":"o2","texto":"A un hogar que gana 3.000.000 que a uno que gana 300.000"},{"id":"o3","texto":"A los dos exactamente igual, porque es la misma plata"},{"id":"o4","texto":"A ninguno, porque el dinero no influye en el bienestar"}]},"solucion":{"clave":["o1"],"explicacion":"Por eso las mejoras de ingreso en los hogares que no cubren lo básico tienen un efecto tan grande.","por_opcion":{"o3":"La misma suma pesa distinto según cuánto se tenía."}}},{"slug":"consumo-5.s1.p4","orden":4,"grupo":"consumo-5.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La cinta que no para","cuerpo":["Nos acostumbramos rápido a lo nuevo: el celular recién comprado entusiasma unas semanas y después pasa a ser \"el celular\". Es la adaptación hedónica. Además, muchas veces medimos lo que tenemos comparándonos con otros. Juntas, adaptación y comparación empujan a querer siempre un poco más.","Un metaanálisis de 2014, con 259 muestras, encontró que las personas con valores más materialistas tienden a reportar menos bienestar. Es una asociación consistente, aunque por sí sola no prueba cuál de las dos cosas causa la otra."]},"solucion":{}},{"slug":"consumo-5.s1.p5","orden":5,"grupo":"consumo-5.s1.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de la adaptación hedónica.","items":[{"id":"i1","texto":"Comprás algo que deseabas mucho"},{"id":"i2","texto":"Al principio da mucha satisfacción"},{"id":"i3","texto":"Con las semanas te acostumbrás"},{"id":"i4","texto":"La satisfacción vuelve a su nivel de antes"},{"id":"i5","texto":"Aparece el deseo de la próxima compra"},{"id":"i6","texto":"La satisfacción de una compra crece con el tiempo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Conocer este mecanismo ayuda a decidir antes de comprar."}},{"slug":"consumo-5.s1.p6","orden":6,"grupo":"consumo-5.s1.p6","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"El metaanálisis de 2014 encontró que el materialismo va junto con menos bienestar. ¿Qué se puede concluir?","opciones":[{"id":"o1","texto":"Que van juntos, aunque no prueba cuál causa cuál"},{"id":"o2","texto":"Que comprar cosas causa siempre infelicidad"},{"id":"o3","texto":"Que ser infeliz hace comprar más, sin ninguna duda"},{"id":"o4","texto":"Que el estudio no sirve porque usó muchas muestras"}]},"solucion":{"clave":["o1"],"explicacion":"Correlación no es causa, como viste en ciencia: la evidencia es sólida, pero hay que leerla con cuidado.","por_opcion":{"o3":"Es posible, pero una asociación no alcanza para afirmarlo."}}},{"slug":"consumo-5.s1.p7","orden":7,"grupo":"consumo-5.s1.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Según la evidencia, el dinero no tiene ninguna relación con el bienestar.","razones":[{"id":"r1","texto":"Porque el bienestar crece con el ingreso, aunque cada peso sume menos"},{"id":"r2","texto":"Porque la felicidad no se puede medir"},{"id":"r3","texto":"Porque las personas ricas son siempre infelices"}]},"solucion":{"valor":false,"explicacion":"Sí tiene relación: el bienestar crece con el ingreso, sobre todo cuando permite cubrir necesidades. Lo que muestra la evidencia es que cada peso extra suma menos, y que no todos los usos del dinero dan lo mismo.","clave":["r1"]}},{"slug":"consumo-5.s1.p8","orden":8,"grupo":"consumo-5.s1.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cómo se gasta también importa","cuerpo":["Una revisión de 2011 sobre cómo gastar para estar mejor recogió varios hallazgos: las experiencias compartidas suelen dar más satisfacción duradera que los objetos, gastar en otras personas suele hacer sentir mejor que gastar en uno mismo, y usar el dinero para ganar tiempo libre también ayuda. No son reglas absolutas, pero van en contra de la idea de que más cosas es igual a más bienestar."]},"solucion":{}},{"slug":"consumo-5.s1.p9","orden":9,"grupo":"consumo-5.s1.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Según la investigación, ¿qué suele dar satisfacción más duradera y qué suele desvanecerse rápido?","grupos":[{"id":"g1","nombre":"Satisfacción más duradera"},{"id":"g2","nombre":"Se desvanece rápido"}],"items":[{"id":"i1","texto":"Compartir una experiencia con amigos"},{"id":"i2","texto":"Cambiar un celular que todavía funciona"},{"id":"i3","texto":"Hacer un regalo o ayudar a alguien"},{"id":"i4","texto":"Un objeto caro para mostrar"},{"id":"i5","texto":"Ganar tiempo libre para lo que te gusta"},{"id":"i6","texto":"Acumular ropa que casi no se usa"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"No se trata de no gastar, sino de gastar en lo que de verdad suma."}},{"slug":"consumo-5.s1.p10","orden":10,"grupo":"consumo-5.s1.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un producto cuesta 120.000 pesos. Si ganás 4.000 pesos por hora de trabajo, ¿cuántas horas de trabajo cuesta?","unidad":"horas","decimales":0,"contexto":"Precio de 120000 pesos; 4000 pesos por hora."},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"120.000 ÷ 4.000 = 30 horas. Pensar los precios en horas de vida ayuda a decidir si una compra vale la pena."}},{"slug":"consumo-5.s1.p10.v2","orden":10,"grupo":"consumo-5.s1.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un producto cuesta 300.000 pesos. Si ganás 5.000 pesos por hora de trabajo, ¿cuántas horas de trabajo cuesta?","unidad":"horas","decimales":0,"contexto":"Precio de 300000 pesos; 5000 pesos por hora."},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"300.000 ÷ 5.000 = 60 horas. Pensar los precios en horas de vida ayuda a decidir si una compra vale la pena."}},{"slug":"consumo-5.s1.p10.v3","orden":10,"grupo":"consumo-5.s1.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un producto cuesta 90.000 pesos. Si ganás 3.000 pesos por hora de trabajo, ¿cuántas horas de trabajo cuesta?","unidad":"horas","decimales":0,"contexto":"Precio de 90000 pesos; 3000 pesos por hora."},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"90.000 ÷ 3.000 = 30 horas. Pensar los precios en horas de vida ayuda a decidir si una compra vale la pena."}},{"slug":"consumo-5.s1.p11","orden":11,"grupo":"consumo-5.s1.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué señales muestran que una compra puede caer en la adaptación hedónica? Marcá todas.","opciones":[{"id":"o1","texto":"Ya tenés algo que cumple la misma función"},{"id":"o2","texto":"La querés sobre todo porque otros la tienen"},{"id":"o3","texto":"Tu entusiasmo con la compra anterior duró poco"},{"id":"o4","texto":"La publicidad te la mostró muchas veces esta semana"},{"id":"o5","texto":"Reemplaza algo roto que usás todos los días"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Reconocer estas señales permite frenar antes de una compra que no va a sumar."}},{"slug":"consumo-5.s1.p12","orden":12,"grupo":"consumo-5.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este posteo de un influencer y marcá lo que no se sostiene con la evidencia.","segmentos":[{"id":"s1","texto":"El dinero ayuda al bienestar, sobre todo cuando cubre lo básico."},{"id":"s2","texto":"Cada compra nueva te va a hacer más feliz para siempre."},{"id":"s3","texto":"Compartir experiencias suele dejar recuerdos más duraderos que los objetos."},{"id":"s4","texto":"Está probado que comprar cosas causa depresión."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Ni \"el dinero no importa\" ni \"comprar hace feliz\": la evidencia es más interesante.","por_opcion":{"s2":"Por la adaptación hedónica, la satisfacción suele volver a su nivel anterior.","s4":"La evidencia muestra una asociación con el materialismo, no una causa probada."}}},{"slug":"consumo-5.s1.p13","orden":13,"grupo":"consumo-5.s1.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Acostumbrarse rápido a lo nuevo es la adaptación {{0}}; el bienestar crece aproximadamente con cada {{1}} del ingreso; y los valores más materialistas se asocian con {{2}} bienestar.","banco":[{"id":"w1","texto":"hedónica"},{"id":"w2","texto":"duplicación"},{"id":"w3","texto":"menos"},{"id":"w4","texto":"estética"},{"id":"w5","texto":"moneda"},{"id":"w6","texto":"más"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para pensar la relación entre consumo y bienestar."}}]},{"slug":"consumo-5.s2","orden":2,"tipo":"leccion","titulo_es":"Necesidades y satisfactores","bajada_es":"El aporte latinoamericano de Max-Neef: pocas necesidades humanas, muchas formas de satisfacerlas.","minutos":10,"pasos":[{"slug":"consumo-5.s2.p1","orden":1,"grupo":"consumo-5.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Pocas necesidades","cuerpo":["En 1986, el economista chileno Manfred Max-Neef, junto con Antonio Elizalde y Martín Hopenhayn, propuso el enfoque del Desarrollo a Escala Humana. Su idea central: las necesidades humanas fundamentales son pocas, finitas y las mismas en todas las culturas y épocas. Lo que cambia es la forma de satisfacerlas, a la que llamaron satisfactores.","Propusieron nueve necesidades: subsistencia, protección, afecto, entendimiento, participación, ocio, creación, identidad y libertad."]},"solucion":{}},{"slug":"consumo-5.s2.p2","orden":2,"grupo":"consumo-5.s2.p2","tipo":"estimar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"¿Cuántas necesidades humanas fundamentales propone el enfoque de Max-Neef?","min":1,"max":30,"paso":1,"unidad":"necesidades","escala":"lineal"},"solucion":{"valor":9,"banda":"lineal","explicacion":"Nueve: subsistencia, protección, afecto, entendimiento, participación, ocio, creación, identidad y libertad."}},{"slug":"consumo-5.s2.p3","orden":3,"grupo":"consumo-5.s2.p3","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada necesidad con un satisfactor posible.","izquierda":[{"id":"a1","texto":"Subsistencia"},{"id":"a2","texto":"Entendimiento"},{"id":"a3","texto":"Participación"},{"id":"a4","texto":"Ocio"},{"id":"a5","texto":"Identidad"}],"derecha":[{"id":"b1","texto":"Alimentación y abrigo"},{"id":"b2","texto":"Una escuela o una biblioteca"},{"id":"b3","texto":"Una asamblea vecinal"},{"id":"b4","texto":"Tiempo libre y juegos"},{"id":"b5","texto":"Costumbres y memoria de la comunidad"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Cada necesidad puede satisfacerse de muchas maneras, con más o menos recursos."}},{"slug":"consumo-5.s2.p4","orden":4,"grupo":"consumo-5.s2.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Según Max-Neef, las necesidades humanas cambian con cada moda.","razones":[{"id":"r1","texto":"Porque lo que cambia son los satisfactores, no las necesidades"},{"id":"r2","texto":"Porque las necesidades las define la publicidad"},{"id":"r3","texto":"Porque cada persona tiene necesidades completamente distintas"}]},"solucion":{"valor":false,"explicacion":"Las necesidades son las mismas en todas las culturas y épocas; lo que cambia con las modas y las sociedades son los satisfactores, es decir, las formas de satisfacerlas.","clave":["r1"]}},{"slug":"consumo-5.s2.p5","orden":5,"grupo":"consumo-5.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Satisfactores que suman y que engañan","cuerpo":["Algunos satisfactores son sinérgicos: satisfacen varias necesidades a la vez. Una huerta comunitaria, por ejemplo, aporta alimento (subsistencia), encuentro (afecto), aprendizaje (entendimiento), decisiones compartidas (participación) y pertenencia (identidad). Otros son pseudosatisfactores: dan una sensación de satisfacer una necesidad sin hacerlo de verdad, como una marca que promete \"identidad\" o \"libertad\" a través de un producto."]},"solucion":{}},{"slug":"consumo-5.s2.p6","orden":6,"grupo":"consumo-5.s2.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué una huerta comunitaria es un satisfactor sinérgico?","opciones":[{"id":"o1","texto":"Porque satisface varias necesidades a la vez"},{"id":"o2","texto":"Porque produce más alimento que cualquier campo"},{"id":"o3","texto":"Porque reemplaza la necesidad de comer"},{"id":"o4","texto":"Porque es la forma más cara de conseguir verduras"}]},"solucion":{"clave":["o1"],"explicacion":"Los satisfactores sinérgicos son claves para vivir bien con pocos recursos.","por_opcion":{"o3":"No la reemplaza: la satisface junto con otras."}}},{"slug":"consumo-5.s2.p7","orden":7,"grupo":"consumo-5.s2.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un satisfactor sinérgico o un pseudosatisfactor?","grupos":[{"id":"g1","nombre":"Sinérgico"},{"id":"g2","nombre":"Pseudosatisfactor"}],"items":[{"id":"i1","texto":"Una huerta comunitaria"},{"id":"i2","texto":"Una marca que promete \"ser alguien\" con su producto"},{"id":"i3","texto":"Un club de barrio con deportes y talleres"},{"id":"i4","texto":"Seguidores comprados en una red social"},{"id":"i5","texto":"Una biblioteca popular"},{"id":"i6","texto":"Un auto caro para sentirse libre"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los pseudosatisfactores prometen mucho y dejan la necesidad sin cubrir."}},{"slug":"consumo-5.s2.p8","orden":8,"grupo":"consumo-5.s2.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un pseudosatisfactor alimenta el consumo.","items":[{"id":"i1","texto":"Una publicidad asocia un producto con la identidad"},{"id":"i2","texto":"Alguien lo compra para sentirse parte"},{"id":"i3","texto":"La necesidad de identidad no queda satisfecha"},{"id":"i4","texto":"Aparece otro producto que promete lo mismo"},{"id":"i5","texto":"Se compra más sin resolver la necesidad"},{"id":"i6","texto":"Un pseudosatisfactor cubre la necesidad para siempre"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cuando el satisfactor no es el adecuado, el consumo se vuelve un círculo."}},{"slug":"consumo-5.s2.p9","orden":9,"grupo":"consumo-5.s2.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué satisfactores pueden cubrir la necesidad de afecto con pocos recursos materiales? Marcá todos.","opciones":[{"id":"o1","texto":"Compartir una comida con amistades"},{"id":"o2","texto":"Participar en un grupo de interés común"},{"id":"o3","texto":"Cuidar a alguien de la familia"},{"id":"o4","texto":"Una tarde de mates en la plaza"},{"id":"o5","texto":"Comprar regalos cada vez más caros para demostrar cariño"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Muchas necesidades se satisfacen mejor con vínculos que con cosas."}},{"slug":"consumo-5.s2.p10","orden":10,"grupo":"consumo-5.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un club de barrio cobra 5.000 pesos por mes a cada una de sus 20 familias socias y ofrece deporte, talleres y encuentros. ¿Cuánto recauda por mes para sostener esas actividades?","unidad":"pesos","decimales":0,"contexto":"20 familias; cuota de 5000 pesos."},"solucion":{"valor":100000,"tolerancia":2000,"explicacion":"20 × 5.000 = 100.000 pesos por mes. Compartidos, los satisfactores sinérgicos suelen costar mucho menos por persona que resolver cada necesidad por separado."}},{"slug":"consumo-5.s2.p10.v2","orden":10,"grupo":"consumo-5.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un club de barrio cobra 4.000 pesos por mes a cada una de sus 30 familias socias y ofrece deporte, talleres y encuentros. ¿Cuánto recauda por mes para sostener esas actividades?","unidad":"pesos","decimales":0,"contexto":"30 familias; cuota de 4000 pesos."},"solucion":{"valor":120000,"tolerancia":2400,"explicacion":"30 × 4.000 = 120.000 pesos por mes. Compartidos, los satisfactores sinérgicos suelen costar mucho menos por persona que resolver cada necesidad por separado."}},{"slug":"consumo-5.s2.p10.v3","orden":10,"grupo":"consumo-5.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un club de barrio cobra 8.000 pesos por mes a cada una de sus 15 familias socias y ofrece deporte, talleres y encuentros. ¿Cuánto recauda por mes para sostener esas actividades?","unidad":"pesos","decimales":0,"contexto":"15 familias; cuota de 8000 pesos."},"solucion":{"valor":120000,"tolerancia":2400,"explicacion":"15 × 8.000 = 120.000 pesos por mes. Compartidos, los satisfactores sinérgicos suelen costar mucho menos por persona que resolver cada necesidad por separado."}},{"slug":"consumo-5.s2.p11","orden":11,"grupo":"consumo-5.s2.p11","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada necesidad con un pseudosatisfactor que promete cubrirla.","izquierda":[{"id":"a1","texto":"Protección"},{"id":"a2","texto":"Libertad"},{"id":"a3","texto":"Identidad"},{"id":"a4","texto":"Afecto"}],"derecha":[{"id":"b1","texto":"Comprar productos por miedo que genera la publicidad"},{"id":"b2","texto":"Un auto que \"te lleva a donde quieras\" en un embotellamiento"},{"id":"b3","texto":"La marca de moda que \"te define\""},{"id":"b4","texto":"Muchos \"me gusta\" en lugar de vínculos cercanos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Detectar la necesidad detrás del deseo ayuda a buscar un satisfactor mejor."}},{"slug":"consumo-5.s2.p12","orden":12,"grupo":"consumo-5.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este texto escolar y marcá lo que no coincide con el enfoque de Max-Neef.","segmentos":[{"id":"s1","texto":"Las necesidades fundamentales son las mismas en todas las culturas."},{"id":"s2","texto":"Cada generación inventa necesidades nuevas, como tener el último celular."},{"id":"s3","texto":"Una huerta comunitaria puede satisfacer varias necesidades a la vez."},{"id":"s4","texto":"Las necesidades solo se satisfacen comprando productos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El enfoque de Max-Neef separa lo que necesitamos de las formas de conseguirlo.","por_opcion":{"s2":"El celular es un satisfactor posible; las necesidades no cambian.","s4":"Hay satisfactores sociales, culturales y comunitarios que no pasan por comprar."}}},{"slug":"consumo-5.s2.p13","orden":13,"grupo":"consumo-5.s2.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Según Max-Neef, las necesidades son pocas y {{0}}; las formas de satisfacerlas se llaman {{1}}; y los que cubren varias necesidades a la vez son {{2}}.","banco":[{"id":"w1","texto":"finitas"},{"id":"w2","texto":"satisfactores"},{"id":"w3","texto":"sinérgicos"},{"id":"w4","texto":"infinitas"},{"id":"w5","texto":"consumidores"},{"id":"w6","texto":"aislados"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos del Desarrollo a Escala Humana."}}]},{"slug":"consumo-5.s3","orden":3,"tipo":"leccion","titulo_es":"Suficiencia","bajada_es":"Vivir bien dentro de los límites del planeta: qué es la suficiencia y en qué se diferencia de la eficiencia.","minutos":10,"pasos":[{"slug":"consumo-5.s3.p1","orden":1,"grupo":"consumo-5.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una buena vida para todos","cuerpo":["Un estudio de 2018 comparó, en más de 150 países, cuánto cubren las necesidades básicas de su población y cuántos recursos usan. Encontró que ningún país lograba cubrir las necesidades básicas de su gente con un uso de recursos sostenible a escala global. Y que, con las relaciones actuales, lograr metas como una alta satisfacción con la vida para todo el mundo requeriría entre 2 y 6 veces el uso de recursos sostenible.","La economista Kate Raworth lo resume con la imagen de una dona: un piso social, por debajo del cual nadie debería quedar, y un techo ecológico, por encima del cual se dañan los sistemas que sostienen la vida. El espacio seguro y justo está entre los dos."]},"solucion":{}},{"slug":"consumo-5.s3.p2","orden":2,"grupo":"consumo-5.s3.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué representa el espacio entre el borde interno y el externo de la \"dona\"?","opciones":[{"id":"o1","texto":"Donde todos cubren sus necesidades sin exceder el planeta"},{"id":"o2","texto":"El nivel de consumo de los países más ricos del mundo"},{"id":"o3","texto":"La zona donde el consumo no tiene ningún límite"},{"id":"o4","texto":"La cantidad de recursos que sobran para exportar"}]},"solucion":{"clave":["o1"],"explicacion":"El desafío no es solo reducir: es subir a quienes están por debajo del piso sin atravesar el techo.","por_opcion":{"o3":"Tiene dos límites: el piso social y el techo ecológico."}}},{"slug":"consumo-5.s3.p3","orden":3,"grupo":"consumo-5.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es la suficiencia","cuerpo":["El IPCC define las políticas de suficiencia como un conjunto de medidas y prácticas cotidianas que evitan demanda de energía, materiales, tierra y agua, mientras dan bienestar a todas las personas dentro de los límites del planeta. La eficiencia hace lo mismo con menos energía, como una heladera que consume menos; la suficiencia ajusta el servicio a lo que se necesita, como una heladera del tamaño justo, o compartir un freezer.","Según el IPCC, las medidas del lado de la demanda, que incluyen suficiencia, eficiencia e infraestructura, podrían reducir entre un 40 y un 70 % las emisiones de los edificios, el transporte terrestre y la alimentación hacia 2050, respecto de las tendencias."],"destacado":{"valor":"40 a 70 %","texto":"podrían bajar hacia 2050 las emisiones de edificios, transporte y alimentación con medidas del lado de la demanda, según el IPCC."}},"solucion":{}},{"slug":"consumo-5.s3.p4","orden":4,"grupo":"consumo-5.s3.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una medida de eficiencia o de suficiencia?","grupos":[{"id":"g1","nombre":"Eficiencia"},{"id":"g2","nombre":"Suficiencia"}],"items":[{"id":"i1","texto":"Cambiar a lámparas LED"},{"id":"i2","texto":"Una vivienda del tamaño que se necesita"},{"id":"i3","texto":"Un auto que consume menos por km"},{"id":"i4","texto":"Compartir herramientas entre vecinos"},{"id":"i5","texto":"Aislar las paredes de la casa"},{"id":"i6","texto":"Vivir cerca del trabajo para no depender del auto"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las dos se complementan: la eficiencia sin suficiencia puede terminar en rebote."}},{"slug":"consumo-5.s3.p5","orden":5,"grupo":"consumo-5.s3.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la eficiencia sola puede no alcanzar.","items":[{"id":"i1","texto":"Las heladeras nuevas consumen menos por litro"},{"id":"i2","texto":"Las heladeras se hacen cada vez más grandes"},{"id":"i3","texto":"Muchos hogares suman un segundo freezer"},{"id":"i4","texto":"El consumo total de energía casi no baja"},{"id":"i5","texto":"Hace falta también ajustar el tamaño a lo necesario"},{"id":"i6","texto":"Las heladeras eficientes siempre bajan el consumo total"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Eficiencia y suficiencia juntas logran lo que ninguna logra sola."}},{"slug":"consumo-5.s3.p6","orden":6,"grupo":"consumo-5.s3.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una tarifa de luz cobra los primeros 150 kWh del mes a 100 pesos y cada kWh extra a 300 pesos. ¿Cuánto paga un hogar que consume 250 kWh?","unidad":"pesos","decimales":0,"contexto":"250 kWh; 150 kWh a 100 y el resto a 300."},"solucion":{"valor":45000,"tolerancia":900,"explicacion":"150 × 100 = 15.000; 100 × 300 = 30.000; total 45.000 pesos. Una tarifa escalonada abarata lo básico y encarece el exceso: una herramienta de suficiencia."}},{"slug":"consumo-5.s3.p6.v2","orden":6,"grupo":"consumo-5.s3.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una tarifa de luz cobra los primeros 150 kWh del mes a 100 pesos y cada kWh extra a 300 pesos. ¿Cuánto paga un hogar que consume 400 kWh?","unidad":"pesos","decimales":0,"contexto":"400 kWh; 150 kWh a 100 y el resto a 300."},"solucion":{"valor":90000,"tolerancia":1800,"explicacion":"150 × 100 = 15.000; 250 × 300 = 75.000; total 90.000 pesos. Una tarifa escalonada abarata lo básico y encarece el exceso: una herramienta de suficiencia."}},{"slug":"consumo-5.s3.p6.v3","orden":6,"grupo":"consumo-5.s3.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una tarifa de luz cobra los primeros 150 kWh del mes a 120 pesos y cada kWh extra a 360 pesos. ¿Cuánto paga un hogar que consume 200 kWh?","unidad":"pesos","decimales":0,"contexto":"200 kWh; 150 kWh a 120 y el resto a 360."},"solucion":{"valor":36000,"tolerancia":720,"explicacion":"150 × 120 = 18.000; 50 × 360 = 18.000; total 36.000 pesos. Una tarifa escalonada abarata lo básico y encarece el exceso: una herramienta de suficiencia."}},{"slug":"consumo-5.s3.p7","orden":7,"grupo":"consumo-5.s3.p7","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá el porcentaje máximo en que podrían bajar hacia 2050 las emisiones de edificios, transporte y alimentación con medidas del lado de la demanda, según el IPCC.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":70,"banda":"lineal","explicacion":"Entre un 40 y un 70 %, según el IPCC: un potencial enorme que no depende solo de nuevas tecnologías."}},{"slug":"consumo-5.s3.p8","orden":8,"grupo":"consumo-5.s3.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La suficiencia significa que todas las personas tienen que consumir menos.","razones":[{"id":"r1","texto":"Porque quienes están por debajo del piso social necesitan más"},{"id":"r2","texto":"Porque la suficiencia prohíbe todo consumo"},{"id":"r3","texto":"Porque solo aplica a los países pobres"}]},"solucion":{"valor":false,"explicacion":"Significa ajustar el consumo al bienestar. Quienes consumen muy por encima de sus necesidades pueden reducir; quienes están por debajo del piso social necesitan más acceso a energía, vivienda y alimentos.","clave":["r1"]}},{"slug":"consumo-5.s3.p9","orden":9,"grupo":"consumo-5.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una vivienda de 120 m² tiene 2 habitantes. ¿Cuántos m² hay por persona?","unidad":"m² por persona","decimales":0,"contexto":"120 m²; 2 habitantes."},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"120 ÷ 2 = 60 m² por persona. Más metros por persona suelen significar más materiales para construir y más energía para calefaccionar y enfriar."}},{"slug":"consumo-5.s3.p9.v2","orden":9,"grupo":"consumo-5.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una vivienda de 60 m² tiene 3 habitantes. ¿Cuántos m² hay por persona?","unidad":"m² por persona","decimales":0,"contexto":"60 m²; 3 habitantes."},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"60 ÷ 3 = 20 m² por persona. Más metros por persona suelen significar más materiales para construir y más energía para calefaccionar y enfriar."}},{"slug":"consumo-5.s3.p9.v3","orden":9,"grupo":"consumo-5.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una vivienda de 200 m² tiene 4 habitantes. ¿Cuántos m² hay por persona?","unidad":"m² por persona","decimales":0,"contexto":"200 m²; 4 habitantes."},"solucion":{"valor":50,"tolerancia":1,"explicacion":"200 ÷ 4 = 50 m² por persona. Más metros por persona suelen significar más materiales para construir y más energía para calefaccionar y enfriar."}},{"slug":"consumo-5.s3.p10","orden":10,"grupo":"consumo-5.s3.p10","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ámbito con una práctica de suficiencia.","izquierda":[{"id":"a1","texto":"Vivienda"},{"id":"a2","texto":"Transporte"},{"id":"a3","texto":"Alimentación"},{"id":"a4","texto":"Objetos"}],"derecha":[{"id":"b1","texto":"Espacios compartidos, como lavaderos o terrazas comunes"},{"id":"b2","texto":"Barrios con servicios a distancia caminable"},{"id":"b3","texto":"Comprar lo que se va a comer y aprovechar sobras"},{"id":"b4","texto":"Reparar y usar las cosas durante más tiempo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"La suficiencia aparece en todos los ámbitos de la vida cotidiana."}},{"slug":"consumo-5.s3.p11","orden":11,"grupo":"consumo-5.s3.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué políticas públicas facilitan la suficiencia? Marcá todas.","opciones":[{"id":"o1","texto":"Tarifas que abaratan lo básico y encarecen el exceso"},{"id":"o2","texto":"Normas de diseño para productos más durables"},{"id":"o3","texto":"Espacios y equipamientos compartidos en los barrios"},{"id":"o4","texto":"Planificación urbana con servicios cercanos"},{"id":"o5","texto":"Subsidiar que cada hogar tenga más de un auto"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La suficiencia es más fácil cuando las reglas y la infraestructura la hacen natural."}},{"slug":"consumo-5.s3.p12","orden":12,"grupo":"consumo-5.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta columna de opinión y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"La eficiencia es necesaria pero no alcanza sola."},{"id":"s2","texto":"Suficiencia es obligar a todos a vivir con lo mínimo."},{"id":"s3","texto":"El IPCC reconoce el potencial de las medidas del lado de la demanda."},{"id":"s4","texto":"Algún país ya cubre las necesidades de todos con recursos sostenibles."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La suficiencia no es austeridad forzada: es bienestar con menos recursos.","por_opcion":{"s2":"Busca bienestar para todos: algunos reducen y otros acceden a más.","s4":"El estudio de 2018 no encontró ningún país que lo lograra."}}},{"slug":"consumo-5.s3.p13","orden":13,"grupo":"consumo-5.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Hacer lo mismo con menos energía es {{0}}; ajustar el servicio a lo que de verdad se necesita es {{1}}; y el modelo de la dona combina un piso social con un techo {{2}}.","banco":[{"id":"w1","texto":"eficiencia"},{"id":"w2","texto":"suficiencia"},{"id":"w3","texto":"ecológico"},{"id":"w4","texto":"abundancia"},{"id":"w5","texto":"austeridad"},{"id":"w6","texto":"económico"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para pensar un consumo que alcance para todos."}}]},{"slug":"consumo-5.s4","orden":4,"tipo":"leccion","titulo_es":"Publicidad y normas sociales","bajada_es":"Cómo nos empujan a consumir los anuncios y lo que hacen los demás, y qué límites se están poniendo.","minutos":11,"pasos":[{"slug":"consumo-5.s4.p1","orden":1,"grupo":"consumo-5.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El mensaje que se repite","cuerpo":["La publicidad no solo informa: busca crear deseos, asociar productos con emociones, estatus o identidad, y repetirse hasta volverse familiar. Las niñas y los niños son especialmente vulnerables, porque todavía no distinguen bien un anuncio de un contenido. En redes sociales, los anuncios se mezclan con publicaciones de personas y se ajustan a cada usuario."]},"solucion":{}},{"slug":"consumo-5.s4.p2","orden":2,"grupo":"consumo-5.s4.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una persona ve unos 50 anuncios por día entre redes, calle y pantallas, ¿cuántos ve en 30 días?","unidad":"anuncios","decimales":0,"contexto":"50 anuncios por día; 30 días."},"solucion":{"valor":1500,"tolerancia":30,"explicacion":"50 × 30 = 1.500 anuncios. Valores de ejemplo: la repetición es parte central de cómo funciona la publicidad."}},{"slug":"consumo-5.s4.p2.v2","orden":2,"grupo":"consumo-5.s4.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una persona ve unos 120 anuncios por día entre redes, calle y pantallas, ¿cuántos ve en 30 días?","unidad":"anuncios","decimales":0,"contexto":"120 anuncios por día; 30 días."},"solucion":{"valor":3600,"tolerancia":72,"explicacion":"120 × 30 = 3.600 anuncios. Valores de ejemplo: la repetición es parte central de cómo funciona la publicidad."}},{"slug":"consumo-5.s4.p2.v3","orden":2,"grupo":"consumo-5.s4.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una persona ve unos 80 anuncios por día entre redes, calle y pantallas, ¿cuántos ve en 365 días?","unidad":"anuncios","decimales":0,"contexto":"80 anuncios por día; 365 días."},"solucion":{"valor":29200,"tolerancia":584,"explicacion":"80 × 365 = 29.200 anuncios. Valores de ejemplo: la repetición es parte central de cómo funciona la publicidad."}},{"slug":"consumo-5.s4.p3","orden":3,"grupo":"consumo-5.s4.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué técnica publicitaria usa cada anuncio?","grupos":[{"id":"g1","nombre":"Estatus"},{"id":"g2","nombre":"Urgencia"},{"id":"g3","nombre":"Pertenencia"}],"items":[{"id":"i1","texto":"\"El auto de quienes llegaron lejos\""},{"id":"i2","texto":"\"Solo por hoy: 50 % de descuento\""},{"id":"i3","texto":"\"Todos tus amigos ya lo usan\""},{"id":"i4","texto":"\"La edición exclusiva que pocos tienen\""},{"id":"i5","texto":"\"Quedan 3 unidades\""},{"id":"i6","texto":"\"Sumate a la comunidad de la marca\""}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Reconocer la técnica ayuda a separar el deseo creado de la necesidad real."}},{"slug":"consumo-5.s4.p4","orden":4,"grupo":"consumo-5.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que hacen los demás","cuerpo":["Además de los anuncios, nos influye lo que vemos hacer a otras personas: las normas sociales. Pueden empujar a consumir más, cuando lo \"normal\" es cambiar de celular cada año, o ayudar a consumir menos, como en el experimento de las cartas que comparaban el consumo eléctrico con el de los vecinos, que viste en ciencia. El consumo para mostrar estatus, que el economista Thorstein Veblen llamó \"consumo conspicuo\" a fines del siglo XIX, sigue muy presente."]},"solucion":{}},{"slug":"consumo-5.s4.p5","orden":5,"grupo":"consumo-5.s4.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una norma social puede aumentar el consumo.","items":[{"id":"i1","texto":"En un grupo, cambiar de celular cada año se vuelve lo normal"},{"id":"i2","texto":"Quien tiene uno viejo se siente fuera de lugar"},{"id":"i3","texto":"Lo cambia aunque todavía funcione"},{"id":"i4","texto":"Se refuerza la idea de que \"todos\" lo cambian"},{"id":"i5","texto":"Crecen el consumo y los residuos electrónicos"},{"id":"i6","texto":"Las normas sociales solo influyen en quienes ven publicidad"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Las normas se contagian, y por eso también se pueden cambiar."}},{"slug":"consumo-5.s4.p6","orden":6,"grupo":"consumo-5.s4.p6","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué es el \"consumo conspicuo\"?","opciones":[{"id":"o1","texto":"Comprar para mostrar estatus ante los demás"},{"id":"o2","texto":"Comprar solo lo que se necesita para vivir"},{"id":"o3","texto":"Comprar productos de segunda mano"},{"id":"o4","texto":"Comprar productos que no tienen marca"}]},"solucion":{"clave":["o1"],"explicacion":"Cuando el objetivo es mostrar, ninguna compra alcanza: siempre hay algo más visible.","por_opcion":{"o3":"Es casi lo contrario: el objetivo es exhibir."}}},{"slug":"consumo-5.s4.p7","orden":7,"grupo":"consumo-5.s4.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las normas sociales solo pueden empujar a consumir más.","razones":[{"id":"r1","texto":"Porque también pueden hacer normal ahorrar, reparar o compartir"},{"id":"r2","texto":"Porque las personas nunca copian a otras"},{"id":"r3","texto":"Porque las normas sociales no existen"}]},"solucion":{"valor":false,"explicacion":"También pueden empujar a consumir menos o mejor: ver que los vecinos ahorran energía, reparan o comparten cambia lo que parece normal.","clave":["r1"]}},{"slug":"consumo-5.s4.p8","orden":8,"grupo":"consumo-5.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Poner límites","cuerpo":["Algunos países y ciudades empezaron a limitar la publicidad de lo que más contamina. En Francia, desde agosto de 2022 está prohibida la publicidad de combustibles fósiles, por la ley de Clima y Resiliencia. La Haya, en los Países Bajos, fue la primera ciudad en prohibir por ley, desde enero de 2025, los anuncios de combustibles fósiles, autos a nafta y diésel, vuelos y cruceros en el espacio público; en 2025 un tribunal confirmó la medida."]},"solucion":{}},{"slug":"consumo-5.s4.p9","orden":9,"grupo":"consumo-5.s4.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué hizo La Haya desde enero de 2025?","opciones":[{"id":"o1","texto":"Prohibir en la vía pública anuncios fósiles, de vuelos y cruceros"},{"id":"o2","texto":"Prohibir toda la publicidad de cualquier producto en la ciudad"},{"id":"o3","texto":"Obligar a anunciar solo autos a combustión"},{"id":"o4","texto":"Cobrar un impuesto a quienes miran publicidad en la calle"}]},"solucion":{"clave":["o1"],"explicacion":"Es de las primeras normas que tratan la publicidad como parte de la política climática, y un tribunal la confirmó.","por_opcion":{"o3":"Es al revés: los autos a nafta y diésel quedaron entre los anuncios prohibidos."}}},{"slug":"consumo-5.s4.p10","orden":10,"grupo":"consumo-5.s4.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a consumir con más autonomía frente a la publicidad? Marcá todo.","opciones":[{"id":"o1","texto":"Esperar unos días antes de una compra no planificada"},{"id":"o2","texto":"Desactivar notificaciones de ofertas"},{"id":"o3","texto":"Preguntarse qué necesidad hay detrás del deseo"},{"id":"o4","texto":"Reconocer las técnicas de urgencia y estatus"},{"id":"o5","texto":"Comprar siempre en el momento de la oferta para no perderla"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Ganar tiempo entre el deseo y la compra es de las herramientas más efectivas."}},{"slug":"consumo-5.s4.p11","orden":11,"grupo":"consumo-5.s4.p11","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená una forma de decidir una compra no planificada.","items":[{"id":"i1","texto":"Notar el deseo y qué lo disparó"},{"id":"i2","texto":"Preguntarse qué necesidad hay detrás"},{"id":"i3","texto":"Esperar unos días"},{"id":"i4","texto":"Revisar si hay otra forma de cubrirla: pedir, reparar, compartir"},{"id":"i5","texto":"Si todavía hace falta, comprar con criterio"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"No se trata de no comprar nunca, sino de que la decisión sea propia."}},{"slug":"consumo-5.s4.p12","orden":12,"grupo":"consumo-5.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este anuncio y marcá las frases que usan técnicas de presión.","segmentos":[{"id":"s1","texto":"Zapatillas de running con suela reparable."},{"id":"s2","texto":"Solo quedan 2 pares: comprá ya antes de que se agoten."},{"id":"s3","texto":"Talles del 35 al 45."},{"id":"s4","texto":"Las que usan los que marcan la diferencia."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Separar información de presión cambia cómo se lee cualquier anuncio.","por_opcion":{"s2":"Urgencia: presiona para decidir sin pensar.","s4":"Estatus: asocia el producto con ser superior a otros."}}},{"slug":"consumo-5.s4.p13","orden":13,"grupo":"consumo-5.s4.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Comprar para mostrar estatus es el consumo {{0}}; lo que vemos hacer a los demás funciona como una norma {{1}}; y Francia prohibió en 2022 la publicidad de combustibles {{2}}.","banco":[{"id":"w1","texto":"conspicuo"},{"id":"w2","texto":"social"},{"id":"w3","texto":"fósiles"},{"id":"w4","texto":"invisible"},{"id":"w5","texto":"legal"},{"id":"w6","texto":"renovables"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para entender qué nos empuja a consumir."}}]},{"slug":"consumo-5.s5","orden":5,"tipo":"leccion","titulo_es":"Lo colectivo","bajada_es":"Bibliotecas de objetos, espacios compartidos, tiempo y justicia: bienestar con menos recursos no es solo una decisión individual.","minutos":9,"pasos":[{"slug":"consumo-5.s5.p1","orden":1,"grupo":"consumo-5.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que se comparte","cuerpo":["Muchos consumos privados se pueden reemplazar por bienes compartidos que dan el mismo servicio con muchos menos recursos: una plaza en vez de muchos patios, una biblioteca en vez de muchos libros sin leer, un transporte público en vez de muchos autos, una biblioteca de herramientas en vez de un taladro en cada casa. Cuando lo común es bueno, lo privado puede ser más chico sin perder bienestar."]},"solucion":{}},{"slug":"consumo-5.s5.p2","orden":2,"grupo":"consumo-5.s5.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio, 30 hogares necesitan un taladro de vez en cuando. Cada uno cuesta 60.000 pesos. Si una biblioteca de herramientas compra 3 para prestar, ¿cuánto se ahorra el barrio en total?","unidad":"pesos","decimales":0,"contexto":"30 hogares; taladro de 60000 pesos; 3 compartidos."},"solucion":{"valor":1620000,"tolerancia":32400,"explicacion":"(30 − 3) × 60.000 = 1.620.000 pesos, y 27 taladros menos que fabricar. Compartir lo que se usa poco es de lo más eficiente que hay."}},{"slug":"consumo-5.s5.p2.v2","orden":2,"grupo":"consumo-5.s5.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio, 50 hogares necesitan un taladro de vez en cuando. Cada uno cuesta 80.000 pesos. Si una biblioteca de herramientas compra 4 para prestar, ¿cuánto se ahorra el barrio en total?","unidad":"pesos","decimales":0,"contexto":"50 hogares; taladro de 80000 pesos; 4 compartidos."},"solucion":{"valor":3680000,"tolerancia":73600,"explicacion":"(50 − 4) × 80.000 = 3.680.000 pesos, y 46 taladros menos que fabricar. Compartir lo que se usa poco es de lo más eficiente que hay."}},{"slug":"consumo-5.s5.p2.v3","orden":2,"grupo":"consumo-5.s5.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio, 20 hogares necesitan un taladro de vez en cuando. Cada uno cuesta 45.000 pesos. Si una biblioteca de herramientas compra 2 para prestar, ¿cuánto se ahorra el barrio en total?","unidad":"pesos","decimales":0,"contexto":"20 hogares; taladro de 45000 pesos; 2 compartidos."},"solucion":{"valor":810000,"tolerancia":16200,"explicacion":"(20 − 2) × 45.000 = 810.000 pesos, y 18 taladros menos que fabricar. Compartir lo que se usa poco es de lo más eficiente que hay."}},{"slug":"consumo-5.s5.p3","orden":3,"grupo":"consumo-5.s5.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué bien compartido puede reemplazar cada consumo privado?","grupos":[{"id":"g1","nombre":"Biblioteca de objetos"},{"id":"g2","nombre":"Espacio público"},{"id":"g3","nombre":"Transporte compartido"}],"items":[{"id":"i1","texto":"Una escalera que se usa dos veces por año"},{"id":"i2","texto":"Un patio grande que casi no se usa"},{"id":"i3","texto":"Un segundo auto familiar"},{"id":"i4","texto":"Una carpa para una sola salida"},{"id":"i5","texto":"Una pileta en cada casa"},{"id":"i6","texto":"Un auto para ir solo al centro"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Cada bien compartido resuelve muchas necesidades individuales a la vez."}},{"slug":"consumo-5.s5.p4","orden":4,"grupo":"consumo-5.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tiempo y justicia","cuerpo":["Consumir menos también puede significar necesitar menos ingresos, y por lo tanto, en algunos casos, trabajar menos horas y ganar tiempo. Pero no hay que romantizarlo: para muchos hogares el problema no es el exceso, sino no llegar a lo básico. La suficiencia es una cuestión de justicia: como viste con la justicia climática, el 10 % más rico del mundo genera cerca de la mitad de las emisiones del consumo, y ahí está el mayor margen para reducir."]},"solucion":{}},{"slug":"consumo-5.s5.p5","orden":5,"grupo":"consumo-5.s5.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La suficiencia exige lo mismo a un hogar que no llega a fin de mes que a uno que consume en exceso.","razones":[{"id":"r1","texto":"Porque el margen para reducir está en quienes consumen en exceso"},{"id":"r2","texto":"Porque los hogares pobres emiten más que los ricos"},{"id":"r3","texto":"Porque la suficiencia no tiene nada que ver con la justicia"}]},"solucion":{"valor":false,"explicacion":"La suficiencia es una cuestión de justicia: el mayor margen para reducir está en quienes consumen muy por encima de sus necesidades, mientras otros necesitan acceder a más.","clave":["r1"]}},{"slug":"consumo-5.s5.p6","orden":6,"grupo":"consumo-5.s5.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una persona reduce su jornada 4 horas por semana, ¿cuántas horas libres gana en 4 semanas?","unidad":"horas","decimales":0,"contexto":"4 horas menos por semana; 4 semanas."},"solucion":{"valor":16,"tolerancia":0.5,"explicacion":"4 × 4 = 16 horas por mes para descansar, cuidar, estudiar o participar: satisfactores de varias necesidades a la vez."}},{"slug":"consumo-5.s5.p6.v2","orden":6,"grupo":"consumo-5.s5.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una persona reduce su jornada 2 horas por semana, ¿cuántas horas libres gana en 4 semanas?","unidad":"horas","decimales":0,"contexto":"2 horas menos por semana; 4 semanas."},"solucion":{"valor":8,"tolerancia":0.5,"explicacion":"2 × 4 = 8 horas por mes para descansar, cuidar, estudiar o participar: satisfactores de varias necesidades a la vez."}},{"slug":"consumo-5.s5.p6.v3","orden":6,"grupo":"consumo-5.s5.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una persona reduce su jornada 8 horas por semana, ¿cuántas horas libres gana en 4 semanas?","unidad":"horas","decimales":0,"contexto":"8 horas menos por semana; 4 semanas."},"solucion":{"valor":32,"tolerancia":0.64,"explicacion":"8 × 4 = 32 horas por mes para descansar, cuidar, estudiar o participar: satisfactores de varias necesidades a la vez."}},{"slug":"consumo-5.s5.p7","orden":7,"grupo":"consumo-5.s5.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un bien público puede reducir el consumo privado.","items":[{"id":"i1","texto":"El barrio tiene una plaza con sombra y juegos"},{"id":"i2","texto":"Las familias la usan todos los días"},{"id":"i3","texto":"Necesitan menos espacio propio para el ocio"},{"id":"i4","texto":"Construyen y equipan menos por su cuenta"},{"id":"i5","texto":"Se usan menos recursos con el mismo bienestar"},{"id":"i6","texto":"Los bienes públicos aumentan siempre el consumo privado"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Los bienes comunes son una de las herramientas más potentes de la suficiencia."}},{"slug":"consumo-5.s5.p8","orden":8,"grupo":"consumo-5.s5.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la suficiencia no es solo una decisión individual?","opciones":[{"id":"o1","texto":"Porque depende de la infraestructura, las reglas y lo común"},{"id":"o2","texto":"Porque las personas no pueden decidir nada sobre su consumo"},{"id":"o3","texto":"Porque solo los gobiernos consumen recursos"},{"id":"o4","texto":"Porque la suficiencia la deciden las empresas en secreto"}]},"solucion":{"clave":["o1"],"explicacion":"Sin transporte público, espacios comunes y reglas adecuadas, elegir menos es mucho más difícil.","por_opcion":{"o3":"Los hogares también; pero sus opciones dependen del entorno."}}},{"slug":"consumo-5.s5.p9","orden":9,"grupo":"consumo-5.s5.p9","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada iniciativa con lo que aporta.","izquierda":[{"id":"a1","texto":"Biblioteca de herramientas"},{"id":"a2","texto":"Taller comunitario de reparación"},{"id":"a3","texto":"Huerta del barrio"},{"id":"a4","texto":"Club o centro cultural"}],"derecha":[{"id":"b1","texto":"Menos objetos comprados y guardados"},{"id":"b2","texto":"Cosas que duran más"},{"id":"b3","texto":"Alimento, encuentro y aprendizaje"},{"id":"b4","texto":"Ocio y pertenencia sin gastar tanto"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Lo colectivo multiplica los satisfactores sinérgicos."}},{"slug":"consumo-5.s5.p10","orden":10,"grupo":"consumo-5.s5.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace falta para que una biblioteca de objetos funcione? Marcá todo.","opciones":[{"id":"o1","texto":"Un lugar accesible y horarios claros"},{"id":"o2","texto":"Un registro de préstamos y devoluciones"},{"id":"o3","texto":"Mantenimiento de los objetos"},{"id":"o4","texto":"Personas que la organicen y la difundan"},{"id":"o5","texto":"Que cada objeto se preste una sola vez"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Lo común necesita organización: por eso las comunidades son tan importantes."}},{"slug":"consumo-5.s5.p11","orden":11,"grupo":"consumo-5.s5.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este proyecto vecinal y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"Armaremos una biblioteca de herramientas en el club."},{"id":"s2","texto":"Todos los vecinos deberán reducir su consumo a la mitad, sin excepción."},{"id":"s3","texto":"Llevaremos un registro de préstamos."},{"id":"s4","texto":"No hace falta que nadie se ocupe del mantenimiento."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen proyecto colectivo es justo, organizado y sostenible en el tiempo.","por_opcion":{"s2":"Hay hogares que no cubren lo básico: la suficiencia no exige lo mismo a todos.","s4":"Sin mantenimiento, los objetos compartidos se rompen y el sistema falla."}}},{"slug":"consumo-5.s5.p12","orden":12,"grupo":"consumo-5.s5.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Prestar herramientas entre vecinos es una biblioteca de {{0}}; una plaza puede reemplazar muchos patios porque es un bien {{1}}; y el mayor margen para reducir emisiones está en quienes más {{2}}.","banco":[{"id":"w1","texto":"objetos"},{"id":"w2","texto":"público"},{"id":"w3","texto":"consumen"},{"id":"w4","texto":"monedas"},{"id":"w5","texto":"privado"},{"id":"w6","texto":"ahorran"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para pasar de lo individual a lo colectivo."}}]},{"slug":"consumo-5.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: consumo y bienestar","bajada_es":"Dinero y bienestar, necesidades y satisfactores, suficiencia, publicidad y lo colectivo, mezclados.","minutos":8,"pasos":[{"slug":"consumo-5.s6.p1","orden":1,"grupo":"consumo-5.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Consumo, bienestar y suficiencia». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"consumo-5.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el aumento de Julián","bajada_es":"Julián consiguió un aumento de sueldo y no sabe qué hacer con él. Ayudalo a decidir con lo que aprendiste.","minutos":10,"pasos":[{"slug":"consumo-5.s7.p1","orden":1,"grupo":"consumo-5.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["Julián gana 5.000 pesos por hora y trabaja 40 horas por semana. Le ofrecen un aumento del 20 %. Tiene tres ideas: A, sacar un auto nuevo en cuotas de 400.000 pesos por mes, aunque el suyo funciona; B, mantener el ingreso actual y trabajar menos horas; C, usar parte del aumento para un viaje con amistades y ahorrar el resto. Vive cerca de una línea de colectivo y su club de barrio tiene talleres que siempre quiso hacer."]},"solucion":{}},{"slug":"consumo-5.s7.p2","orden":2,"grupo":"consumo-5.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con el aumento del 20 %, ¿cuánto gana Julián por hora?","unidad":"pesos por hora","decimales":0,"contexto":"5.000 pesos por hora; aumento del 20 %."},"solucion":{"valor":6000,"tolerancia":120,"explicacion":"5.000 × 1,2 = 6.000 pesos por hora: un 20 % más por cada hora trabajada."}},{"slug":"consumo-5.s7.p3","orden":3,"grupo":"consumo-5.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas horas de trabajo por mes cuesta la cuota del auto con el nuevo sueldo? Redondeá al entero.","unidad":"horas","decimales":0,"contexto":"Cuota de 400.000 pesos; 6.000 pesos por hora."},"solucion":{"valor":67,"tolerancia":1,"explicacion":"400.000 ÷ 6.000 ≈ 67 horas por mes: más de una semana y media de trabajo cada mes para cambiar un auto que funciona."}},{"slug":"consumo-5.s7.p4","orden":4,"grupo":"consumo-5.s7.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si elige la opción B y quiere ganar lo mismo que antes (200.000 pesos por semana), ¿cuántas horas por semana tendría que trabajar? Redondeá a un decimal.","unidad":"horas","decimales":1,"contexto":"200.000 pesos por semana; 6.000 pesos por hora."},"solucion":{"valor":33.3,"tolerancia":0.1,"explicacion":"200.000 ÷ 6.000 ≈ 33,3 horas: casi 7 horas libres más por semana con el mismo ingreso."}},{"slug":"consumo-5.s7.p5","orden":5,"grupo":"consumo-5.s7.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Según lo que viste sobre adaptación hedónica, ¿qué riesgo tiene la opción A?","opciones":[{"id":"o1","texto":"Que el entusiasmo dure poco y la cuota siga"},{"id":"o2","texto":"Que el auto nuevo no se pueda manejar"},{"id":"o3","texto":"Que los autos nuevos no tengan garantía"},{"id":"o4","texto":"Que la cuota baje con el tiempo"}]},"solucion":{"clave":["o1"],"explicacion":"La satisfacción se adapta rápido; la cuota, no.","por_opcion":{"o3":"El riesgo está en la satisfacción que se desvanece, no en la garantía."}}},{"slug":"consumo-5.s7.p6","orden":6,"grupo":"consumo-5.s7.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué necesidades satisface cada opción de Julián?","grupos":[{"id":"g1","nombre":"Ocio y afecto"},{"id":"g2","nombre":"Entendimiento y creación"}],"items":[{"id":"i1","texto":"El viaje con amistades"},{"id":"i2","texto":"Los talleres del club"},{"id":"i3","texto":"Tiempo libre para ver a su familia"},{"id":"i4","texto":"Aprender algo nuevo con horas liberadas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Las opciones B y C tienen satisfactores sinérgicos; la A apunta sobre todo al estatus."}},{"slug":"consumo-5.s7.p7","orden":7,"grupo":"consumo-5.s7.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué argumentos apoyan las opciones B o C frente a la A? Marcá todos.","opciones":[{"id":"o1","texto":"Las experiencias compartidas suelen dar satisfacción más duradera"},{"id":"o2","texto":"Ganar tiempo libre también se asocia con bienestar"},{"id":"o3","texto":"Su auto actual funciona y vive cerca del colectivo"},{"id":"o4","texto":"Ahorrar da seguridad frente a imprevistos"},{"id":"o5","texto":"Tener el auto más nuevo del barrio garantiza la felicidad"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La decisión es de Julián, pero la evidencia ayuda a ver lo que cada opción ofrece."}},{"slug":"consumo-5.s7.p8","orden":8,"grupo":"consumo-5.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Julián escribe sus conclusiones. Marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"El auto nuevo me costaría unas 67 horas de trabajo por mes."},{"id":"s2","texto":"Si compro el auto, voy a estar igual de contento todos los años."},{"id":"s3","texto":"Con la opción B ganaría casi 7 horas libres por semana."},{"id":"s4","texto":"El dinero no tiene nada que ver con el bienestar, así que da igual."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Decidir con información no es renunciar: es elegir lo que de verdad suma.","por_opcion":{"s2":"Por la adaptación hedónica, la satisfacción suele bajar con el tiempo.","s4":"Sí tiene relación; lo que importa es cómo se usa."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"consumo-6","rama":"consumo","orden":6,"nivel":3,"titulo_es":"Empresas y cadenas de valor","bajada_es":"Alcances de emisiones, fábricas lejanas, debida diligencia, metas corporativas, calificaciones que no coinciden y empresas que se organizan distinto.","objetivos_es":["Clasificar emisiones de una empresa en alcances 1, 2 y 3","Explicar la debida diligencia en derechos humanos y ambiente en las cadenas de suministro","Evaluar la credibilidad de metas y reportes de sostenibilidad empresarial","Interpretar las calificaciones ESG y sus límites","Comparar modelos de empresa: cooperativas, empresas B y compras públicas sostenibles"],"repasa":["consumo-1","consumo-2","consumo-3","aire-suelo-6"],"requiere_tronco":3,"fuentes":["ghg-protocol","ghg-protocol-alcance3","cdp-cadena-2024","oit-rana-plaza","onu-principios-rectores","ocde-debida-diligencia","ue-csddd","ue-deforestacion","issb-s2","sbti","berg-2022-esg","sistema-b","aci-principios","inaes"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"consumo-6.s1","orden":1,"tipo":"leccion","titulo_es":"La huella de una empresa","bajada_es":"Alcances 1, 2 y 3: dónde están las emisiones de una empresa y por qué casi siempre están afuera.","minutos":11,"pasos":[{"slug":"consumo-6.s1.p1","orden":1,"grupo":"consumo-6.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tres alcances","cuerpo":["El Protocolo de Gases de Efecto Invernadero, el estándar más usado en el mundo, divide las emisiones de una empresa en tres alcances. El alcance 1 son las emisiones directas de fuentes que la empresa posee o controla, como sus calderas o sus camiones. El alcance 2 son las emisiones de generar la electricidad, el vapor o el calor que compra. El alcance 3 son todas las demás emisiones indirectas de su cadena de valor: lo que compra a proveedores, el transporte que contrata, los viajes de su personal y también el uso y el descarte de lo que vende."]},"solucion":{}},{"slug":"consumo-6.s1.p2","orden":2,"grupo":"consumo-6.s1.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿En qué alcance se cuenta cada emisión de una fábrica de galletitas?","grupos":[{"id":"g1","nombre":"Alcance 1"},{"id":"g2","nombre":"Alcance 2"},{"id":"g3","nombre":"Alcance 3"}],"items":[{"id":"i1","texto":"El gas que quema su horno"},{"id":"i2","texto":"La electricidad que compra a la red"},{"id":"i3","texto":"La harina que produce un molino proveedor"},{"id":"i4","texto":"El combustible de sus propios camiones"},{"id":"i5","texto":"El vapor que le compra a una planta vecina"},{"id":"i6","texto":"Los envases que fabrica otra empresa"},{"id":"i7","texto":"Los viajes de trabajo de su personal"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g3"},"explicacion":"Alcance 1 es lo propio, alcance 2 la energía comprada y alcance 3 todo lo demás de la cadena."}},{"slug":"consumo-6.s1.p3","orden":3,"grupo":"consumo-6.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Casi todo está afuera","cuerpo":["Para la mayoría de las empresas, el alcance 3 es la parte más grande. Según un informe de CDP de 2024, las empresas que le informan sus datos declararon emisiones en su cadena de suministro, en promedio, 26 veces mayores que las de sus propias operaciones (alcances 1 y 2). Aun así, solo el 15 % tenía una meta para el alcance 3."],"destacado":{"valor":"26 veces","texto":"mayores que las de sus operaciones propias son, en promedio, las emisiones de la cadena de suministro de las empresas que informan a CDP."}},"solucion":{}},{"slug":"consumo-6.s1.p4","orden":4,"grupo":"consumo-6.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una empresa emite 2.000 tCO₂e de alcance 1, 3.000 de alcance 2 y 45.000 de alcance 3. ¿Qué porcentaje de su huella es alcance 3?","unidad":"%","decimales":0,"contexto":"Alcance 1: 2000; alcance 2: 3000; alcance 3: 45000 tCO₂e."},"solucion":{"valor":90,"tolerancia":1,"explicacion":"45.000 ÷ 50.000 × 100 ≈ 90 %. Una empresa que solo informa sus alcances 1 y 2 muestra una parte chica de su impacto."}},{"slug":"consumo-6.s1.p4.v2","orden":4,"grupo":"consumo-6.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una empresa emite 500 tCO₂e de alcance 1, 1.500 de alcance 2 y 18.000 de alcance 3. ¿Qué porcentaje de su huella es alcance 3?","unidad":"%","decimales":0,"contexto":"Alcance 1: 500; alcance 2: 1500; alcance 3: 18000 tCO₂e."},"solucion":{"valor":90,"tolerancia":1,"explicacion":"18.000 ÷ 20.000 × 100 ≈ 90 %. Una empresa que solo informa sus alcances 1 y 2 muestra una parte chica de su impacto."}},{"slug":"consumo-6.s1.p4.v3","orden":4,"grupo":"consumo-6.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una empresa emite 10.000 tCO₂e de alcance 1, 5.000 de alcance 2 y 85.000 de alcance 3. ¿Qué porcentaje de su huella es alcance 3?","unidad":"%","decimales":0,"contexto":"Alcance 1: 10000; alcance 2: 5000; alcance 3: 85000 tCO₂e."},"solucion":{"valor":85,"tolerancia":1,"explicacion":"85.000 ÷ 100.000 × 100 ≈ 85 %. Una empresa que solo informa sus alcances 1 y 2 muestra una parte chica de su impacto."}},{"slug":"consumo-6.s1.p5","orden":5,"grupo":"consumo-6.s1.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Las operaciones propias de una empresa (alcances 1 y 2) emiten 4.000 tCO₂e. Si su cadena de suministro emite 26 veces más, ¿cuánto emite la cadena?","unidad":"tCO₂e","decimales":0,"contexto":"4000 tCO₂e propias; cadena 26 veces mayor."},"solucion":{"valor":104000,"tolerancia":2080,"explicacion":"4.000 × 26 = 104.000 tCO₂e. Por eso las políticas climáticas de una empresa que ignoran a sus proveedores se quedan cortas."}},{"slug":"consumo-6.s1.p5.v2","orden":5,"grupo":"consumo-6.s1.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Las operaciones propias de una empresa (alcances 1 y 2) emiten 1.000 tCO₂e. Si su cadena de suministro emite 10 veces más, ¿cuánto emite la cadena?","unidad":"tCO₂e","decimales":0,"contexto":"1000 tCO₂e propias; cadena 10 veces mayor."},"solucion":{"valor":10000,"tolerancia":200,"explicacion":"1.000 × 10 = 10.000 tCO₂e. Por eso las políticas climáticas de una empresa que ignoran a sus proveedores se quedan cortas."}},{"slug":"consumo-6.s1.p5.v3","orden":5,"grupo":"consumo-6.s1.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Las operaciones propias de una empresa (alcances 1 y 2) emiten 2.500 tCO₂e. Si su cadena de suministro emite 26 veces más, ¿cuánto emite la cadena?","unidad":"tCO₂e","decimales":0,"contexto":"2500 tCO₂e propias; cadena 26 veces mayor."},"solucion":{"valor":65000,"tolerancia":1300,"explicacion":"2.500 × 26 = 65.000 tCO₂e. Por eso las políticas climáticas de una empresa que ignoran a sus proveedores se quedan cortas."}},{"slug":"consumo-6.s1.p6","orden":6,"grupo":"consumo-6.s1.p6","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una empresa usa solo electricidad renovable en sus oficinas, ya resolvió su huella de carbono.","razones":[{"id":"r1","texto":"Porque el alcance 3 suele ser mucho mayor que el 2"},{"id":"r2","texto":"Porque la electricidad renovable emite más que la fósil"},{"id":"r3","texto":"Porque las oficinas no consumen electricidad"}]},"solucion":{"valor":false,"explicacion":"Eso reduce su alcance 2, pero en la mayoría de las empresas el alcance 3 es mucho mayor: lo que compran, transportan y venden.","clave":["r1"]}},{"slug":"consumo-6.s1.p7","orden":7,"grupo":"consumo-6.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Arriba y abajo de la cadena","cuerpo":["El alcance 3 tiene dos partes: aguas arriba, lo que pasa antes de la empresa, como la producción de materias primas y el transporte de lo que compra; y aguas abajo, lo que pasa después, como el uso y el descarte de lo que vende. En una marca de ropa, casi todo está aguas arriba, en el cultivo del algodón, el teñido y la costura. En una fábrica de autos o de heladeras, una gran parte está aguas abajo: la energía que consumen sus productos durante años."]},"solucion":{}},{"slug":"consumo-6.s1.p8","orden":8,"grupo":"consumo-6.s1.p8","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada empresa con dónde suele estar la mayor parte de su huella.","izquierda":[{"id":"a1","texto":"Marca de ropa"},{"id":"a2","texto":"Fábrica de autos a nafta"},{"id":"a3","texto":"Cadena de supermercados"},{"id":"a4","texto":"Petrolera"}],"derecha":[{"id":"b1","texto":"Aguas arriba: fibras, teñido y confección"},{"id":"b2","texto":"Aguas abajo: el combustible que queman los autos"},{"id":"b3","texto":"Aguas arriba: los alimentos que compra"},{"id":"b4","texto":"Aguas abajo: la quema de lo que vende"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Saber dónde está la huella dice dónde tiene que actuar cada empresa."}},{"slug":"consumo-6.s1.p9","orden":9,"grupo":"consumo-6.s1.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una empresa puede reducir su alcance 3.","items":[{"id":"i1","texto":"Mide las emisiones de sus principales proveedores"},{"id":"i2","texto":"Identifica dónde se concentran"},{"id":"i3","texto":"Acuerda metas y apoyo técnico con esos proveedores"},{"id":"i4","texto":"Los proveedores cambian procesos o energía"},{"id":"i5","texto":"Bajan las emisiones de la cadena"},{"id":"i6","texto":"Cambia de logo y declara que su cadena es verde"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Reducir el alcance 3 exige trabajar con otros, no solo dentro de la empresa."}},{"slug":"consumo-6.s1.p10","orden":10,"grupo":"consumo-6.s1.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué a las empresas les cuesta más medir el alcance 3?","opciones":[{"id":"o1","texto":"Depende de datos de proveedores y clientes que no controlan"},{"id":"o2","texto":"Porque el alcance 3 no existe en el Protocolo de GEI"},{"id":"o3","texto":"Porque está prohibido pedir datos a los proveedores"},{"id":"o4","texto":"Porque el alcance 3 siempre es cero en las empresas grandes"}]},"solucion":{"clave":["o1"],"explicacion":"Medirlo exige colaboración a lo largo de la cadena y, a veces, estimaciones.","por_opcion":{"o3":"No está prohibido: es justamente lo que se recomienda."}}},{"slug":"consumo-6.s1.p11","orden":11,"grupo":"consumo-6.s1.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este reporte de sustentabilidad y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"Informamos nuestras emisiones de alcances 1, 2 y 3."},{"id":"s2","texto":"Somos carbono neutrales porque compensamos nuestros alcances 1 y 2."},{"id":"s3","texto":"Trabajamos con nuestros 20 principales proveedores para medir sus emisiones."},{"id":"s4","texto":"El transporte que contratamos no cuenta, porque los camiones no son nuestros."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un reporte serio muestra toda la cadena, no solo lo que queda cómodo.","por_opcion":{"s2":"Deja afuera el alcance 3, que suele ser la mayor parte.","s4":"Cuenta como alcance 3."}}},{"slug":"consumo-6.s1.p12","orden":12,"grupo":"consumo-6.s1.p12","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué emisiones forman parte del alcance 3 de un banco? Marcá todas.","opciones":[{"id":"o1","texto":"Las de las empresas a las que les presta dinero"},{"id":"o2","texto":"Los viajes de trabajo de su personal"},{"id":"o3","texto":"Los servidores que alquila a un proveedor de nube"},{"id":"o4","texto":"La fabricación del papel y los equipos que compra"},{"id":"o5","texto":"El gas que quema la caldera de su propia sede"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Para un banco, las emisiones que financia suelen ser muchísimo mayores que las de sus oficinas; la caldera propia es alcance 1."}},{"slug":"consumo-6.s1.p13","orden":13,"grupo":"consumo-6.s1.p13","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de las empresas que informan a CDP tenía una meta para su alcance 3, según el informe de 2024.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":15,"banda":"lineal","explicacion":"Apenas un 15 %, aunque el alcance 3 sea en promedio 26 veces mayor que las operaciones propias."}},{"slug":"consumo-6.s1.p14","orden":14,"grupo":"consumo-6.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las emisiones directas de la empresa son el alcance {{0}}; las de la electricidad comprada, el alcance {{1}}; y las de la cadena de valor, el alcance {{2}}.","banco":[{"id":"w1","texto":"1"},{"id":"w2","texto":"2"},{"id":"w3","texto":"3"},{"id":"w4","texto":"0"},{"id":"w5","texto":"4"},{"id":"w6","texto":"5"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Los tres alcances para leer cualquier huella empresarial."}}]},{"slug":"consumo-6.s2","orden":2,"tipo":"leccion","titulo_es":"Detrás de la etiqueta","bajada_es":"Rana Plaza, los Principios Rectores de la ONU y la debida diligencia: lo que pasa con las personas en la cadena de suministro.","minutos":11,"pasos":[{"slug":"consumo-6.s2.p1","orden":1,"grupo":"consumo-6.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Rana Plaza","cuerpo":["El 24 de abril de 2013, en Bangladesh, se derrumbó el edificio Rana Plaza, donde funcionaban fábricas de ropa para marcas de todo el mundo. Murieron más de 1.100 personas y más de 2.000 resultaron heridas. El día anterior se habían detectado grietas, pero se ordenó volver a trabajar. Poco después, sindicatos y más de 80 marcas firmaron un acuerdo para inspeccionar y reparar las fábricas, con la Organización Internacional del Trabajo como presidenta neutral."]},"solucion":{}},{"slug":"consumo-6.s2.p2","orden":2,"grupo":"consumo-6.s2.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la presión por precios bajos puede terminar en tragedia.","items":[{"id":"i1","texto":"Las marcas exigen precios cada vez más bajos y entregas rápidas"},{"id":"i2","texto":"Los talleres recortan costos donde pueden"},{"id":"i3","texto":"Se posponen reparaciones y controles de seguridad"},{"id":"i4","texto":"Se ignoran las señales de riesgo en el edificio"},{"id":"i5","texto":"Ocurre una tragedia evitable"},{"id":"i6","texto":"Los precios bajos mejoran la seguridad de los talleres"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Lo que no se paga en la cadena lo terminan pagando las personas más vulnerables."}},{"slug":"consumo-6.s2.p3","orden":3,"grupo":"consumo-6.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Proteger, respetar, remediar","cuerpo":["En 2011, la ONU aprobó los Principios Rectores sobre las Empresas y los Derechos Humanos. Se apoyan en tres pilares: los Estados deben proteger los derechos humanos; las empresas deben respetarlos, lo que incluye evitar causar daños y hacer \"debida diligencia\" en sus cadenas; y las personas afectadas deben tener acceso a una reparación.","La OCDE describe la debida diligencia como un proceso: incorporar la conducta responsable en las políticas de la empresa, identificar y evaluar los riesgos en sus operaciones y cadena, detener, prevenir o mitigar los daños, hacer seguimiento, comunicar lo que se hace y reparar cuando corresponda."]},"solucion":{}},{"slug":"consumo-6.s2.p4","orden":4,"grupo":"consumo-6.s2.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada pilar de los Principios Rectores con su responsable principal.","izquierda":[{"id":"a1","texto":"Proteger"},{"id":"a2","texto":"Respetar"},{"id":"a3","texto":"Remediar"}],"derecha":[{"id":"b1","texto":"Los Estados, con leyes y controles"},{"id":"b2","texto":"Las empresas, en sus operaciones y cadenas"},{"id":"b3","texto":"Vías de reparación para las personas afectadas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Los tres pilares funcionan juntos: ninguno reemplaza a los otros."}},{"slug":"consumo-6.s2.p5","orden":5,"grupo":"consumo-6.s2.p5","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos de la debida diligencia según la OCDE.","items":[{"id":"i1","texto":"Incorporar la conducta responsable en las políticas"},{"id":"i2","texto":"Identificar y evaluar los riesgos en la cadena"},{"id":"i3","texto":"Detener, prevenir o mitigar los daños"},{"id":"i4","texto":"Hacer seguimiento de los resultados"},{"id":"i5","texto":"Comunicar lo que se hizo y reparar cuando corresponda"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Es un proceso continuo, no una auditoría de una sola vez."}},{"slug":"consumo-6.s2.p6","orden":6,"grupo":"consumo-6.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"De lo voluntario a lo obligatorio","cuerpo":["Durante años, la debida diligencia fue voluntaria. En 2024, la Unión Europea aprobó una directiva que obliga a las grandes empresas a identificar y reducir los daños a los derechos humanos y al ambiente en sus cadenas, aunque su aplicación se postergó y su alcance sigue en discusión. La Unión Europea también aprobó un reglamento que exige demostrar que productos como la soja, la carne, el café o el cacao no vienen de tierras deforestadas: eso obliga a rastrear el origen de cada cargamento, también en Argentina."]},"solucion":{}},{"slug":"consumo-6.s2.p7","orden":7,"grupo":"consumo-6.s2.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué exige el reglamento europeo sobre productos libres de deforestación a un exportador de soja?","opciones":[{"id":"o1","texto":"Demostrar que la soja no viene de tierras deforestadas"},{"id":"o2","texto":"Dejar de exportar soja a cualquier país"},{"id":"o3","texto":"Pagar un impuesto por cada tonelada exportada"},{"id":"o4","texto":"Cultivar solo soja orgánica certificada"}]},"solucion":{"clave":["o1"],"explicacion":"La trazabilidad del origen se vuelve una condición para vender.","por_opcion":{"o3":"No es un impuesto: es una obligación de trazabilidad."}}},{"slug":"consumo-6.s2.p8","orden":8,"grupo":"consumo-6.s2.p8","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una práctica de debida diligencia real o una de fachada?","grupos":[{"id":"g1","nombre":"Real"},{"id":"g2","nombre":"De fachada"}],"items":[{"id":"i1","texto":"Visitar talleres sin aviso previo con inspectores independientes"},{"id":"i2","texto":"Pedir al proveedor que firme que \"todo está bien\""},{"id":"i3","texto":"Publicar la lista de proveedores"},{"id":"i4","texto":"Auditar solo una vez y con aviso de un mes"},{"id":"i5","texto":"Tener un canal de denuncias para trabajadores de la cadena"},{"id":"i6","texto":"Cortar al proveedor sin ayudar a corregir los problemas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Cortar sin corregir puede dejar a los trabajadores peor: la debida diligencia busca mejorar la cadena."}},{"slug":"consumo-6.s2.p9","orden":9,"grupo":"consumo-6.s2.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en una cadena de 1.200 talleres se inspecciona el 15 % por año, ¿cuántos talleres se inspeccionan?","unidad":"talleres","decimales":0,"contexto":"1.200 talleres; 15 % inspeccionados por año."},"solucion":{"valor":180,"tolerancia":3.6,"explicacion":"1.200 × 15 % = 180 talleres por año: harían falta casi siete años para pasar por todos, por eso se priorizan los de mayor riesgo."}},{"slug":"consumo-6.s2.p10","orden":10,"grupo":"consumo-6.s2.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una marca no es dueña de la fábrica, no tiene ninguna responsabilidad por lo que pasa ahí.","razones":[{"id":"r1","texto":"Porque debe respetar derechos y hacer debida diligencia en su cadena"},{"id":"r2","texto":"Porque las fábricas de otros no tienen trabajadores"},{"id":"r3","texto":"Porque la responsabilidad es solo del consumidor"}]},"solucion":{"valor":false,"explicacion":"Según los Principios Rectores, las empresas deben respetar los derechos humanos también en sus cadenas, e identificar y prevenir los daños vinculados a sus operaciones y compras.","clave":["r1"]}},{"slug":"consumo-6.s2.p11","orden":11,"grupo":"consumo-6.s2.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué puede exigir una persona consumidora a una marca? Marcá todo.","opciones":[{"id":"o1","texto":"Que publique la lista de sus proveedores"},{"id":"o2","texto":"Que informe cómo controla las condiciones de trabajo"},{"id":"o3","texto":"Que explique qué hace cuando encuentra un problema"},{"id":"o4","texto":"Que muestre el origen de sus materias primas"},{"id":"o5","texto":"Que baje siempre el precio, sin importar cómo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La transparencia de la cadena es la base de cualquier compromiso creíble."}},{"slug":"consumo-6.s2.p12","orden":12,"grupo":"consumo-6.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comunicado de una marca y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"Publicamos la lista completa de nuestros talleres proveedores."},{"id":"s2","texto":"Como no somos dueños de las fábricas, lo que pase allí no es asunto nuestro."},{"id":"s3","texto":"Tenemos un canal de denuncias anónimo para trabajadores de los talleres."},{"id":"s4","texto":"Si encontramos un problema, cortamos al taller de inmediato y no hacemos nada más."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un compromiso serio mira toda la cadena y se hace cargo de lo que encuentra.","por_opcion":{"s2":"Las empresas deben hacer debida diligencia en su cadena.","s4":"Lo esperado es ayudar a corregir y reparar, no solo cortar."}}},{"slug":"consumo-6.s2.p13","orden":13,"grupo":"consumo-6.s2.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los tres pilares de los Principios Rectores son proteger, respetar y {{0}}; identificar y prevenir daños en la cadena es la debida {{1}}; y el derrumbe de Rana Plaza ocurrió en {{2}}.","banco":[{"id":"w1","texto":"remediar"},{"id":"w2","texto":"diligencia"},{"id":"w3","texto":"Bangladesh"},{"id":"w4","texto":"olvidar"},{"id":"w5","texto":"publicidad"},{"id":"w6","texto":"Brasil"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para mirar lo que hay detrás de una etiqueta."}}]},{"slug":"consumo-6.s3","orden":3,"tipo":"leccion","titulo_es":"Metas y reportes creíbles","bajada_es":"Metas basadas en ciencia, estándares de reporte y cómo distinguir un compromiso de un comunicado.","minutos":9,"pasos":[{"slug":"consumo-6.s3.p1","orden":1,"grupo":"consumo-6.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Metas basadas en ciencia","cuerpo":["La iniciativa Science Based Targets (SBTi) valida metas de reducción de emisiones de empresas según lo que haría falta para cumplir el Acuerdo de París. Pide metas de corto plazo, incluido el alcance 3 cuando es relevante, y metas de largo plazo de cero neto que se apoyen sobre todo en reducciones propias y no en compensaciones. Como viste con las metas climáticas, las metas intermedias y la calidad de los bonos son clave."]},"solucion":{}},{"slug":"consumo-6.s3.p2","orden":2,"grupo":"consumo-6.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una empresa emite 100.000 tCO₂e y se compromete a reducirlas un 42 % en 7 años. Si baja lo mismo cada año, ¿cuántas tCO₂e tiene que reducir por año? Redondeá al entero.","unidad":"tCO₂e por año","decimales":0,"contexto":"100000 tCO₂e; −42 % en 7 años."},"solucion":{"valor":6000,"tolerancia":1,"explicacion":"Meta: 100.000 × 58 % = 58.000; baja total 42.000; ÷ 7 ≈ 6.000 por año. Traducir la meta a un ritmo anual permite controlar si se cumple."}},{"slug":"consumo-6.s3.p2.v2","orden":2,"grupo":"consumo-6.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una empresa emite 50.000 tCO₂e y se compromete a reducirlas un 50 % en 10 años. Si baja lo mismo cada año, ¿cuántas tCO₂e tiene que reducir por año? Redondeá al entero.","unidad":"tCO₂e por año","decimales":0,"contexto":"50000 tCO₂e; −50 % en 10 años."},"solucion":{"valor":2500,"tolerancia":1,"explicacion":"Meta: 50.000 × 50 % = 25.000; baja total 25.000; ÷ 10 ≈ 2.500 por año. Traducir la meta a un ritmo anual permite controlar si se cumple."}},{"slug":"consumo-6.s3.p2.v3","orden":2,"grupo":"consumo-6.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una empresa emite 80.000 tCO₂e y se compromete a reducirlas un 30 % en 6 años. Si baja lo mismo cada año, ¿cuántas tCO₂e tiene que reducir por año? Redondeá al entero.","unidad":"tCO₂e por año","decimales":0,"contexto":"80000 tCO₂e; −30 % en 6 años."},"solucion":{"valor":4000,"tolerancia":1,"explicacion":"Meta: 80.000 × 70 % = 56.000; baja total 24.000; ÷ 6 ≈ 4.000 por año. Traducir la meta a un ritmo anual permite controlar si se cumple."}},{"slug":"consumo-6.s3.p3","orden":3,"grupo":"consumo-6.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reportes con reglas comunes","cuerpo":["Para que los datos de distintas empresas se puedan comparar, hacen falta reglas comunes. En 2023, el Consejo de Normas Internacionales de Sostenibilidad (ISSB) publicó la norma IFRS S2, que pide a las empresas informar sus riesgos climáticos, su estrategia y sus emisiones de alcances 1, 2 y 3. Varios países empezaron a adoptarla. Sin reglas comunes, cada empresa elige qué mostrar."]},"solucion":{}},{"slug":"consumo-6.s3.p4","orden":4,"grupo":"consumo-6.s3.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Para qué sirven normas comunes de reporte como la IFRS S2?","opciones":[{"id":"o1","texto":"Para que los datos de distintas empresas se puedan comparar"},{"id":"o2","texto":"Para que las empresas no tengan que medir sus emisiones"},{"id":"o3","texto":"Para certificar que una empresa es carbono neutral"},{"id":"o4","texto":"Para prohibir que las empresas publiquen sus datos"}]},"solucion":{"clave":["o1"],"explicacion":"Datos comparables permiten a inversores, clientes y gobiernos distinguir a quien avanza de verdad.","por_opcion":{"o3":"No certifican neutralidad: ordenan qué y cómo informar."}}},{"slug":"consumo-6.s3.p5","orden":5,"grupo":"consumo-6.s3.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿La característica hace más creíble la meta de una empresa o la debilita?","grupos":[{"id":"g1","nombre":"Más creíble"},{"id":"g2","nombre":"La debilita"}],"items":[{"id":"i1","texto":"Incluye el alcance 3"},{"id":"i2","texto":"Se cumple sobre todo comprando bonos baratos"},{"id":"i3","texto":"Tiene metas intermedias cada pocos años"},{"id":"i4","texto":"Solo tiene una meta para 2050"},{"id":"i5","texto":"Está validada por un tercero independiente"},{"id":"i6","texto":"No informa el año base ni las emisiones actuales"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las mismas preguntas que usaste para las metas de los países sirven para las empresas."}},{"slug":"consumo-6.s3.p6","orden":6,"grupo":"consumo-6.s3.p6","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una empresa que publica un reporte de sustentabilidad largo y con muchas fotos es necesariamente más sustentable.","razones":[{"id":"r1","texto":"Porque importan los datos verificables, no el diseño"},{"id":"r2","texto":"Porque los reportes cortos siempre mienten"},{"id":"r3","texto":"Porque las fotos prueban el desempeño ambiental"}]},"solucion":{"valor":false,"explicacion":"Lo que importa son los datos verificables: emisiones de los tres alcances, metas, avances y problemas reconocidos. El diseño no dice nada del desempeño.","clave":["r1"]}},{"slug":"consumo-6.s3.p7","orden":7,"grupo":"consumo-6.s3.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una empresa emitía 100.000 tCO₂e en su año base y, 3 años después, emite 90.000. ¿En qué porcentaje redujo sus emisiones hasta ahora?","unidad":"%","decimales":0,"contexto":"Año base: 100000; hoy: 90000 tCO₂e."},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"(100.000 − 90.000) ÷ 100.000 × 100 = 10 %. Comparar ese avance con la meta (42 %) y con los años que faltan muestra si va en camino."}},{"slug":"consumo-6.s3.p7.v2","orden":7,"grupo":"consumo-6.s3.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una empresa emitía 60.000 tCO₂e en su año base y, 4 años después, emite 57.000. ¿En qué porcentaje redujo sus emisiones hasta ahora?","unidad":"%","decimales":0,"contexto":"Año base: 60000; hoy: 57000 tCO₂e."},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"(60.000 − 57.000) ÷ 60.000 × 100 = 5 %. Comparar ese avance con la meta (50 %) y con los años que faltan muestra si va en camino."}},{"slug":"consumo-6.s3.p7.v3","orden":7,"grupo":"consumo-6.s3.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una empresa emitía 80.000 tCO₂e en su año base y, 2 años después, emite 64.000. ¿En qué porcentaje redujo sus emisiones hasta ahora?","unidad":"%","decimales":0,"contexto":"Año base: 80000; hoy: 64000 tCO₂e."},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"(80.000 − 64.000) ÷ 80.000 × 100 = 20 %. Comparar ese avance con la meta (40 %) y con los años que faltan muestra si va en camino."}},{"slug":"consumo-6.s3.p8","orden":8,"grupo":"consumo-6.s3.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un reporte comparable ayuda a reducir emisiones.","items":[{"id":"i1","texto":"Las empresas informan con las mismas reglas"},{"id":"i2","texto":"Inversores y clientes pueden comparar"},{"id":"i3","texto":"Las que avanzan menos quedan expuestas"},{"id":"i4","texto":"Aumenta la presión para mejorar"},{"id":"i5","texto":"Más empresas fijan y cumplen metas"},{"id":"i6","texto":"Los reportes comparables hacen innecesario medir"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La transparencia no reduce emisiones por sí sola, pero crea incentivos para hacerlo."}},{"slug":"consumo-6.s3.p9","orden":9,"grupo":"consumo-6.s3.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herramienta con lo que hace.","izquierda":[{"id":"a1","texto":"Protocolo de GEI"},{"id":"a2","texto":"SBTi"},{"id":"a3","texto":"IFRS S2"},{"id":"a4","texto":"CDP"}],"derecha":[{"id":"b1","texto":"Define cómo contar las emisiones"},{"id":"b2","texto":"Valida metas alineadas con París"},{"id":"b3","texto":"Norma para informar riesgos y emisiones"},{"id":"b4","texto":"Recoge y publica datos ambientales de empresas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Contar, fijar metas, informar y publicar: cuatro piezas de la rendición de cuentas."}},{"slug":"consumo-6.s3.p10","orden":10,"grupo":"consumo-6.s3.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene buscar en el reporte de una empresa? Marcá todo.","opciones":[{"id":"o1","texto":"Emisiones de los tres alcances"},{"id":"o2","texto":"Metas con año base y metas intermedias"},{"id":"o3","texto":"El avance real respecto de esas metas"},{"id":"o4","texto":"Verificación por un tercero independiente"},{"id":"o5","texto":"Solo frases como \"comprometidos con el planeta\""}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Números, metas, avances y verificación: lo demás es comunicación."}},{"slug":"consumo-6.s3.p11","orden":11,"grupo":"consumo-6.s3.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este anuncio corporativo y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"Nuestra meta fue validada por la iniciativa Science Based Targets."},{"id":"s2","texto":"Seremos cero neto en 2050; mientras tanto, no fijaremos metas intermedias."},{"id":"s3","texto":"Informamos con la norma IFRS S2."},{"id":"s4","texto":"Nuestra meta cubre solo las oficinas, que son el 2 % de nuestras emisiones."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Leer metas empresariales es aplicar el mismo ojo crítico que con las metas de los países.","por_opcion":{"s2":"Sin metas intermedias no hay forma de controlar el avance.","s4":"Deja afuera casi toda la huella."}}},{"slug":"consumo-6.s3.p12","orden":12,"grupo":"consumo-6.s3.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La iniciativa que valida metas empresariales alineadas con París es la {{0}}; la norma de reporte climático publicada en 2023 es la IFRS {{1}}; y para seguir el avance hacen falta metas {{2}}.","banco":[{"id":"w1","texto":"SBTi"},{"id":"w2","texto":"S2"},{"id":"w3","texto":"intermedias"},{"id":"w4","texto":"ONU"},{"id":"w5","texto":"S9"},{"id":"w6","texto":"secretas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres herramientas para evaluar compromisos corporativos."}}]},{"slug":"consumo-6.s4","orden":4,"tipo":"leccion","titulo_es":"Calificaciones que no coinciden","bajada_es":"Qué miden las calificaciones ESG, por qué cambian tanto según quién califica y cómo leerlas.","minutos":10,"pasos":[{"slug":"consumo-6.s4.p1","orden":1,"grupo":"consumo-6.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"ESG","cuerpo":["Las calificaciones ESG evalúan a las empresas en temas ambientales (E), sociales (S) y de gobierno corporativo (G). Las usan inversores para elegir dónde poner su dinero. Pero un estudio publicado en 2022 comparó seis de las calificadoras más conocidas y encontró que coinciden poco: la misma empresa puede estar entre las mejores para una y entre las peores para otra. La mayor parte de la diferencia viene de cómo mide cada una (56 %), después de qué temas incluye (38 %) y, en menor medida, de cuánto pesa cada tema (6 %)."],"datos":{"tipo":"barras","titulo":"De dónde viene la diferencia entre calificaciones ESG","unidad":"% de la divergencia","filas":[{"etiqueta":"Cómo se mide","valor":56},{"etiqueta":"Qué temas se incluyen","valor":38},{"etiqueta":"Cuánto pesa cada tema","valor":6}],"nota":"Berg, Kölbel y Rigobon (2022)."}},"solucion":{}},{"slug":"consumo-6.s4.p2","orden":2,"grupo":"consumo-6.s4.p2","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de la diferencia entre calificaciones ESG viene de cómo mide cada calificadora.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":56,"banda":"lineal","explicacion":"Un 56 %, según el estudio de 2022: más de la mitad de la divergencia es de medición, no de opinión sobre qué importa."}},{"slug":"consumo-6.s4.p3","orden":3,"grupo":"consumo-6.s4.p3","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada letra de ESG con un tema que evalúa.","izquierda":[{"id":"a1","texto":"E (ambiental)"},{"id":"a2","texto":"S (social)"},{"id":"a3","texto":"G (gobierno)"}],"derecha":[{"id":"b1","texto":"Emisiones, agua y residuos"},{"id":"b2","texto":"Condiciones de trabajo y comunidades"},{"id":"b3","texto":"Transparencia, directorio y anticorrupción"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Tres dimensiones que se evalúan juntas, a veces mezclando cosas muy distintas."}},{"slug":"consumo-6.s4.p4","orden":4,"grupo":"consumo-6.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"¿Riesgo para la empresa o impacto en el mundo?","cuerpo":["Muchas calificaciones ESG miden sobre todo cuánto le pueden afectar los temas ambientales y sociales a la empresa: por ejemplo, si una sequía puede dañar su negocio. Eso se llama materialidad simple. Otra mirada, la doble materialidad, suma también cuánto impacta la empresa en el ambiente y en las personas. Una empresa puede tener \"bajo riesgo\" para sus inversores y, a la vez, un impacto grande en el mundo."]},"solucion":{}},{"slug":"consumo-6.s4.p5","orden":5,"grupo":"consumo-6.s4.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿La pregunta corresponde al riesgo para la empresa o al impacto de la empresa?","grupos":[{"id":"g1","nombre":"Riesgo para la empresa"},{"id":"g2","nombre":"Impacto de la empresa"}],"items":[{"id":"i1","texto":"¿Puede una sequía afectar su producción?"},{"id":"i2","texto":"¿Cuánto contamina el río donde vuelca sus efluentes?"},{"id":"i3","texto":"¿Puede una nueva ley aumentar sus costos?"},{"id":"i4","texto":"¿Cómo afecta a las comunidades cercanas?"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"La doble materialidad mira las dos direcciones a la vez."}},{"slug":"consumo-6.s4.p6","orden":6,"grupo":"consumo-6.s4.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué una misma empresa puede tener calificaciones ESG muy distintas?","opciones":[{"id":"o1","texto":"Porque cada calificadora mide, incluye y pesa temas distinto"},{"id":"o2","texto":"Porque las calificadoras siempre se equivocan a propósito"},{"id":"o3","texto":"Porque las empresas cambian todos los días"},{"id":"o4","texto":"Porque solo una de las calificadoras usa datos reales"}]},"solucion":{"clave":["o1"],"explicacion":"Antes de usar una calificación, conviene saber qué mide y cómo.","por_opcion":{"o3":"La diferencia aparece aun calificando a la misma empresa el mismo año."}}},{"slug":"consumo-6.s4.p7","orden":7,"grupo":"consumo-6.s4.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una calificadora le pone 80 puntos sobre 100 a una empresa y otra le pone 35. ¿Cuántos puntos de diferencia hay?","unidad":"puntos","decimales":0,"contexto":"Calificación A: 80; calificación B: 35."},"solucion":{"valor":45,"tolerancia":0.9,"explicacion":"80 − 35 = 45 puntos. Con diferencias así, la misma empresa puede entrar o quedar afuera de un fondo \"sustentable\" según qué calificación se use."}},{"slug":"consumo-6.s4.p7.v2","orden":7,"grupo":"consumo-6.s4.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una calificadora le pone 72 puntos sobre 100 a una empresa y otra le pone 50. ¿Cuántos puntos de diferencia hay?","unidad":"puntos","decimales":0,"contexto":"Calificación A: 72; calificación B: 50."},"solucion":{"valor":22,"tolerancia":0.5,"explicacion":"72 − 50 = 22 puntos. Con diferencias así, la misma empresa puede entrar o quedar afuera de un fondo \"sustentable\" según qué calificación se use."}},{"slug":"consumo-6.s4.p7.v3","orden":7,"grupo":"consumo-6.s4.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una calificadora le pone 90 puntos sobre 100 a una empresa y otra le pone 40. ¿Cuántos puntos de diferencia hay?","unidad":"puntos","decimales":0,"contexto":"Calificación A: 90; calificación B: 40."},"solucion":{"valor":50,"tolerancia":1,"explicacion":"90 − 40 = 50 puntos. Con diferencias así, la misma empresa puede entrar o quedar afuera de un fondo \"sustentable\" según qué calificación se use."}},{"slug":"consumo-6.s4.p8","orden":8,"grupo":"consumo-6.s4.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una calificación ESG alta garantiza que la empresa tiene poco impacto ambiental.","razones":[{"id":"r1","texto":"Porque muchas miden riesgo para la empresa, no impacto"},{"id":"r2","texto":"Porque las calificaciones ESG no miden nada ambiental"},{"id":"r3","texto":"Porque todas las calificadoras dan el mismo resultado"}]},"solucion":{"valor":false,"explicacion":"Muchas calificaciones miden sobre todo el riesgo para la empresa, no su impacto en el mundo. Y distintas calificadoras pueden dar resultados muy distintos.","clave":["r1"]}},{"slug":"consumo-6.s4.p9","orden":9,"grupo":"consumo-6.s4.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una calificación poco clara puede desviar inversiones.","items":[{"id":"i1","texto":"Una calificadora mide sobre todo riesgos para la empresa"},{"id":"i2","texto":"Una petrolera bien gestionada obtiene buena nota"},{"id":"i3","texto":"Un fondo \"sustentable\" la incluye por esa nota"},{"id":"i4","texto":"Inversores creen que financian algo de bajo impacto"},{"id":"i5","texto":"El dinero va a actividades con alto impacto ambiental"},{"id":"i6","texto":"La calificación mide el impacto directo en el clima"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Por eso importan las etiquetas claras y la doble materialidad."}},{"slug":"consumo-6.s4.p10","orden":10,"grupo":"consumo-6.s4.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"Antes de confiar en una calificación ESG, ¿qué conviene preguntar? Marcá todo.","opciones":[{"id":"o1","texto":"¿Mide riesgo para la empresa, impacto, o ambos?"},{"id":"o2","texto":"¿Qué temas incluye y cuánto pesa cada uno?"},{"id":"o3","texto":"¿De dónde salen los datos?"},{"id":"o4","texto":"¿Qué dicen otras calificadoras de la misma empresa?"},{"id":"o5","texto":"¿Qué color tiene el logo de la calificadora?"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Una nota sin su método es un número sin contexto."}},{"slug":"consumo-6.s4.p11","orden":11,"grupo":"consumo-6.s4.p11","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas formas de evaluar a una empresa, de la más informativa a la menos.","items":[{"id":"i1","texto":"Datos verificados de emisiones y metas, con doble materialidad"},{"id":"i2","texto":"Varias calificaciones ESG comparadas, con su método"},{"id":"i3","texto":"Una sola calificación ESG, sin saber qué mide"},{"id":"i4","texto":"El eslogan de la empresa"}],"extremos":["Más informativa","Menos informativa"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuanto más transparente el método y más directos los datos, mejor la evaluación.","valores":{"i1":"la más informativa","i2":"buena","i3":"débil","i4":"la menos informativa"}}},{"slug":"consumo-6.s4.p12","orden":12,"grupo":"consumo-6.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta publicidad de un fondo de inversión y marcá lo que conviene revisar.","segmentos":[{"id":"s1","texto":"Informamos qué calificadora usamos y cómo mide."},{"id":"s2","texto":"Nuestras empresas tienen nota ESG alta, así que no contaminan."},{"id":"s3","texto":"Publicamos las emisiones de las empresas en las que invertimos."},{"id":"s4","texto":"Todas las calificadoras coinciden en nuestras empresas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los fondos \"verdes\" también necesitan ser leídos con lupa.","por_opcion":{"s2":"Una nota alta puede reflejar bajo riesgo para la empresa, no bajo impacto.","s4":"Las calificaciones ESG suelen coincidir poco."}}},{"slug":"consumo-6.s4.p13","orden":13,"grupo":"consumo-6.s4.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Evaluar temas ambientales, sociales y de gobierno es una calificación {{0}}; mirar el riesgo para la empresa y también su impacto es la doble {{1}}; y la mayor parte de la divergencia entre calificadoras viene de cómo {{2}}.","banco":[{"id":"w1","texto":"ESG"},{"id":"w2","texto":"materialidad"},{"id":"w3","texto":"miden"},{"id":"w4","texto":"ISO"},{"id":"w5","texto":"contabilidad"},{"id":"w6","texto":"venden"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para leer las calificaciones de sostenibilidad."}}]},{"slug":"consumo-6.s5","orden":5,"tipo":"leccion","titulo_es":"Otras formas de empresa","bajada_es":"Cooperativas, empresas B, economía social y compras públicas: organizar la producción de otra manera.","minutos":11,"pasos":[{"slug":"consumo-6.s5.p1","orden":1,"grupo":"consumo-6.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cooperativas","cuerpo":["Una cooperativa es una empresa de propiedad conjunta de sus integrantes, que la gestionan de forma democrática: en general, una persona, un voto, sin importar cuánto capital aportó. La Alianza Cooperativa Internacional define siete principios: adhesión voluntaria y abierta, gestión democrática, participación económica de los asociados, autonomía, educación e información, cooperación entre cooperativas e interés por la comunidad. En Argentina las regula el Instituto Nacional de Asociativismo y Economía Social (INAES), y son parte importante de servicios como la electricidad en muchos pueblos, del agro y del reciclado."]},"solucion":{}},{"slug":"consumo-6.s5.p2","orden":2,"grupo":"consumo-6.s5.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una cooperativa tiene un excedente de 3.000.000 pesos. La asamblea decide repartir el 70 % en partes iguales entre sus 60 asociados y reinvertir el resto. ¿Cuánto recibe cada asociado?","unidad":"pesos","decimales":0,"contexto":"Excedente de 3000000; 70 % repartido entre 60."},"solucion":{"valor":35000,"tolerancia":700,"explicacion":"3.000.000 × 70 % = 2.100.000; ÷ 60 = 35.000 pesos. La decisión la toma la asamblea, con un voto por persona."}},{"slug":"consumo-6.s5.p2.v2","orden":2,"grupo":"consumo-6.s5.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una cooperativa tiene un excedente de 1.200.000 pesos. La asamblea decide repartir el 50 % en partes iguales entre sus 40 asociados y reinvertir el resto. ¿Cuánto recibe cada asociado?","unidad":"pesos","decimales":0,"contexto":"Excedente de 1200000; 50 % repartido entre 40."},"solucion":{"valor":15000,"tolerancia":300,"explicacion":"1.200.000 × 50 % = 600.000; ÷ 40 = 15.000 pesos. La decisión la toma la asamblea, con un voto por persona."}},{"slug":"consumo-6.s5.p2.v3","orden":2,"grupo":"consumo-6.s5.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una cooperativa tiene un excedente de 5.000.000 pesos. La asamblea decide repartir el 60 % en partes iguales entre sus 100 asociados y reinvertir el resto. ¿Cuánto recibe cada asociado?","unidad":"pesos","decimales":0,"contexto":"Excedente de 5000000; 60 % repartido entre 100."},"solucion":{"valor":30000,"tolerancia":600,"explicacion":"5.000.000 × 60 % = 3.000.000; ÷ 100 = 30.000 pesos. La decisión la toma la asamblea, con un voto por persona."}},{"slug":"consumo-6.s5.p3","orden":3,"grupo":"consumo-6.s5.p3","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada principio cooperativo con un ejemplo.","izquierda":[{"id":"a1","texto":"Gestión democrática"},{"id":"a2","texto":"Adhesión voluntaria y abierta"},{"id":"a3","texto":"Educación e información"},{"id":"a4","texto":"Interés por la comunidad"}],"derecha":[{"id":"b1","texto":"Una persona, un voto en la asamblea"},{"id":"b2","texto":"Puede sumarse quien acepte las responsabilidades"},{"id":"b3","texto":"Capacitaciones para asociados y comunidad"},{"id":"b4","texto":"Apoyar proyectos del pueblo donde funciona"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Los principios distinguen a una cooperativa de una empresa común."}},{"slug":"consumo-6.s5.p4","orden":4,"grupo":"consumo-6.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Empresas B y economía social","cuerpo":["Las Empresas B son empresas con fines de lucro que se certifican por su impacto social y ambiental y se comprometen a considerar a trabajadores, comunidad y ambiente en sus decisiones. En América Latina las impulsa Sistema B, que nació en 2012 en Argentina, Chile y Colombia. La economía social incluye además mutuales, empresas recuperadas por sus trabajadores y emprendimientos asociativos. Ninguna forma jurídica garantiza por sí sola buenas prácticas, pero cambian quién decide y para qué."]},"solucion":{}},{"slug":"consumo-6.s5.p5","orden":5,"grupo":"consumo-6.s5.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué modelo de empresa describe cada caso?","grupos":[{"id":"g1","nombre":"Cooperativa"},{"id":"g2","nombre":"Empresa B"},{"id":"g3","nombre":"Empresa convencional"}],"items":[{"id":"i1","texto":"Los vecinos son dueños de la distribuidora eléctrica del pueblo"},{"id":"i2","texto":"Una empresa con fines de lucro certificada por su impacto"},{"id":"i3","texto":"Una sociedad anónima que decide según el capital de cada accionista"},{"id":"i4","texto":"Recicladores organizados que deciden en asamblea"},{"id":"i5","texto":"Una marca que cambió su estatuto para considerar al ambiente"},{"id":"i6","texto":"Una empresa que solo busca maximizar ganancias"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Quién es dueño y cómo se decide cambia las prioridades de una empresa."}},{"slug":"consumo-6.s5.p6","orden":6,"grupo":"consumo-6.s5.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una cooperativa eléctrica puede llevar servicios a un pueblo.","items":[{"id":"i1","texto":"Los vecinos forman una cooperativa para tener electricidad"},{"id":"i2","texto":"Deciden en asamblea cómo usar los excedentes"},{"id":"i3","texto":"Reinvierten en la red y en nuevos servicios"},{"id":"i4","texto":"El servicio llega a zonas que una empresa no consideraba rentables"},{"id":"i5","texto":"El pueblo gana acceso a energía y otros servicios"},{"id":"i6","texto":"La cooperativa reparte todo el excedente y no reinvierte nada"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cuando los usuarios son dueños, la prioridad puede ser el servicio y no solo la ganancia."}},{"slug":"consumo-6.s5.p7","orden":7,"grupo":"consumo-6.s5.p7","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para formar una cooperativa.","items":[{"id":"i1","texto":"Reunir a las personas interesadas y definir el objetivo"},{"id":"i2","texto":"Preparar el proyecto de estatuto"},{"id":"i3","texto":"Realizar la asamblea constitutiva"},{"id":"i4","texto":"Tramitar la autorización y la matrícula ante el INAES"},{"id":"i5","texto":"Funcionar con asambleas y balances periódicos"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una cooperativa nace de un acuerdo colectivo y se sostiene con participación."}},{"slug":"consumo-6.s5.p8","orden":8,"grupo":"consumo-6.s5.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué distingue a una cooperativa de una sociedad anónima tradicional?","opciones":[{"id":"o1","texto":"Sus integrantes deciden con un voto por persona"},{"id":"o2","texto":"Que no puede tener ingresos ni excedentes"},{"id":"o3","texto":"Que no puede tener trabajadores ni clientes"},{"id":"o4","texto":"Que no paga impuestos en ningún caso"}]},"solucion":{"clave":["o1"],"explicacion":"En la cooperativa, el poder de decisión no depende de cuánto capital se aportó.","por_opcion":{"o3":"Tiene ambos; lo distintivo es la propiedad y el voto."}}},{"slug":"consumo-6.s5.p9","orden":9,"grupo":"consumo-6.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El poder de las compras públicas","cuerpo":["Los gobiernos compran muchísimo: comida para escuelas y hospitales, vehículos, papel, obras. Las compras públicas sostenibles incluyen criterios ambientales y sociales en esas compras, por ejemplo priorizando productos de menor impacto, a cooperativas o a la agricultura familiar. Como el Estado es un comprador enorme, sus criterios pueden mover mercados enteros."]},"solucion":{}},{"slug":"consumo-6.s5.p10","orden":10,"grupo":"consumo-6.s5.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un municipio gasta 500.000.000 pesos por año en alimentos para escuelas. Si decide comprar el 30 % a cooperativas y productores familiares locales, ¿cuánto dinero se destina a ellos?","unidad":"pesos","decimales":0,"contexto":"500000000 pesos; 30 % a productores locales."},"solucion":{"valor":150000000,"tolerancia":3000000,"explicacion":"500.000.000 × 30 % = 150.000.000 pesos por año que quedan en la economía local. Valores de ejemplo."}},{"slug":"consumo-6.s5.p10.v2","orden":10,"grupo":"consumo-6.s5.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un municipio gasta 200.000.000 pesos por año en alimentos para escuelas. Si decide comprar el 25 % a cooperativas y productores familiares locales, ¿cuánto dinero se destina a ellos?","unidad":"pesos","decimales":0,"contexto":"200000000 pesos; 25 % a productores locales."},"solucion":{"valor":50000000,"tolerancia":1000000,"explicacion":"200.000.000 × 25 % = 50.000.000 pesos por año que quedan en la economía local. Valores de ejemplo."}},{"slug":"consumo-6.s5.p10.v3","orden":10,"grupo":"consumo-6.s5.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un municipio gasta 800.000.000 pesos por año en alimentos para escuelas. Si decide comprar el 20 % a cooperativas y productores familiares locales, ¿cuánto dinero se destina a ellos?","unidad":"pesos","decimales":0,"contexto":"800000000 pesos; 20 % a productores locales."},"solucion":{"valor":160000000,"tolerancia":3200000,"explicacion":"800.000.000 × 20 % = 160.000.000 pesos por año que quedan en la economía local. Valores de ejemplo."}},{"slug":"consumo-6.s5.p11","orden":11,"grupo":"consumo-6.s5.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una empresa que se declara cooperativa o B tiene garantizado un impacto positivo.","razones":[{"id":"r1","texto":"Porque el impacto depende de las prácticas, no solo de la forma jurídica"},{"id":"r2","texto":"Porque las cooperativas no pueden tener impacto"},{"id":"r3","texto":"Porque las Empresas B no existen"}]},"solucion":{"valor":false,"explicacion":"La forma jurídica cambia quién decide y para qué, pero el impacto real depende de sus prácticas. También hay que medirlas y controlarlas.","clave":["r1"]}},{"slug":"consumo-6.s5.p12","orden":12,"grupo":"consumo-6.s5.p12","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué pueden hacer las personas, además de comprar, para influir en las empresas? Marcá todo.","opciones":[{"id":"o1","texto":"Participar en cooperativas de su comunidad"},{"id":"o2","texto":"Pedir transparencia sobre la cadena de suministro"},{"id":"o3","texto":"Apoyar compras públicas con criterios sostenibles"},{"id":"o4","texto":"Elegir bancos o fondos que informen su impacto"},{"id":"o5","texto":"Dejar las decisiones solo en manos de la publicidad"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Como trabajadores, vecinos, votantes e inversores, las personas tienen más herramientas que la góndola."}},{"slug":"consumo-6.s5.p13","orden":13,"grupo":"consumo-6.s5.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este texto sobre economía social y marcá lo que conviene revisar.","segmentos":[{"id":"